type step struct {
	g    int    // 哪个 goroutine
	op   string // load / store
	note string // 备注：这一步为什么危险
}

// runTrace：真的按指令序列执行一遍，返回终值与完成的自增次数。
func runTrace(ts []step) (int64, int) {
	mem := int64(0)
	reg := map[int]int64{1: 0, 2: 0}
	done := 0
	for _, s := range ts {
		if s.op == "l" {
			reg[s.g] = mem
		} else {
