// =====================================================================
// W53 d02：并发写 map 是 fatal，不是 race —— 连「错个数」的机会都不给你。
//
// map 内部有个 hashWriting 标志位：写操作开始前置上，若发现自己进来时已经被别人
// 置着，说明两个 goroutine 同时在写 —— runtime.throw 直接毙掉整个进程。
// 这不是 panic，recover 接不住；也不是一等 -race 才有 -race 只是旁观者，
// runtime 自己就是哨兵。崩法真跑在 d02_fatal_test.go，本文件 stdout 全字节确定。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d02
// 真崩复跑： go test -count=1 -run TestConcurrentMapWrites ./lab/s13/d02
// 插桩复跑： CGO_ENABLED=1 go test -race -count=1 -run TestConcurrentMapWrites ./lab/s13/d02
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"sync"
)

const (
	gorens = 8    // 每个版本都是 8 个 goroutine
	perG   = 1000 // 每人写 1000 个专属键：gorens*perG = 8000，终态可全等校验
)

var yes = map[bool]string{true: "是", false: "否"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// key：键空间按 goroutine 划段互不重叠，终态确定性 = 8000 键、和 8000。
func key(g, i int) int { return g*perG + i }

// ---------- 修复 A：Mutex 包整个 map ----------
func fixMutex() (int, int64) {
	var mu sync.Mutex
	m := make(map[int]int)
	var wg sync.WaitGroup
	for g := 0; g < gorens; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for i := 0; i < perG; i++ {
				mu.Lock()
				m[key(g, i)] = 1
				mu.Unlock()
			}
		}(g)
	}
	wg.Wait()
	return len(m), sum(m)
}

// ---------- 修复 B：每 goroutine 私有分片，最后串行归并 ----------
func fixShard() (int, int64) {
	shards := make([]map[int]int, gorens)
	for g := range shards {
		shards[g] = make(map[int]int)
	}
	var wg sync.WaitGroup
	for g := 0; g < gorens; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for i := 0; i < perG; i++ {
				shards[g][key(g, i)] = 1 // 私有 map，全程零共享写
			}
		}(g)
	}
	wg.Wait()
	merged := make(map[int]int, gorens*perG)
	for g := 0; g < gorens; g++ { // 归并阶段是单线程，随便写
		for k, v := range shards[g] {
			merged[k] = v
		}
	}
	return len(merged), sum(merged)
}

// ---------- 修复 C：channel 串行化，map 从头到尾只有一个主人 ----------
type writeOp struct {
	k, v int
}

func fixChan() (int, int64) {
	ops := make(chan writeOp, gorens) // 小缓冲只是攒着，不改变串行本质
	m := make(map[int]int)
	done := make(chan struct{})
	go func() { // 唯一写者：map 归这根 goroutine 独占
		for op := range ops {
			m[op.k] = op.v
		}
		close(done)
	}()
	var wg sync.WaitGroup
	for g := 0; g < gorens; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for i := 0; i < perG; i++ {
				ops <- writeOp{key(g, i), 1} // 发送即交接所有权，不碰 map
			}
		}(g)
	}
	wg.Wait()
	close(ops) // 必须有人 close：否则接收方 range 永远等（d04 详讲）
	<-done
	return len(m), sum(m)
}

func sum(m map[int]int) (s int64) {
	for _, v := range m {
		s += int64(v)
	}
	return
}

