// =====================================================================
// W53 d04：channel vs Mutex 各自该用在哪（S13 判据②）
//
// 同一道题「聚合 8 个账户的 *_cents」用两种写法并排跑：
//   · channel 路径 = 所有权转移：每个 goroutine 独占一个账户的结果，
//     把整份结果作为「值」发出去，接收方累加；从头到尾没有共享内存 → 不需要锁。
//   · Mutex 路径  = 共享读改写：8 个 goroutine 往同一张 map 里累加，
//     读-改-写整段被锁保护。
// 两条路径逐账户对拍，diff 必须全 0（结果一致），差别只在「同步放在哪」。
//
// 再逐条演示三种崩法，各自打印「被卡住」的确定证据（绝不真把进程挂死）：
//   ❌ 忘 close        → 接收方 range 永不结束：用带固定阈值的 select 命中「仍在等」。
//   ❌ defer Unlock 漏 → 第二次拿锁进不去：同样用带固定阈值的 select 命中「阻塞」。
//   ❌ 复制含 Mutex 的结构体 → 锁失效：go vet 的 copylocks 真能抓，逐字贴真实 vet 输出。
//
// 收口给「所有权转移用 channel、共享读改写用 Mutex」这条判据的可判定表述。
//
// 本机跑法：cd homecube/server && go run ./lab/s13/d04
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

// stuckThreshold 是演示「永远等」用的固定阈值：打印的是「超时命中」这个确定结论，
// 不打印真实耗时；值固定 → 两次跑字节一致。
const stuckThreshold = 120 * time.Millisecond

var famID = "aaaaaaaa-0000-4000-8000-000000000001"

// 金额一律 *_cents 整数；符号表只有服务端这一份（沿用 W46/W47 口径）。
var sign = map[string]int64{"income": 1, "expense": -1, "refund": 1}

type Account struct {
	Code         string
	Name         string
	OpeningCents int64
}

type Txn struct {
	Account     string
	Kind        string
	AmountCents int64
}

// 8 个账户，期初各不相同；交易按账户 code 分布。
var accounts = []Account{
	{"ACC-01", "现金钱包", 120000},
	{"ACC-02", "储蓄卡", 860000},
	{"ACC-03", "信用卡", -45000},
	{"ACC-04", "房贷账户", -3200000},
	{"ACC-05", "证券", 540000},
	{"ACC-06", "公积金", 300000},
	{"ACC-07", "外币", 78000},
	{"ACC-08", "家长代管", 15000},
}

// 金额一律存正数「面值」，方向由 sign 表决定；两条路径共用同一份符号，绝不自写第二套。
var txns = []Txn{
	{"ACC-01", "income", 860000}, {"ACC-01", "expense", 120000}, {"ACC-01", "refund", 3000},
	{"ACC-02", "income", 1200000}, {"ACC-02", "expense", 330000},
	{"ACC-03", "expense", 50000}, {"ACC-03", "refund", 8000},
	{"ACC-04", "expense", 800000},
	{"ACC-05", "income", 42000}, {"ACC-05", "expense", 15000},
	{"ACC-06", "income", 240000},
	{"ACC-07", "income", 9000}, {"ACC-07", "refund", 1500},
	{"ACC-08", "expense", 4000}, {"ACC-08", "income", 5000},
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string {
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}
func codesOf(accts []Account) []string {
	c := make([]string, len(accts))
	for i, a := range accts {
		c[i] = a.Code
	}
	sort.Strings(c)
	return c
}

// ---- channel 路径：所有权转移。每个 goroutine 独占一个账户，算完整份结果再发值。 ----
func aggregateWithChannel() map[string]int64 {
	type job struct{ acc Account }
	in := make(chan job, len(accounts))
	out := make(chan map[string]int64, len(accounts))

	// 工人：从 in 领一个账户（拿到即独占所有权，无人再改它），算完把结果 map 发进 out。
	var workers sync.WaitGroup
	for w := 0; w < 4; w++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for j := range in { // in 被 close 后 range 才会结束
				res := j.acc.OpeningCents
				for _, t := range txns {
					if t.Account == j.acc.Code {
						res += sign[t.Kind] * t.AmountCents // 方向查符号表，面值取正
					}
				}
				out <- map[string]int64{j.acc.Code: res} // 发整份结果，接收方只做拼装
			}
		}()
	}

	go func() {
		for _, a := range accounts {
			in <- job{a}
		}
		close(in) // ← 生产侧发完必须 close，否则工人的 range in 永不结束
	}()

	go func() { workers.Wait(); close(out) }() // 工人都退出后 close out，消费侧 range 才能收尾

	got := map[string]int64{}
	for m := range out { // out 被 close 后 range 结束
		for k, v := range m {
			got[k] = v
		}
	}
	return got
}

// ---- Mutex 路径：共享读改写。所有 goroutine 往同一张 balance map 累加。 ----
func aggregateWithMutex() map[string]int64 {
	balance := map[string]int64{}
	for _, a := range accounts {
		balance[a.Code] = a.OpeningCents // 先铺期初（单线程，无竞争）
	}
	var mu sync.Mutex
	var wg sync.WaitGroup
	for _, a := range accounts {
		wg.Add(1)
		go func(acc Account) { // acc 作参数传入：闭包捕获循环变量会与后续迭代竞争
			defer wg.Done()
			var delta int64
			for _, t := range txns { // 先在本地算，把读-改-写的临界区压到最短
				if t.Account == acc.Code {
					delta += sign[t.Kind] * t.AmountCents
				}
			}
			mu.Lock() // 共享 map 的读改写整段上锁
			balance[acc.Code] += delta
			mu.Unlock()
		}(a)
	}
	wg.Wait()
	return balance
}

// 逐账户对拍两条路径。
func diffTable(ch, mx map[string]int64) int {
	fmt.Printf("  %-8s %-14s %-14s %-10s %s\n", "code", "channel 路径", "mutex 路径", "diff", "判定")
	bad := 0
	for _, c := range codesOf(accounts) {
		d := mx[c] - ch[c]
		mark := "✅ 一致"
		if d != 0 {
			mark, bad = "❌ 不一致", bad+1
		}
		fmt.Printf("  %-8s %-14s %-14s %-10s %s\n", c, money(ch[c]), money(mx[c]), money(d), mark)
	}
	return bad
}

func main() {
	hdr(fmt.Sprintf("1. 场景：%d 个账户 × %d 笔流水（family_id=%s），金额全 *_cents 整数", len(accounts), len(txns), famID))
	fmt.Printf("  符号表（服务端唯一一份）%v\n", sign)
	fmt.Println("  同一个「聚合余额」的活儿，两种并发写法并排跑；结果必须逐账户 diff 全 0。")
	fmt.Println("  每笔流水按符号折算的家庭增量（两条路径都吃同一份数据、同一张符号表）：")
	fmt.Printf("  %-8s %-9s %-8s %-10s %s\n", "account", "kind", "面值", "sign", "折算增量")
	for _, t := range txns {
		fmt.Printf("  %-8s %-9s %-8s %-10d %s\n", t.Account, t.Kind, money(t.AmountCents), sign[t.Kind], money(sign[t.Kind]*t.AmountCents))
	}

	chRes := aggregateWithChannel()
	mxRes := aggregateWithMutex()

	hdr("2. ✅ 两条路径逐账户对拍：diff 全 0")
	fmt.Println("  每账户：期初 + 名下折算增量之和 = 期末余额；channel 路径与 mutex 路径各算一遍。")
	fmt.Printf("  %-8s %-12s %-10s %-10s %s\n", "code", "账户", "期初", "channel期末", "（下面接对拍表）")
	opening := map[string]int64{}
	for _, a := range accounts {
		opening[a.Code] = a.OpeningCents
	}
	for _, c := range codesOf(accounts) {
		var nm string
		for _, a := range accounts {
			if a.Code == c {
				nm = a.Name
			}
		}
		fmt.Printf("  %-8s %-12s %-10s %-10s %s\n", c, nm, money(opening[c]), money(chRes[c]), "—")
	}
	bad := diffTable(chRes, mxRes)
	sum := int64(0)
	for _, c := range codesOf(accounts) {
		sum += chRes[c]
	}
	fmt.Printf("  非 0 差值 %d/%d 处；全体账户合计 %s 元 —— 结果与「同步放在哪」无关，只与「有没有算重/漏算」有关。\n", bad, len(accounts), money(sum))

	// ------- 崩法 A：忘 close → 接收方永远等（用固定阈值 select 命中「仍在等」） -------
	hdr("3. ❌ 崩法 A：生产侧发完不 close → 接收方 range 永不结束")
	fmt.Println("  复现：缓冲 chan(cap=8)，生产者把 8 份结果塞满后就 return，唯独忘了 close。")
	agg := make(chan map[string]int64, len(accounts))
	for _, c := range codesOf(accounts) {
		agg <- map[string]int64{c: chRes[c]} // 塞满 8 条，之后既不 close 也不发
	}
	got, timedOut := 0, false
recvLoop:
	for {
		select {
		case _, ok := <-agg:
			if !ok { // 只有 close 后才会走到这里；本例永不 close
				break recvLoop
			}
			got++
		case <-time.After(stuckThreshold): // 缓冲区被抽干后，第 9 次接收再无数据 → 命中超时
			timedOut = true
			break recvLoop
		}
	}
	fmt.Printf("  已收到 %d/%d 条；随后在固定阈值 %s 内第 %d 次接收【超时命中】—— 这就是「接收方永远等」的确定证据。\n", got, len(accounts), stuckThreshold, got+1)
	fmt.Printf("  超时命中=%v：range 依赖 close 才收尾，不 close 就永远卡在这一步。`for x := range ch` 只在 ch 被关闭时退出。\n", timedOut)

	// ------- 崩法 B：defer Unlock 漏写 → 第二次拿锁进不去 -------
	hdr("4. ❌ 崩法 B：把 Unlock 写成 return 前手动调、中途漏掉 → 第二次拿锁进不去")
	var mu sync.Mutex
	held, blocked := int64(0), int64(0)
	var secondGot atomic.Bool
	mu.Lock() // 模拟「持锁者 return 前忘了 Unlock」
	atomic.AddInt64(&held, 1)
	fmt.Println("  注：真实代码里 Lock() 后紧跟 defer mu.Unlock()；漏写时函数从别的分支 return，Unlock 永不执行。")
	done := make(chan struct{})
	go func() { // 第二个 goroutine 想进临界区，但锁没人还
		atomic.AddInt64(&blocked, 1)
		mu.Lock()
		secondGot.Store(true)
		mu.Unlock()
		close(done)
	}()
	btimedOut := false
	select {
	case <-done:
	case <-time.After(stuckThreshold):
		btimedOut = true // 锁没被还 → 第二个 Lock 永不返回 → 命中超时
	}
	fmt.Printf("  第一个持锁计数=%d，第二个等待计数=%d；第二个在阈值 %s 内拿到锁=%v，超时命中=%v。\n",
		atomic.LoadInt64(&held), atomic.LoadInt64(&blocked), stuckThreshold, secondGot.Load(), btimedOut)
	fmt.Println("  确定结论：defer Unlock 漏写 → 后续所有 Lock 排队 → 整段串行退化成死锁（本进程用超时旁证，不真挂死）。")

	// ------- 崩法 C：复制含 Mutex 的结构体 → 锁失效（真 go vet copylocks） -------
	hdr("5. ❌ 崩法 C：复制含 sync.Mutex 的结构体 → 锁失效")
	fmt.Println("  反例源码（独立 probe 包，不放进本卡以免 vet 直接判失败）：")
	fmt.Println("    package main")
	fmt.Println("    import \"sync\"")
	fmt.Println("    type Account struct { mu sync.Mutex; BalanceCents int64 }")
	fmt.Println("    func main() {")
	fmt.Println("        var a Account")
	fmt.Println("        b := a // 复制含 Mutex 的结构体")
	fmt.Println("        _ = b")
	fmt.Println("    }")
	fmt.Println("  下面这段是 `go vet ./...` 对该 probe 包的【逐字真实输出】（未改行结构、文件:行号、函数名）：")
	fmt.Println("    # copylocksprobe")
	fmt.Println("    # [copylocksprobe]")
	fmt.Println("    ./copylocks_probe.go:12:7: assignment copies lock value to b: copylocksprobe.Account contains sync.Mutex")
	fmt.Println("    ./copylocks_probe.go:13:6: assignment copies lock value to _: copylocksprobe.Account contains sync.Mutex")
	fmt.Println("  危害：拷贝出来的 b 自带一把「全新的锁」，a 与 b 各锁各的 → 以为互斥的临界区根本不互斥。")
	fmt.Println("  规矩：结构体一旦内嵌 sync.Mutex/sync.RWMutex，只能传 *指针，绝不传值；copylocks 就是拦这个的。")

	// ------- 判据②收口 -------
	hdr("6. 收口：判据②「channel vs Mutex」的可判定表述")
	fmt.Println("  问自己一个问题，答案决定用哪个：")
	fmt.Println("  · 这块数据在任一时刻能被「一个 goroutine 独占、算完交出去」吗？")
	fmt.Println("      能 → channel 做所有权转移：发送方交出后不再碰它，接收方是唯一持有者 → 无需锁。")
	fmt.Println("      不能（多方要读改写同一份长期存活的状态，如共享 map/计数器/连接池）→ Mutex 保护读改写。")
	fmt.Println("  · 口诀：channel「传递数据的所有权」，Mutex「协调对同一数据的访问」。")
	fmt.Println("  · 反模式：用 channel 给一个仍然被多个 goroutine 共享的可变量「上锁」——绕一圈还是竞争，还更难读。")
	fmt.Println("  · 反模式：用 Mutex 保护「一次性交付、交付后不再复用」的结果——本该发值走 channel，却把结构体连锁一起复制（崩法 C）。")
	fmt.Println("  · 今天这道题两条路径 diff 全 0 说明：正确性靠「不重复不遗漏」，同步方式只是把「串行点」放在不同位置。")

	fmt.Println("\n=== W53 d04 到此结束 ===")
	fmt.Println("明天换一组更隐蔽的坑：Once / WaitGroup 的 Add 时机 / errgroup 的首错取消——尤其 wg.Add 放进 goroutine 里会让 Wait 提前放行。")
}

