// =====================================================================
// W53 d04：channel vs Mutex 各自该用在哪（S13 判据②）
//
// 同一道题「聚合 8 个账户的 *_cents」用两种写法并排跑：
//   · channel 路径 = 所有权转移：每个 goroutine 独占一个账户的结果，
//     把整份结果作为「值」发出去，接收方累加；从头到尾没有共享内存 → 不需要锁。
//   · Mutex 路径  = 共享读改写：8 个 goroutine 往同一张 map 里累加，
//     读-改-写整段被锁保护。
// 两条路径逐账户对拍，diff 必须全 0（结果一致），差别只在「同步放在哪」。
//
// 再逐条演示三种崩法，各自打印「被卡住」的确定证据（绝不真把进程挂死）：
//   ❌ 忘 close        → 接收方 range 永不结束：用带固定阈值的 select 命中「仍在等」。
//   ❌ defer Unlock 漏 → 第二次拿锁进不去：同样用带固定阈值的 select 命中「阻塞」。
//   ❌ 复制含 Mutex 的结构体 → 锁失效：go vet 的 copylocks 真能抓，逐字贴真实 vet 输出。
//
// 收口给「所有权转移用 channel、共享读改写用 Mutex」这条判据的可判定表述。
//
// 本机跑法：cd homecube/server && go run ./lab/s13/d04
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

// stuckThreshold 是演示「永远等」用的固定阈值：打印的是「超时命中」这个确定结论，
// 不打印真实耗时；值固定 → 两次跑字节一致。
const stuckThreshold = 120 * time.Millisecond

var famID = "aaaaaaaa-0000-4000-8000-000000000001"

// 金额一律 *_cents 整数；符号表只有服务端这一份（沿用 W46/W47 口径）。
var sign = map[string]int64{"income": 1, "expense": -1, "refund": 1}

type Account struct {
	Code         string
	Name         string
	OpeningCents int64
}

type Txn struct {
	Account     string
	Kind        string
	AmountCents int64
}

// 8 个账户，期初各不相同；交易按账户 code 分布。
var accounts = []Account{
	{"ACC-01", "现金钱包", 120000},
	{"ACC-02", "储蓄卡", 860000},
	{"ACC-03", "信用卡", -45000},
	{"ACC-04", "房贷账户", -3200000},
	{"ACC-05", "证券", 540000},
	{"ACC-06", "公积金", 300000},
	{"ACC-07", "外币", 78000},
	{"ACC-08", "家长代管", 15000},
}

// 金额一律存正数「面值」，方向由 sign 表决定；两条路径共用同一份符号，绝不自写第二套。

var txns = []Txn{
	{"ACC-01", "income", 860000}, {"ACC-01", "expense", 120000}, {"ACC-01", "refund", 3000},
	{"ACC-02", "income", 1200000}, {"ACC-02", "expense", 330000},
	{"ACC-03", "expense", 50000}, {"ACC-03", "refund", 8000},
	{"ACC-04", "expense", 800000},
	{"ACC-05", "income", 42000}, {"ACC-05", "expense", 15000},
	{"ACC-06", "income", 240000},
	{"ACC-07", "income", 9000}, {"ACC-07", "refund", 1500},
	{"ACC-08", "expense", 4000}, {"ACC-08", "income", 5000},
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string {
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}
func codesOf(accts []Account) []string {
	c := make([]string, len(accts))
	for i, a := range accts {
		c[i] = a.Code
	}
	sort.Strings(c)
	return c
}

// ---- channel 路径：所有权转移。每个 goroutine 独占一个账户，算完整份结果再发值。 ----
func aggregateWithChannel() map[string]int64 {
	type job struct{ acc Account }
	in := make(chan job, len(accounts))
	out := make(chan map[string]int64, len(accounts))

	// 工人：从 in 领一个账户（拿到即独占所有权，无人再改它），算完把结果 map 发进 out。
	var workers sync.WaitGroup
	for w := 0; w < 4; w++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for j := range in { // in 被 close 后 range 才会结束
				res := j.acc.OpeningCents
				for _, t := range txns {
					if t.Account == j.acc.Code {
						res += sign[t.Kind] * t.AmountCents // 方向查符号表，面值取正
					}
				}
				out <- map[string]int64{j.acc.Code: res} // 发整份结果，接收方只做拼装
			}
		}()
	}

	go func() {
		for _, a := range accounts {
			in <- job{a}
		}
		close(in) // ← 生产侧发完必须 close，否则工人的 range in 永不结束
	}()

	go func() { workers.Wait(); close(out) }() // 工人都退出后 close out，消费侧 range 才能收尾

	got := map[string]int64{}
	for m := range out { // out 被 close 后 range 结束
		for k, v := range m {
			got[k] = v
		}
	}
	return got
}

// ---- Mutex 路径：共享读改写。所有 goroutine 往同一张 balance map 累加。 ----

func aggregateWithMutex() map[string]int64 {
	balance := map[string]int64{}
	for _, a := range accounts {
		balance[a.Code] = a.OpeningCents // 先铺期初（单线程，无竞争）
	}
	var mu sync.Mutex
	var wg sync.WaitGroup
	for _, a := range accounts {
		wg.Add(1)
		go func(acc Account) { // acc 作参数传入：闭包捕获循环变量会与后续迭代竞争
			defer wg.Done()
			var delta int64
			for _, t := range txns { // 先在本地算，把读-改-写的临界区压到最短
				if t.Account == acc.Code {
					delta += sign[t.Kind] * t.AmountCents
				}
			}
			mu.Lock() // 共享 map 的读改写整段上锁
			balance[acc.Code] += delta
			mu.Unlock()
		}(a)
	}
	wg.Wait()
	return balance
}

// 逐账户对拍两条路径。
func diffTable(ch, mx map[string]int64) int {
	fmt.Printf("  %-8s %-14s %-14s %-10s %s\n", "code", "channel 路径", "mutex 路径", "diff", "判定")
	bad := 0
	for _, c := range codesOf(accounts) {
		d := mx[c] - ch[c]
		mark := "✅ 一致"
		if d != 0 {
			mark, bad = "❌ 不一致", bad+1
		}
		fmt.Printf("  %-8s %-14s %-14s %-10s %s\n", c, money(ch[c]), money(mx[c]), money(d), mark)
	}
	return bad
}

func main() {
	hdr(fmt.Sprintf("1. 场景：%d 个账户 × %d 笔流水（family_id=%s），金额全 *_cents 整数", len(accounts), len(txns), famID))
	fmt.Printf("  符号表（服务端唯一一份）%v\n", sign)
	fmt.Println("  同一个「聚合余额」的活儿，两种并发写法并排跑；结果必须逐账户 diff 全 0。")
	fmt.Println("  每笔流水按符号折算的家庭增量（两条路径都吃同一份数据、同一张符号表）：")
	fmt.Printf("  %-8s %-9s %-8s %-10s %s\n", "account", "kind", "面值", "sign", "折算增量")
	for _, t := range txns {
		fmt.Printf("  %-8s %-9s %-8s %-10d %s\n", t.Account, t.Kind, money(t.AmountCents), sign[t.Kind], money(sign[t.Kind]*t.AmountCents))
	}

	chRes := aggregateWithChannel()
	mxRes := aggregateWithMutex()

	hdr("2. ✅ 两条路径逐账户对拍：diff 全 0")
	fmt.Println("  每账户：期初 + 名下折算增量之和 = 期末余额；channel 路径与 mutex 路径各算一遍。")
	fmt.Printf("  %-8s %-12s %-10s %-10s %s\n", "code", "账户", "期初", "channel期末", "（下面接对拍表）")
	opening := map[string]int64{}
	for _, a := range accounts {
		opening[a.Code] = a.OpeningCents
	}
	for _, c := range codesOf(accounts) {
		var nm string
		for _, a := range accounts {
			if a.Code == c {
				nm = a.Name
			}
		}
		fmt.Printf("  %-8s %-12s %-10s %-10s %s\n", c, nm, money(opening[c]), money(chRes[c]), "—")
	}
	bad := diffTable(chRes, mxRes)
	sum := int64(0)
	for _, c := range codesOf(accounts) {
		sum += chRes[c]
	}
	fmt.Printf("  非 0 差值 %d/%d 处；全体账户合计 %s 元 —— 结果与「同步放在哪」无关，只与「有没有算重/漏算」有关。\n", bad, len(accounts), money(sum))

	// ------- 崩法 A：忘 close → 接收方永远等（用固定阈值 select 命中「仍在等」） -------
	hdr("3. ❌ 崩法 A：生产侧发完不 close → 接收方 range 永不结束")
	fmt.Println("  复现：缓冲 chan(cap=8)，生产者把 8 份结果塞满后就 return，唯独忘了 close。")
	agg := make(chan map[string]int64, len(accounts))
	for _, c := range codesOf(accounts) {
		agg <- map[string]int64{c: chRes[c]} // 塞满 8 条，之后既不 close 也不发
	}
	got, timedOut := 0, false
recvLoop:
	for {
		select {
		case _, ok := <-agg:
			if !ok { // 只有 close 后才会走到这里；本例永不 close
				break recvLoop
			}
			got++
		case <-time.After(stuckThreshold): // 缓冲区被抽干后，第 9 次接收再无数据 → 命中超时
			timedOut = true
			break recvLoop
		}
	}
	fmt.Printf("  已收到 %d/%d 条；随后在固定阈值 %s 内第 %d 次接收【超时命中】—— 这就是「接收方永远等」的确定证据。\n", got, len(accounts), stuckThreshold, got+1)
	fmt.Printf("  超时命中=%v：range 依赖 close 才收尾，不 close 就永远卡在这一步。`for x := range ch` 只在 ch 被关闭时退出。\n", timedOut)

	// ------- 崩法 B：defer Unlock 漏写 → 第二次拿锁进不去 -------
	hdr("4. ❌ 崩法 B：把 Unlock 写成 return 前手动调、中途漏掉 → 第二次拿锁进不去")

code.content:
// =====================================================================
// W53 d05：Once / WaitGroup 的 Add 时机 / errgroup 的首错取消
//
// 三件事各自「真跑」并给出确定字节：
//   ① 懒初始化读到半成品：builder 逐字段写、无 Once 的读者停在第 1/3/4 阶段各拍一张快照，
//      打印三份配置点名不一致字段（用 ping-pong 信号把观察点钉死，可复现）；再用 sync.Once 修好。
//   ② wg.Add 放进 goroutine → Wait 提前返回：裸跑 K∈0..7 不定；用 fastDone/parked 把顺序钉死，
//      K 稳定复现成 3，再对比放对 Add 位置后等满 8。
//   ③ errgroup 首错取消其余：打印胜出错误是谁、其余几个被取消（呼应 S12 d21 的部分失败）。
//
// 本机跑法：cd homecube/server && go run ./lab/s13/d05
// =====================================================================

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"

	"golang.org/x/sync/errgroup"
)

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---------- ① 懒初始化配置：无 Once 时读到半成品 ----------
type Cfg struct {
	Addr      string
	Port      int
	TimeoutMS int
	Pool      int
	Ready     bool // 只有全部字段填完才置 true
}

// 把 Cfg 渲染成一行，方便逐字段对比。
func (c Cfg) line() string {
	return fmt.Sprintf("addr=%-9s port=%-5d timeout=%-4d pool=%-3d ready=%-5v", c.Addr, c.Port, c.TimeoutMS, c.Pool, c.Ready)
}

// 无保护的共享配置：builder 一个字段一个字段往里写，每写一步给 stage 发一个阶段号。
var shared Cfg

func stageOf(c Cfg) int { // 该快照填到了第几个字段（用于点名不一致）
	n := 0
	if c.Addr != "" {
		n++
	}
	if c.Port != 0 {
		n++
	}
	if c.TimeoutMS != 0 {
		n++
	}
	if c.Pool != 0 {
		n++
	}
	return n
}

func lazyInitRacy() []Cfg {
	ping := make(chan int)      // 无缓冲：builder 写完一步就等读者取走快照
	pong := make(chan struct{}) // 读者拍完再放行 builder 写下一步
	go func() {                 // builder：逐字段写，Ready 最后才置；每步与读者做 ping-pong 严格交错
		shared.Addr = "0.0.0.0"
		ping <- 1
		<-pong
		shared.Port = 8080
		ping <- 2
		<-pong
		shared.TimeoutMS = 3000
		ping <- 3
		<-pong
		shared.Pool = 16
		shared.Ready = true
		ping <- 4
		<-pong
	}()
	obs := make([]Cfg, 0, 3)
	watch := map[int]bool{1: true, 3: true, 4: true} // 三个读者分别停在第 1、3、4 阶段快照
	for s := 1; s <= 4; s++ {
		<-ping
		if watch[s] {
			obs = append(obs, shared) // 停在 s 阶段时拍到的共享状态：比 s 晚的字段还没写
		}
		pong <- struct{}{}
	}
	return obs
}

// sync.Once 版：init 只跑一次；每个读者拿到的都是完整配置。
var onceCfg Cfg
var once sync.Once
var initCount int64

func lazyInitOnce() []Cfg {
	readers := make(chan Cfg, 3)
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			once.Do(func() { // 只有一个 goroutine 真正执行，其余阻塞等它跑完
				atomic.AddInt64(&initCount, 1)
				onceCfg.Addr, onceCfg.Port = "0.0.0.0", 8080
				onceCfg.TimeoutMS, onceCfg.Pool, onceCfg.Ready = 3000, 16, true
			})
			readers <- onceCfg // Do 返回后一定已填完 → 读者只会拿到成品
		}()
	}
	wg.Wait()
	close(readers)
	out := []Cfg{}
	for c := range readers {
		out = append(out, c)
	}
	return out
}

// ---------- ② WaitGroup：Add 放 goroutine 内 → Wait 提前返回 ----------
const wgTotal, wgFast = 8, 3

// 把 K 稳定钉成 3 的复现：前 wgFast 个「碰巧」先跑完 Add+Done（计数净回落到 0），
// 其余卡在 wg.Add 之前；主 goroutine 观察到这两件事后才调 Wait → 计数器此刻为 0 → 立刻返回。
func waitGroupAddTooLate() int {
	var wg sync.WaitGroup
	var done int64
	fastDone := make(chan struct{}, wgFast)       // 前几个已完成一整轮 Add→Done
	parked := make(chan struct{}, wgTotal-wgFast) // 其余停在 wg.Add 之前
	release := make(chan struct{})
	lateDone := make(chan struct{}, wgTotal-wgFast)
	for i := 0; i < wgTotal; i++ {
		i := i
		go func() {
			if i < wgFast {
				wg.Add(1) // BUG：Add 在 goroutine 里；这 3 个恰好抢在 Wait 之前跑完
				atomic.AddInt64(&done, 1)
				wg.Done()
				fastDone <- struct{}{}
				return
			}
			parked <- struct{}{} // 报到：已创建，但还没 wg.Add
			<-release            // 卡在这里，等主 goroutine 观察完
			wg.Add(1)
			atomic.AddInt64(&done, 1)
			wg.Done()
			lateDone <- struct{}{}
		}()
	}
	for i := 0; i < wgFast; i++ {
		<-fastDone
	} // 确定：前 3 个已 Done，计数器净为 0
	for i := 0; i < wgTotal-wgFast; i++ {
		<-parked
	} // 确定：后 5 个还卡在 Add 之前，一个都没登记
	wg.Wait() // 此刻计数器=0 → 立即返回（本该等 8 条却提前放行）
	K := int(atomic.LoadInt64(&done))
	close(release) // 现在才让后 5 个真跑
	for i := 0; i < wgTotal-wgFast; i++ {
		<-lateDone
	}
	return K
}

// Add 放对位置：wg.Add 在主 goroutine、go 之前。
func waitGroupAddCorrect() int {
	var wg sync.WaitGroup
	var done int64
	for i := 0; i < wgTotal; i++ {
		wg.Add(1) // ← 登记发生在 spawn 之前
		go func() {
			defer wg.Done()
			atomic.AddInt64(&done, 1)
		}()
	}
	wg.Wait()
	return int(atomic.LoadInt64(&done))
}

// ---------- ③ errgroup：首个错误取消其余（部分失败口径） ----------
type Zone struct {
	ID       string
	FastFail bool // 只有它立即报错；其余都是会被取消的慢区
}

var zones = []Zone{
	{"R1-华北", false},
	{"R2-华东", false},
	{"R3-华南", true}, // 上游 500，最快返回错误 → 成为 errgroup 的胜出错误
	{"R4-西南", false},
	{"R5-西北", false},
}

// runErrgroup 返回：胜出的错误、被取消的区数、以及每个区的逐区结局（按 zones 顺序，稳定可打印）。
func runErrgroup() (winner string, canceled int, perZone []string) {
	g, ctx := errgroup.WithContext(context.Background())
	start := make(chan struct{})
	var nCanceled int64
	perZone = make([]string, len(zones))
	for i, z := range zones {
		i, z := i, z
		g.Go(func() error {
			<-start // 五个区同时起跑
			if z.FastFail {
				perZone[i] = "error(胜出)"
				return fmt.Errorf("district %s: 上游聚合 500", z.ID) // 首个错误
			}
			<-ctx.Done() // 慢区不返回错误，只等取消信号：errgroup 记录到首个错误后 cancel ctx
			perZone[i] = "canceled(未二次报错)"
			atomic.AddInt64(&nCanceled, 1) // 被取消 → 不往 errgroup 里塞第二个错误
			return nil
		})
	}
	close(start)
	err := g.Wait() // Wait 返回首个（也是唯一一个）错误
	if err != nil {
		winner = err.Error()
	}
	return winner, int(atomic.LoadInt64(&nCanceled)), perZone
}

func main() {
	hdr("1. ① 并发懒初始化：没有 Once，读者会停在 builder 的不同阶段")
	obs := lazyInitRacy()
	fmt.Println("  三个读者分别在第 1 / 3 / 4 阶段对共享配置拍了快照（阶段用信号钉死，可复现）：")
	for i, c := range obs {
		fmt.Printf("  读者#%d 快照：  %s  （已填字段数=%d）\n", i+1, c.line(), stageOf(c))
	}
	fmt.Println("  点名不一致的字段：")
	fmt.Printf("    读者#1 只拿到 addr，port/timeout/pool 全是零值（#1 停在第 1 阶段，builder 还没写后面）。\n")
	fmt.Printf("    读者#2 拿到 addr/port/timeout，但 pool=0 且 ready=false（#2 停在第 3 阶段）。\n")
	fmt.Printf("    读者#3 才是完整成品（ready=true）。\n")
	fmt.Println("    ready=false 的读者会以为「配置没加载完」——但它拿到的 addr/port 又像是能用的，最坑。")
	fmt.Println("  builder 逐字段写入的阶段表（读者在哪个阶段快照，就只能看到该阶段之前的字段）：")
	fmt.Printf("  %-8s %-10s %-8s %-9s %-7s %s\n", "阶段", "addr", "port", "timeout", "pool", "ready")
	fmt.Printf("  %-8s %-10s %-8s %-9s %-7s %s\n", "写 addr", "有", "0", "0", "0", "false")
	fmt.Printf("  %-8s %-10s %-8s %-9s %-7s %s\n", "写 port", "有", "有", "0", "0", "false")
	fmt.Printf("  %-8s %-10s %-8s %-9s %-7s %s\n", "写 timeout", "有", "有", "有", "0", "false")
	fmt.Printf("  %-8s %-10s %-8s %-9s %-7s %s\n", "写 pool", "有", "有", "有", "有", "true")
	fmt.Println("  这不是「慢一点」，是读到半写内存：字段间互相矛盾，端口 0 直接连不上、超时 0 语义又和默认不同。")

	hdr("2. ✅ 用 sync.Once 修好：init 只跑 1 次，所有读者拿到同一份完整配置")
	onceCfg = Cfg{}
	once = sync.Once{}
	atomic.StoreInt64(&initCount, 0)
	fixed := lazyInitOnce()
	for i, c := range fixed {
		fmt.Printf("  读者#%d 结果：  %s\n", i+1, c.line())
	}
	fmt.Printf("  once.Do 实际执行次数=%d（应为 1）；三份快照逐字段一致=%v。\n",
		atomic.LoadInt64(&initCount), fixed[0] == fixed[1] && fixed[1] == fixed[2])

	hdr("3. ② wg.Add 写进 goroutine 内部 → Wait 提前返回")
	fmt.Printf("  场景：本该等满 %d 条并发任务，但 wg.Add(1) 被放进 go func() 里。\n", wgTotal)
	k := waitGroupAddTooLate()
	fmt.Printf("  真跑结果：wg.Wait() 返回时实际只等到 K=%d 条（本该 %d 条）。\n", k, wgTotal)
	fmt.Printf("  裸跑这个 bug，K 会落在 0..%d 的任意值（取决于调度），输出就抖了。\n", wgTotal-1)
	fmt.Println("  为把它钉成确定字节：前 3 个用 fastDone 证明「已 Add+Done 计数器净回落为 0」，")
	fmt.Println("  后 5 个用 parked 证明「卡在 wg.Add 之前一个都没登记」，主 goroutine 观察完这两件事才调 Wait，")
	fmt.Printf("  于是 Wait 看到计数器=0 → 立刻放行 → K 稳定=%d（可复现的最坏情形）。\n", k)

	hdr("4. ✅ Add 放对位置：在 go 之前 wg.Add(N)，Wait 才真的等满")
	kc := waitGroupAddCorrect()
	fmt.Printf("  真跑结果：wg.Wait() 返回时等到 %d/%d 条 —— 与预期相符。\n", kc, wgTotal)
	fmt.Println("  对照第 3 节的 K=3：同一批 8 个任务，只把 wg.Add(1) 从 goroutine 里挪到 go 之前，Wait 就从「提前放行」变成「等满」。")
	fmt.Println("  口诀：谁调用 Wait，谁就要保证在 Wait 之前所有 Add 都已登记完；Add 必须和 spawn 在同一个（主）goroutine 里、且在 go 之前。")

	hdr("5. ③ errgroup：首个错误取消其余（不是整页 500）")
	winner, canceled, perZone := runErrgroup()
	fmt.Printf("  5 个区并发聚合，R3-华南 上游 500 最快返回错误。\n")
	fmt.Printf("  %-10s %s\n", "zone", "逐区结局")
	for i, z := range zones {
		fmt.Printf("  %-10s %s\n", z.ID, perZone[i])
	}
	fmt.Printf("  errgroup.Wait() 胜出的错误：%s\n", winner)
	fmt.Printf("  其余被 ctx 取消的区数：%d（每个慢区只等 ctx.Done()，不往 group 里塞第二个错误）。\n", canceled)
	fmt.Println("  机制：WithContext 的 group 一旦记录到第一个非 nil error，就 cancel 派生 ctx；")
	fmt.Println("  还在跑的兄弟能在下一次 <-ctx.Done() 处及时退出，省掉无谓的上游调用。")
	fmt.Println("  但注意口径（呼应 S12 d21）：页面级「一个区失败不能整页 500」。真做部分失败时，")
	fmt.Println("  要么每区各收各的 error/degraded 标记、只有全挂才 5xx；要么用 SetLimit 控并发。")
	fmt.Println("  errgroup 的「首错即取消」适合「要么全成、要么整单失败」的活儿（如一次事务的多路校验），")
	fmt.Println("  不适合「尽量多拿几块是好块」的仪表盘聚合——那种要自己攒每区结果。")
	fmt.Println("  胜出判定：Wait 只认「第一个真正 return 非 nil」的那个；R3 立即返回，慢区此刻还堵在 <-ctx.Done()，")
	fmt.Println("  所以胜出的永远是 R3。若两个区几乎同时报错，谁先 return 谁赢 —— 那种不确定性正是要靠 -race（d06）暴露的。")

	hdr("6. 收口：今天三件套的判定线")
	fmt.Println("  三处「无同步 / 错同步」的现场，各自的可判定修法：")
	fmt.Printf("  %-22s %-16s %-16s %s\n", "坑", "错法表现", "修法", "判定信号")
	fmt.Printf("  %-22s %-16s %-16s %s\n", "懒初始化读到半成品", "字段间自相矛盾", "sync.Once", "init 次数=1 且各读者快照相等")
	fmt.Printf("  %-22s %-16s %-16s %s\n", "wg.Add 放进 goroutine", "Wait 提前放行 K<8", "Add 在 go 之前", "Wait 返回时 done=N")
	fmt.Printf("  %-22s %-16s %-16s %s\n", "多路并发一路失败", "整页 500 或全跑完", "errgroup 首错取消", "Wait 返回首错、其余 canceled")
	fmt.Println("  · 共享配置的懒初始化 → sync.Once：初始化恰好一次、且对读者原子可见；bool 挡不住半写。")
	fmt.Println("  · WaitGroup：Add 在 spawn 之前、和 Wait 同一 goroutine 登记；Add 进 goroutine = 竞态，Wait 可能提前放行。")
	fmt.Println("  · errgroup：Wait 返回第一个到达的错误并取消其余——用它做「整单语义」，别拿它做「部分成功」。")
	fmt.Println("  · 三者共同的前提：只要多个 goroutine 碰同一份内存，就得先想清楚「同步放在哪」，否则就是 d06 要抓的 race。")

	fmt.Println("\n=== W53 d05 到此结束 ===")
	fmt.Println("明天 W53 收口：从本手册前面已存在的两处真写法（S10 乐观锁、S11 全局 trendCalls 计数）里，用 -race 抓出真实竞争再修好——判据①。")
}

