// =====================================================================
// W53 d05：Once / WaitGroup 的 Add 时机 / errgroup 的首错取消
//
// 三件事各自「真跑」并给出确定字节：
//   ① 懒初始化读到半成品：builder 逐字段写、无 Once 的读者停在第 1/3/4 阶段各拍一张快照，
//      打印三份配置点名不一致字段（用 ping-pong 信号把观察点钉死，可复现）；再用 sync.Once 修好。
//   ② wg.Add 放进 goroutine → Wait 提前返回：裸跑 K∈0..7 不定；用 fastDone/parked 把顺序钉死，
//      K 稳定复现成 3，再对比放对 Add 位置后等满 8。
//   ③ errgroup 首错取消其余：打印胜出错误是谁、其余几个被取消（呼应 S12 d21 的部分失败）。
//
// 本机跑法：cd homecube/server && go run ./lab/s13/d05
// =====================================================================

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"

	"golang.org/x/sync/errgroup"
)

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---------- ① 懒初始化配置：无 Once 时读到半成品 ----------
type Cfg struct {
	Addr      string
	Port      int
	TimeoutMS int
	Pool      int
	Ready     bool // 只有全部字段填完才置 true
}

// 把 Cfg 渲染成一行，方便逐字段对比。
func (c Cfg) line() string {
	return fmt.Sprintf("addr=%-9s port=%-5d timeout=%-4d pool=%-3d ready=%-5v", c.Addr, c.Port, c.TimeoutMS, c.Pool, c.Ready)
}

// 无保护的共享配置：builder 一个字段一个字段往里写，每写一步给 stage 发一个阶段号。
var shared Cfg

func stageOf(c Cfg) int { // 该快照填到了第几个字段（用于点名不一致）
	n := 0
	if c.Addr != "" {
		n++
	}
	if c.Port != 0 {
		n++
	}
	if c.TimeoutMS != 0 {
		n++
	}
	if c.Pool != 0 {
		n++
	}
	return n
}

func lazyInitRacy() []Cfg {
	ping := make(chan int)      // 无缓冲：builder 写完一步就等读者取走快照
	pong := make(chan struct{}) // 读者拍完再放行 builder 写下一步
	go func() {                 // builder：逐字段写，Ready 最后才置；每步与读者做 ping-pong 严格交错
		shared.Addr = "0.0.0.0"
		ping <- 1
		<-pong
		shared.Port = 8080
		ping <- 2
		<-pong
		shared.TimeoutMS = 3000
		ping <- 3
		<-pong
		shared.Pool = 16
		shared.Ready = true
		ping <- 4
		<-pong
	}()
	obs := make([]Cfg, 0, 3)
	watch := map[int]bool{1: true, 3: true, 4: true} // 三个读者分别停在第 1、3、4 阶段快照
	for s := 1; s <= 4; s++ {
		<-ping
		if watch[s] {
			obs = append(obs, shared) // 停在 s 阶段时拍到的共享状态：比 s 晚的字段还没写
		}
		pong <- struct{}{}
	}
	return obs
}

// sync.Once 版：init 只跑一次；每个读者拿到的都是完整配置。
var onceCfg Cfg
var once sync.Once
var initCount int64

func lazyInitOnce() []Cfg {
	readers := make(chan Cfg, 3)
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			once.Do(func() { // 只有一个 goroutine 真正执行，其余阻塞等它跑完
				atomic.AddInt64(&initCount, 1)
				onceCfg.Addr, onceCfg.Port = "0.0.0.0", 8080
				onceCfg.TimeoutMS, onceCfg.Pool, onceCfg.Ready = 3000, 16, true
			})
			readers <- onceCfg // Do 返回后一定已填完 → 读者只会拿到成品
		}()
	}
	wg.Wait()
	close(readers)
	out := []Cfg{}
	for c := range readers {
		out = append(out, c)
	}
	return out
}

// ---------- ② WaitGroup：Add 放 goroutine 内 → Wait 提前返回 ----------

const wgTotal, wgFast = 8, 3

// 把 K 稳定钉成 3 的复现：前 wgFast 个「碰巧」先跑完 Add+Done（计数净回落到 0），
// 其余卡在 wg.Add 之前；主 goroutine 观察到这两件事后才调 Wait → 计数器此刻为 0 → 立刻返回。
func waitGroupAddTooLate() int {
	var wg sync.WaitGroup
	var done int64
	fastDone := make(chan struct{}, wgFast)       // 前几个已完成一整轮 Add→Done
	parked := make(chan struct{}, wgTotal-wgFast) // 其余停在 wg.Add 之前
	release := make(chan struct{})
	lateDone := make(chan struct{}, wgTotal-wgFast)
	for i := 0; i < wgTotal; i++ {
		i := i
		go func() {
			if i < wgFast {
				wg.Add(1) // BUG：Add 在 goroutine 里；这 3 个恰好抢在 Wait 之前跑完
				atomic.AddInt64(&done, 1)
				wg.Done()
				fastDone <- struct{}{}
				return
			}
			parked <- struct{}{} // 报到：已创建，但还没 wg.Add
			<-release            // 卡在这里，等主 goroutine 观察完
			wg.Add(1)
			atomic.AddInt64(&done, 1)
			wg.Done()
			lateDone <- struct{}{}
		}()
	}
	for i := 0; i < wgFast; i++ {
		<-fastDone
	} // 确定：前 3 个已 Done，计数器净为 0
	for i := 0; i < wgTotal-wgFast; i++ {
		<-parked
	} // 确定：后 5 个还卡在 Add 之前，一个都没登记
	wg.Wait() // 此刻计数器=0 → 立即返回（本该等 8 条却提前放行）
	K := int(atomic.LoadInt64(&done))
	close(release) // 现在才让后 5 个真跑
	for i := 0; i < wgTotal-wgFast; i++ {
		<-lateDone
	}
	return K
}

// Add 放对位置：wg.Add 在主 goroutine、go 之前。
func waitGroupAddCorrect() int {
	var wg sync.WaitGroup
	var done int64
	for i := 0; i < wgTotal; i++ {
		wg.Add(1) // ← 登记发生在 spawn 之前
		go func() {
			defer wg.Done()
			atomic.AddInt64(&done, 1)
		}()
	}
	wg.Wait()
	return int(atomic.LoadInt64(&done))
}

// ---------- ③ errgroup：首个错误取消其余（部分失败口径） ----------

type Zone struct {
	ID       string
	FastFail bool // 只有它立即报错；其余都是会被取消的慢区
}

var zones = []Zone{
	{"R1-华北", false},
	{"R2-华东", false},
	{"R3-华南", true}, // 上游 500，最快返回错误 → 成为 errgroup 的胜出错误
	{"R4-西南", false},
	{"R5-西北", false},
}

// runErrgroup 返回：胜出的错误、被取消的区数、以及每个区的逐区结局（按 zones 顺序，稳定可打印）。
func runErrgroup() (winner string, canceled int, perZone []string) {
	g, ctx := errgroup.WithContext(context.Background())
	start := make(chan struct{})
	var nCanceled int64
	perZone = make([]string, len(zones))
	for i, z := range zones {
		i, z := i, z
		g.Go(func() error {
			<-start // 五个区同时起跑
			if z.FastFail {
				perZone[i] = "error(胜出)"
				return fmt.Errorf("district %s: 上游聚合 500", z.ID) // 首个错误
			}
			<-ctx.Done() // 慢区不返回错误，只等取消信号：errgroup 记录到首个错误后 cancel ctx
			perZone[i] = "canceled(未二次报错)"
			atomic.AddInt64(&nCanceled, 1) // 被取消 → 不往 errgroup 里塞第二个错误
			return nil
		})
	}
	close(start)
	err := g.Wait() // Wait 返回首个（也是唯一一个）错误
	if err != nil {
		winner = err.Error()
	}
	return winner, int(atomic.LoadInt64(&nCanceled)), perZone
}

