package main

import (
	"fmt"
	"strings"
	"sync"
	"sync/atomic"
)

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---------- ① 乐观锁：修前用信号把「两个用户都读到同一 version」的交错钉死，确定复现丢失更新 ----------
type demoRow struct {
	Note    string
	Version int
}

// 修前：读-改-写无同步。用一段直线代码把「两个用户都在对方写之前读到 version=1」这一
// 特定交错钉死（真跑时它由 -race 抓到，见第 2 节）——这样终值确定、可字节复现。
func optimisticLockLost() (passA, passB bool, finalVersion int) {
	v := 1  // 起始 version=1
	av := v // 用户 A 读到 version=1
	bv := v // 用户 B 也读到 version=1（此刻 A 还没来得及写 → 两人都拿到同一个陈旧版本）
	if av == 1 {
		v = av + 1
		passA = true
	}
	if bv == 1 { // B 手里还是陈旧的 1，检查照样通过 → 丢失更新的根因（A 的 Note 被 B 覆盖）
		v = bv + 1
		passB = true
	}
	return passA, passB, v
}

// 修后：一把 Mutex 把「检查 version → 改 → 递增」整段串行化。真并发跑，结果确定。
type demoSafeRow struct {
	mu sync.Mutex
	r  demoRow
}

func optimisticLockFixed() (success int, finalVersion int) {
	s := &demoSafeRow{r: demoRow{Note: "原始备注", Version: 1}}
	var wg sync.WaitGroup
	var ok int64
	start := make(chan struct{})
	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			s.mu.Lock()
			if s.r.Version == 1 { // 基于 version=1 的乐观检查
				s.r.Note = fmt.Sprintf("改法-%d", i)
				s.r.Version++
				atomic.AddInt64(&ok, 1)
			}
			s.mu.Unlock()
		}(i)
	}
	close(start)
	wg.Wait()
	return int(atomic.LoadInt64(&ok)), s.r.Version
}

// ---------- ② 全局计数：修后原子自增，真并发跑终值确定 ----------
func counterFixed() int64 {
	var c int64
	var wg sync.WaitGroup
	start := make(chan struct{})
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			atomic.AddInt64(&c, 1) // trendCalls++ 的原子版
		}()
	}
	close(start)
	wg.Wait()
	return c
}

// 归一化后的真实 -race 报告（堆地址→0xADDR，goroutine 编号→G#，绝对路径→模块相对路径；余下逐字照抄）。
