      lab/s13/d06/race_test.go:71 +0xc6
  homecube/server/lab/s13/d06.TestRaceOptimisticLock.gowrap1()
      lab/s13/d06/race_test.go:74 +0x41
Previous write at 0xADDR by goroutine G#:
  homecube/server/lab/s13/d06.(*OLTxn).updateRacy()
      lab/s13/d06/race_test.go:38 +0x1d0
  homecube/server/lab/s13/d06.TestRaceOptimisticLock.func1()
      lab/s13/d06/race_test.go:71 +0xc6
  homecube/server/lab/s13/d06.TestRaceOptimisticLock.gowrap1()
      lab/s13/d06/race_test.go:74 +0x41`

const raceTrend = `WARNING: DATA RACE
Write at 0xADDR by goroutine G#:
  homecube/server/lab/s13/d06.trendRacy()
      lab/s13/d06/race_test.go:117 +0xa9
  homecube/server/lab/s13/d06.TestRaceTrendCounter.func1()
      lab/s13/d06/race_test.go:134 +0x85
Previous write at 0xADDR by goroutine G#:
