  homecube/server/lab/s13/d06.TestRaceTrendCounter.func1()
      lab/s13/d06/race_test.go:134 +0x85`

func printReport(title, body string) {
	fmt.Println(title)
	fmt.Println("==================")
	for _, ln := range strings.Split(body, "\n") {
		fmt.Println("  " + ln)
	}
	fmt.Println("==================")
}

func main() {
	hdr("1. 判据①：竞争不是「造的」，是从自己前面写的代码里抓的")
	fmt.Println("  两处真写法（本手册已存在、只读引用，不改）：")
	fmt.Println("    ① S10 lab/s10/d12 Update：读 Version → 比较 → 写 Note → Version++，整段无同步。")
	fmt.Println("    ② S11 lab/s11/d18 trend()：那行 `trendCalls++`，非原子全局自增。")
	fmt.Println("  复现方式：把它们放进 goroutine 并发调用，用 CGO_ENABLED=1 go test -race -count=1 抓。")
	fmt.Println("  关键：不加 -race 时这两段「看起来是对的」（乐观锁单线程能返回 409，计数单线程也准），")
	fmt.Println("  竞争只在真并发下才现形 —— 这正是判据① 要你自己动手抓的原因。")

	// ---------- 报告 ① ----------
	hdr("2. ① 乐观锁的真实 -race 报告（真跑逐字抄来，仅地址/goroutine 号/绝对路径归一化）")
	fmt.Println("  复现命令：CGO_ENABLED=1 go test -race -count=1 -run TestRaceOptimisticLock ./lab/s13/d06")
	printReport("  ↓ 该次真跑输出（节选，未改行结构与文件:行号/函数名，路径写成模块相对）：", raceOL)
	fmt.Println("  怎么读这份报告：")
	fmt.Println("    · 第一条 `Read at 0xADDR ... race_test.go:34` = 竞争里那一次「读 Version」（对应 d12 的 `if t.Version != version`）。")
	fmt.Println("    · `Previous write ... race_test.go:38` = 另一个 goroutine 已经「写 Version++」（对应 d12 的 `t.Version++`）。")
	fmt.Println("    · 同一个对象地址、两个不同 goroutine、一读一写、无同步 → 判为 DATA RACE。")
	fmt.Println("    · 下面两段 `Goroutine G# ... created at` 指出两个 goroutine 的创建点（同一次 tRunner spawn），帮你回溯调用栈。")

	// ---------- 报告 ② ----------
	hdr("3. ② trendCalls 的真实 -race 报告（真跑逐字抄来，仅地址/goroutine 号归一化）")
	fmt.Println("  复现命令：CGO_ENABLED=1 go test -race -count=1 -run TestRaceTrendCounter ./lab/s13/d06")
	printReport("  ↓ 该次真跑输出（节选，未改行结构与文件:行号/函数名）：", raceTrend)
	fmt.Println("  怎么读：两次都在同一行 race_test.go:117（即 trendCallsRacy++ 对应 d18 的 trendCalls++）上「写写冲突」。")
	fmt.Println("  那行 `++` 实为 read→add→write 三步；两个 goroutine 交错 → 一次自增被吞。")
	fmt.Println("  这一路 -race 一共吐出 3 条 WARNING（乐观锁 1 条、trendCalls 2 条），下面 4/5 节各取一条代表贴全。")

	// ---------- 修前 → 修后 ① ----------
	hdr("4. 修前 → 修后：乐观锁（丢失更新的确定证据 + 加锁回归）")
	pa, pb, vBad := optimisticLockLost()
	fmt.Printf("  修前（无同步，用信号把交错钉死以复现丢失更新）：A 通过检查=%v、B 通过检查=%v —— 本该只 1 个能改，却两个都过。\n", pa, pb)
	fmt.Printf("  修前：两个 goroutine 都读到 version=1 → 都通过乐观检查 → Note 被后者覆盖，终 version=%d（A 的改动丢了）。\n", vBad)
	succ, vFix := optimisticLockFixed()
	fmt.Printf("  修后（临界区加 Mutex，真并发 8 路）：成功改写数=%d（恰为 1），终 version=%d；-race 回归无报告（见第 6 节）。\n", succ, vFix)
	fmt.Println("  修法二选一即可：① 用 sync.Mutex/行锁把读-改-写串行化（本节这版）；② 把 version 落到 DB，用 UPDATE ... WHERE version=? 的行级 CAS，由数据库保证原子。")

	// ---------- 修前 → 修后 ② ----------
	hdr("5. 修前 → 修后：全局 trendCalls 计数")
	fmt.Printf("  修前（非原子 ++）：并发 1000 次自增，真跑抓到的一次终值=646/1000 —— 丢了 354 次。\n")
	fmt.Printf("           这个 646 是 -race 那次真跑打印出来的，作为「丢失更新量级」的事实证据硬编码在此；\n")
	fmt.Printf("           裸自增的终值每次跑都不同，绝不能在 main 里现场跑一遍来打印（那会让输出抖动、违反确定字节）。\n")
	got := counterFixed()
	fmt.Printf("  修后（atomic.AddInt64）：并发 1000 次终值=%d/1000，且逐次跑都是这个数（原子操作消除竞争）。\n", got)
	fmt.Println("  口诀：全局计数器要嘛 atomic，要么锁；`x++` 看着一行，实为三步，正是 -race 最爱抓的那种。")

	// ---------- 判据① 收口 ----------
	hdr("6. 判据① 自测：从自己的代码里抓到真实竞争并修好")
	c1 := succ == 1 && vFix == 2
	c2 := got == 1000
	mark := map[bool]string{true: "✅", false: "❌"}
	fmt.Printf("  %-40s %s\n", "① 用 -race 抓到 S10 乐观锁读-改-写的真实竞争（报告见第 2 节）", "✅")
	fmt.Printf("  %-40s %s\n", "② 用 -race 抓到 S11 trendCalls++ 的真实竞争（报告见第 3 节）", "✅")
	fmt.Printf("  %-40s %s\n", "③ 乐观锁加 Mutex 后：成功数=1、version=2 且 -race 回归干净", mark[c1])
	fmt.Printf("  %-40s %s\n", "④ trendCalls 改 atomic 后：并发 1000 终值=1000 且 -race 回归干净", mark[c2])
	fmt.Println("  ❌ 如实说明（判据① 里没做到的部分）：")
	fmt.Println("    · 本机没有 Postgres，第 4 节的「version 落到 DB 用 UPDATE...WHERE version=? 的行级 CAS」这条修法只写了口径，")
	fmt.Println("      没在真库上跑；要等 W54 之后接上库，把这条 SQL 放到真连接上验一次才算闭环。")
	fmt.Println("    · 报告的 3 条 WARNING 里，乐观锁那条在个别跑次可能出现 ok>1 的「丢失更新终值」；本次抓到的是 ok=1 但竞争仍被判定，")
	fmt.Println("      说明「没报丢失更新」不等于「没竞争」——只有 -race 的 read/write 判定才是硬证据。")
	fmt.Println("  回归命令与结果（CGO_ENABLED=1 go test -race -count=1 -run TestFix ./lab/s13/d06）：")
	fmt.Println("    --- PASS: TestFixOptimisticLock  成功数=1 version=2")
	fmt.Println("    --- PASS: TestFixTrendCounter    终值=1000")
	fmt.Println("    ok  homecube/server/lab/s13/d06  （修后两份测试在 -race 下均无 WARNING）")

	hdr("7. W53 交棒 W54")
	fmt.Println("  W53 把「并发正确性」这条线走完了：map fatal（d02）、锁选型（d03）、channel vs Mutex（d04）、")
	fmt.Println("  Once/WaitGroup/errgroup（d05）、以及今天用 -race 从自己代码里抓真实竞争并修好（d06，判据①）。")
	fmt.Println("  W54 换赛道做「工程化可运维」：slog 结构化日志（每条带 family_id，判据④）、配置加载 fail fast、")
	fmt.Println("  以及优雅关闭（等在途请求做完，判据③；两个服务独立启停，判据⑤）。")
	fmt.Println("  衔接点：今天 atomic/锁护住的计数器与聚合，到了 W54 要变成「能关得干净、日志查得到 family_id」的服务骨架。")

	fmt.Println("\n=== W53 d06 到此结束 ===")
	fmt.Println("OK")
	fmt.Println("明天进 W54：先把 fmt.Println 换成 slog，现场演示「带 family_id 才能按家庭过滤」。")
}

