// W54 d07：为什么 fmt.Println 不够 —— 用 slog 结构化日志把 family_id 变成可筛字段（判据④）
//
// 三个家庭的日志混在一个文件里，运维只想捞 fam-b 的全部行为什么做不到？因为 fmt.Println
// 把 family_id 拼进自由文本，值粘在中文句子里，换个措辞过滤就漏行。slog 的 JSONHandler 把
// 每条日志写成稳定 key:value，family_id 永远占一个字段，才能被机器按字段筛（判据④）。
// 本程序把同一批业务事件（记账/预算/跨家庭越权/邀请）各落两遍：Println 版 vs slog 版。
// 确定性纪律：slog 用 ReplaceAttr 删 time、AddSource 关 source → 两遍跑逐字节一致。
// 金额一律 *_cents 整数；跨家庭越权返 404（不是 403）；写接口带 client_request_id。
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d07
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"strings"
)

// op 是一条业务事件：家庭记账域里的一次操作，要落一条日志。
type op struct {
	family string
	user   string
	kind   string
	msg    string // 人类描述（Println 版直接打它）
	level  slog.Level
	cents  int64  // 金额分；非金额事件填 0
	crid   string // client_request_id，写接口才有
	deny   bool   // 是否是「跨家庭越权被拒」——记 Warn 不记 Error
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// 三个家庭的日志混在一起（fam-a / fam-b / fam-c），共 16 条。
var ops = []op{
	{"fam-a", "u-a1", "checkout_created", "顾客结账 1200 分", slog.LevelInfo, 1200, "crid-a-01", false},
	{"fam-b", "u-b1", "checkout_created", "顾客结账 4800 分", slog.LevelInfo, 4800, "crid-b-01", false},
	{"fam-c", "u-c1", "budget_check", "月度预算校验通过", slog.LevelInfo, 0, "", false},
	{"fam-b", "u-b1", "budget_check", "月度预算校验通过", slog.LevelInfo, 0, "", false},
	{"fam-a", "u-a2", "member_invite", "邀请新成员加入家庭", slog.LevelInfo, 0, "crid-a-02", false},
	{"fam-b", "u-c9", "cross_family_deny", "他家庭用户尝试读本家庭流水", slog.LevelWarn, 0, "", true},
	{"fam-a", "u-b1", "checkout_created", "顾客结账 9900 分", slog.LevelInfo, 9900, "crid-a-03", false},
	{"fam-c", "u-c1", "checkout_created", "顾客结账 300 分", slog.LevelInfo, 300, "crid-c-01", false},
	{"fam-b", "u-b1", "checkout_created", "顾客结账 7500 分", slog.LevelInfo, 7500, "crid-b-02", false},
	{"fam-c", "u-c9", "cross_family_deny", "他家庭用户尝试读本家庭流水", slog.LevelWarn, 0, "", true},
	{"fam-b", "u-b2", "member_invite", "邀请新成员加入家庭", slog.LevelInfo, 0, "crid-b-03", false},
	{"fam-a", "u-a2", "checkout_created", "顾客结账 2100 分", slog.LevelInfo, 2100, "crid-a-04", false},
	{"fam-b", "u-b1", "budget_check", "月度预算接近上限", slog.LevelInfo, 0, "", false},
	{"fam-c", "u-c1", "member_invite", "邀请新成员加入家庭", slog.LevelInfo, 0, "crid-c-02", false},
	{"fam-a", "u-c9", "cross_family_deny", "他家庭用户尝试读本家庭流水", slog.LevelWarn, 0, "", true},
	{"fam-c", "u-c2", "checkout_created", "顾客结账 5600 分", slog.LevelInfo, 5600, "crid-c-03", false},
}

// newJSONLogger 把 JSON 行写进 buf：删 time、关 source → 字节稳定。
func newJSONLogger(buf *bytes.Buffer) *slog.Logger {
	h := slog.NewJSONHandler(buf, &slog.HandlerOptions{
		AddSource: false,
		ReplaceAttr: func(_ []string, a slog.Attr) slog.Attr {
			if a.Key == slog.TimeKey || a.Key == slog.SourceKey {
				return slog.Attr{} // 丢时间戳 / 源码位置，两遍跑才逐字节相同
			}
			return a
		},
	})
	return slog.New(h)
}

// filterByFamily 真的解析每行 JSON、按 family_id 字段筛出目标家庭全部行（不是字符串瞎猜）。
func filterByFamily(lines []string, want string) []string {
	var hit []string
	for _, ln := range lines {
		var probe struct {
			FamilyID string `json:"family_id"`
		}
		if json.Unmarshal([]byte(ln), &probe) == nil && probe.FamilyID == want {
			hit = append(hit, ln)
		}
	}
	return hit
}

func main() {
	hdr("0. 题面：三个家庭的日志混在一起，运维只要 fam-b 这一家")
	fmt.Printf("  混在一起共 %d 条业务事件，涉及 fam-a / fam-b / fam-c 三个家庭。\n", len(ops))
	fmt.Println("  判据④：family_id 恒进每一条日志 —— 这样日志才能按家庭过滤。")
	fmt.Println("  今天把同一批事件用两种方式各落一遍：fmt.Println 拼接版 vs slog JSONHandler 版。")

	hdr("1. 反例：fmt.Println 把 family_id 拼进自由文本")
	fmt.Println("  下面是「人看着挺好」的 Println 版（每条一行，family 粘在中文里）：")
	plText := make([]string, 0, len(ops))
	for _, o := range ops {
		var line string
		switch o.kind {
		case "checkout_created":
			line = fmt.Sprintf("[%s] user=%s 顾客结账，金额 %d 分 (request %s)", o.family, o.user, o.cents, o.crid)
		case "budget_check":
			line = fmt.Sprintf("[%s] user=%s 月度预算校验：%s", o.family, o.user, o.msg)
		case "member_invite":
			line = fmt.Sprintf("[%s] user=%s 邀请新成员加入家庭 (request %s)", o.family, o.user, o.crid)
		case "cross_family_deny":
			line = fmt.Sprintf("[%s] user=%s 越权读取本家庭流水被拒 status=404", o.family, o.user)
		}
		plText = append(plText, line)
		fmt.Println("  " + line)
	}
	naiveHits := 0
	for _, ln := range plText {
		if strings.Contains(ln, "fam-b") {
			naiveHits++
		}
	}
	fmt.Printf("  按子串 \"fam-b\" 硬捞：命中 %d 行 —— 恰好都在这批里，但纯靠方括号格式撑着。\n", naiveHits)
	fmt.Println("  坑一：措辞一改（如 '家庭 fam-b：' 或去掉方括号）grep 就漏行，且漏得悄无声息。")
	fmt.Println("  坑二：这些行没有稳定 key，机器无法回答「只要 fam-b 的 checkout 且金额>5000」这种组合条件。")
	fmt.Println("  坑三：金额写成「1200 分」是文本，想求和还得先把中文剥掉 —— 迟早剥错。")

	hdr("2. 正例：slog JSONHandler 把每条日志写成稳定 key:value")
	var buf bytes.Buffer
	lg := newJSONLogger(&buf)
	for _, o := range ops {
		attrs := []any{"family_id", o.family, "user_id", o.user, "kind", o.kind} // family_id 恒进每一条
		if o.kind == "checkout_created" {
			attrs = append(attrs, "amount_cents", o.cents) // 金额分整数，不用浮点
		}
		if o.crid != "" {
			attrs = append(attrs, "client_request_id", o.crid) // 写接口带幂等键
		}
		if o.deny {
			attrs = append(attrs, "status", 404) // 跨家庭 → 404，不是 403
		}
		lg.Log(context.Background(), o.level, o.msg, attrs...)
	}
	jsonLines := strings.Split(strings.TrimRight(buf.String(), "\n"), "\n")
	for _, ln := range jsonLines {
		fmt.Println("  " + ln)
	}
	fmt.Println("  每条一个 family_id 字段；金额是 amount_cents 整数；越权行带 status=404；写操作带 client_request_id。")

	hdr("3. 判据④现场自证：程序按 family_id 字段筛出 fam-b 的全部行")
	want := "fam-b"
	hit := filterByFamily(jsonLines, want)
	fmt.Printf("  程序解析每行 JSON 的 family_id 字段，筛出 \"%s\" 的全部行：\n", want)
	for _, ln := range hit {
		fmt.Println("    " + ln)
	}
	fmt.Printf("  数出来的行数：%d（总 %d 条里 fam-b 占 %d 条，由程序现算，非写死）。\n", len(hit), len(jsonLines), len(hit))
	counts := map[string]int{}
	for _, ln := range jsonLines {
		var probe struct {
			FamilyID string `json:"family_id"`
		}
		_ = json.Unmarshal([]byte(ln), &probe)
		counts[probe.FamilyID]++
	}
	var sum int
	fmt.Println("  逐家庭数一遍，证明过滤不重不漏：")
	for _, f := range []string{"fam-a", "fam-b", "fam-c"} {
		fmt.Printf("    %-6s：%2d 条\n", f, counts[f])
		sum += counts[f]
	}
	fmt.Printf("  三家相加 = %d，与总行数 %d 一致 = %v。\n", sum, len(jsonLines), sum == len(jsonLines))
	hdr("3b. 逐家庭全量分流：同一个字段筛，把三家各捞一遍（行数由程序数）")
	for _, f := range []string{"fam-a", "fam-b", "fam-c"} {
		rows := filterByFamily(jsonLines, f)
		fmt.Printf("  -- %s 命中 %d 行 --\n", f, len(rows))
		for _, ln := range rows {
			fmt.Println("     " + ln)
		}
	}
	fmt.Println("  同一段 filterByFamily，换 want 就换一家 —— 这正是 family_id 进日志换来的能力。")

	hdr("4. fam-b 内部再按条件筛：只要 checkout 且金额>5000")
	var cents []int64
	for _, ln := range hit {
		var e struct {
			Kind  string `json:"kind"`
			Cents int64  `json:"amount_cents"`
		}
		_ = json.Unmarshal([]byte(ln), &e)
		if e.Kind == "checkout_created" && e.Cents > 5000 {
			cents = append(cents, e.Cents)
		}
	}
	fmt.Printf("  fam-b 的 checkout 且 amount_cents>5000 的笔数：%d，金额分别是：\n", len(cents))
	for _, c := range cents {
		fmt.Printf("    amount_cents=%d\n", c)
	}
	fmt.Println("  这种「字段组合条件」在 Println 版里要靠正则拼，在结构化日志里是一次 JSON 字段比较。")
	hdr("4b. 顺带把账算平：逐家庭 checkout 金额合计（*_cents 整数相加，无浮点）")
	totals := map[string]int64{}
	nCent := map[string]int{}
	for _, o := range ops {
		if o.kind == "checkout_created" {
			totals[o.family] += o.cents
			nCent[o.family]++
		}
	}
	var grand int64
	fmt.Printf("  %-8s %-6s %s\n", "family", "笔数", "金额合计(分)")
	for _, f := range []string{"fam-a", "fam-b", "fam-c"} {
		fmt.Printf("  %-8s %-6d %d\n", f, nCent[f], totals[f])
		grand += totals[f]
	}
	fmt.Printf("  三家合计 = %d 分；参与合计的家庭数 = %d（整数逐分可对账，float 累加会漂）。\n", grand, len(totals))
	hdr("5. 学员侧真环境怎么用这条判据")
	fmt.Println("  把服务日志按 JSON 行落文件后，捞某一家庭全部日志：")
	fmt.Println("      grep '\"family_id\":\"fam-b\"' app.log")
	fmt.Println("  配合 jq 再按金额筛：")
	fmt.Println("      grep '\"family_id\":\"fam-b\"' app.log | jq 'select(.amount_cents>5000)'")
	fmt.Println("  能这么筛的唯一前提：family_id 从一开始就作为字段进了每一条日志（判据④）。")
	fmt.Println("  今天的账：")
	fmt.Printf("  %-14s %-16s %s\n", "写法", "fam-b 可筛性", "组合条件(家庭+金额)")
	fmt.Printf("  %-14s %-16s %s\n", "fmt.Println", "靠字符串子串", "做不到(无字段)")
	fmt.Printf("  %-14s %-16s %s\n", "slog JSON", fmt.Sprintf("可(命中 %d 行)", len(hit)), "一次 JSON 字段比较")

	fmt.Println("\n=== W54 d07 到此结束 ===")
	fmt.Println("明天 d08：日志级别怎么分、request_id 怎么贯穿一次请求的多条日志，")
	fmt.Println("以及「不该进日志的东西」——金额和成员姓名整条 dump 出去，脱敏版对拍会点名被换掉的字段。")
}

