// W54 d08：日志级别别滥发、一次请求用 request_id 串起来、PII 不许裸奔
// 三块：① 跨家庭 404 / 非法 400 是预期内 4xx，被「>=400 全 Error」灌进 Error 会淹没真 5xx 告警——现场算噪声比；
// ② 一次请求多条日志用 request_id + client_request_id 贯穿，程序按 request_id 聚回链路（并发下交错）；
// ③ 姓名/手机/邮箱整条 dump 是合规事故，脱敏版用 slog ReplaceAttr 现场掩码并点名被换掉的字段。
// 确定性：slog JSONHandler 删 time / 关 source → 逐字节一致。跨家庭 404 不是 403；balance_cents 整数非 PII 不掩码。
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d08
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"strings"
)

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// secretKeys 是需要掩码的 PII 字段；amount/balance/member_id 不在此列（非 PII、排查要用）。
var secretKeys = map[string]bool{"full_name": true, "phone": true, "email": true}

// newJSON 造一个确定性 slog.Logger：删 time/source；mask=true 时顺带掩码 PII 字段。
func newJSON(w *bytes.Buffer, mask bool) *slog.Logger {
	re := func(_ []string, a slog.Attr) slog.Attr {
		if a.Key == slog.TimeKey || a.Key == slog.SourceKey {
			return slog.Attr{}
		}
		if mask && secretKeys[a.Key] {
			return slog.String(a.Key, redact(a.Key, a.Value.String()))
		}
		return a
	}
	return slog.New(slog.NewJSONHandler(w, &slog.HandlerOptions{AddSource: false, ReplaceAttr: re}))
}

func main() {
	hdr("0. 题面：日志不是越多越好，要能被过滤、能串起来、不泄密")
	fmt.Println("  三块：级别别滥发 / request_id 贯穿链路 / PII 不许裸奔。全部用 slog 现场跑。")
	evts := []struct {
		family, msg string
		status      int
	}{
		{"fam-a", "结账成功", 200},
		{"fam-b", "跨家庭读取被拒", 404},
		{"fam-a", "DB 连接失败", 500},
		{"fam-c", "时间窗参数非法", 400},
		{"fam-b", "结账成功", 200},
		{"fam-c", "跨家庭写入被拒", 404},
		{"fam-a", "报表生成超时", 503},
		{"fam-b", "分页 size 越界", 400},
		{"fam-a", "跨家庭读取被拒", 404},
		{"fam-c", "通知下发失败", 500},
		{"fam-b", "跨家庭读取被拒", 404},
		{"fam-a", "结账成功", 200},
		{"fam-c", "附件超限被拒", 400},
		{"fam-b", "预算服务不可用", 500},
		{"fam-a", "跨家庭读取被拒", 404},
		{"fam-c", "结账成功", 200},
	}
	hdr("1. 错误做法：if status>=400 { Error } —— 把 4xx 也灌进 Error")
	naiveErr, naive4, naive5 := 0, 0, 0
	fmt.Printf("  %-6s %-8s %-7s %s\n", "级别", "status", "family", "事件")
	for _, e := range evts {
		lvl := "INFO"
		if e.status >= 400 {
			lvl = "ERROR"
			naiveErr++
			if e.status < 500 {
				naive4++
			} else {
				naive5++
			}
		}
		fmt.Printf("  %-6s %-8d %-7s %s\n", lvl, e.status, e.family, e.msg)
	}
	fmt.Printf("  naive ERROR 条数 = %d，其中「预期内 4xx」= %d 条，真 5xx 故障 = %d 条。\n", naiveErr, naive4, naive5)
	fmt.Printf("  → 噪声比 %d/%d：每 %d 条 Error 里约 %.1f 条不是故障，值班会被训练成「Error 先看是不是越权」。\n",
		naive4, naiveErr, naiveErr, float64(naive4)/float64(naiveErr))
	hdr("2. 正确做法：按语义分级 —— 只有 5xx 才是 Error")
	corrErr, warn, info := 0, 0, 0
	correctOf := func(s int) string {
		switch {
		case s >= 500:
			return "ERROR"
		case s == 404:
			return "WARN" // 跨家庭 → 404：预期内拒绝，安全审计可筛，但不是故障
		default:
			return "INFO" // 200 正常 / 400 非法参数（正常拒绝）
		}
	}
	fmt.Printf("  %-6s %-8s %-7s %s\n", "级别", "status", "family", "事件")
	for _, e := range evts {
		lvl := correctOf(e.status)
		switch lvl {
		case "ERROR":
			corrErr++
		case "WARN":
			warn++
		default:
			info++
		}
		fmt.Printf("  %-6s %-8d %-7s %s\n", lvl, e.status, e.family, e.msg)
	}
	fmt.Printf("  分级结果：ERROR=%d（=真 5xx）, WARN=%d（=404 越权）, INFO=%d（200/400）。\n", corrErr, warn, info)
	fmt.Printf("  对照：naive ERROR=%d 被稀释到分级后 ERROR=%d —— 剩下的每条 Error 都值得叫醒人。\n", naiveErr, corrErr)
	hdr("3. request_id：一次请求多条日志，多条交错，程序聚回链路")
	lines := []struct {
		req, crid, fam, stage, msg string
		lvl                        slog.Level
	}{
		{"req-7001", "crid-A", "fam-b", "recv", "收到请求 POST /checkout", slog.LevelInfo},
		{"req-7002", "crid-B", "fam-a", "recv", "收到请求 GET /reports", slog.LevelInfo},
		{"req-7003", "crid-C", "fam-b", "recv", "收到请求 GET /members/mem-9", slog.LevelInfo},
		{"req-7001", "crid-A", "fam-b", "authz", "鉴权通过 role=owner", slog.LevelInfo},
		{"req-7002", "crid-B", "fam-a", "authz", "跨家庭访问被拒 status=404", slog.LevelWarn},
		{"req-7003", "crid-C", "fam-b", "authz", "鉴权通过 role=admin", slog.LevelInfo},
		{"req-7001", "crid-A", "fam-b", "db", "插入流水 1 行 amount_cents=4800", slog.LevelInfo},
		{"req-7003", "crid-C", "fam-b", "db", "读成员 1 行 member_id=mem-9", slog.LevelInfo},
		{"req-7001", "crid-A", "fam-b", "resp", "返回 201", slog.LevelInfo},
		{"req-7002", "crid-B", "fam-a", "resp", "返回 404", slog.LevelInfo},
		{"req-7003", "crid-C", "fam-b", "resp", "返回 200", slog.LevelInfo},
	}
	var buf bytes.Buffer
	jl := newJSON(&buf, false)
	for _, l := range lines {
		jl.Log(context.Background(), l.lvl, l.msg,
			"request_id", l.req, "client_request_id", l.crid, "family_id", l.fam, "stage", l.stage)
	}
	mixed := strings.Split(strings.TrimRight(buf.String(), "\n"), "\n")
	fmt.Println("  交错落盘（并发下看不出各请求经历了什么）：")
	for _, m := range mixed {
		fmt.Println("    " + m)
	}
	order := []string{}
	group := map[string][]string{}
	for _, m := range mixed {
		var p struct {
			Req string `json:"request_id"`
		}
		_ = json.Unmarshal([]byte(m), &p)
		if _, ok := group[p.Req]; !ok {
			order = append(order, p.Req)
		}
		group[p.Req] = append(group[p.Req], m)
	}
	fmt.Println("  聚回链路（同一 request_id 的行拉出来还原一次请求的每一步）：")
	for _, r := range order {
