// redact 按字段类型给一个稳定掩码（不依赖随机/时间 → 输出确定）。
func redact(key, v string) string {
	r := []rune(v)
	switch key {
	case "full_name":
		if len(r) == 0 {
			return "**"
		}
		return string(r[0]) + strings.Repeat("*", max(1, len(r)-1))
	case "phone":
		if len(v) < 7 {
			return "****"
		}
		return v[:3] + "****" + v[len(v)-4:]
	case "email":
