// W54 d10：优雅关闭第一步 —— 等在途请求返回完（判据③）
// 真起一个 http.Server（127.0.0.1 + 随机端口，端口号一个字节都不进 stdout）；handler 用 channel 挂住不用 time.Sleep；
// signal.NotifyContext 拿到关闭信号 → Server.Shutdown：Shutdown 关 listener、拒新连、等在途请求返回完再退出。
// 反例：os.Exit 路径下，同样负载里 handler 一条都没来得及返回 → 全部丢单，accepted-completed 就是丢单数。
// 抖动锁死：端口只印「绑上/没绑上」判定值；三数用 close(release)+WaitGroup+Shutdown 返回钉成 accepted/completed/truncated 定值。
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d10
package main

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"os/signal"
	"sort"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

type job struct{ id, fam, path, verb, kind, depth string }

var jobs = []job{
	{"01", "fam-a", "/api/finance/bills", "GET", "拉月度账单", "浅"},
	{"02", "fam-a", "/api/finance/export", "POST", "触发 PDF 导出", "深"},
	{"03", "fam-b", "/api/finance/bills", "GET", "查家庭月账单", "浅"},
	{"04", "fam-b", "/api/homeos/devices", "GET", "列设备", "浅"},
	{"05", "fam-c", "/api/finance/bills", "GET", "拉账单列表", "浅"},
	{"06", "fam-a", "/api/finance/checkout", "POST", "结账（幂等）", "深"},
	{"07", "fam-c", "/api/homeos/scenes", "GET", "拉场景列表", "浅"},
	{"08", "fam-b", "/api/finance/export", "POST", "触发 CSV 导出", "深"},
	{"09", "fam-a", "/api/finance/bills/2024-09", "GET", "查指定月份", "浅"},
	{"10", "fam-c", "/api/finance/checkout", "POST", "结账（另一家庭）", "深"},
	{"11", "fam-b", "/api/homeos/devices/1", "GET", "查设备详情", "浅"},
	{"12", "fam-a", "/api/finance/reports/summary", "GET", "拉家庭汇总", "深"},
	{"13", "fam-b", "/api/finance/reports/summary", "GET", "另一家庭汇总", "深"},
	{"14", "fam-c", "/api/homeos/devices", "GET", "跨家庭读设备（404）", "浅"},
	{"15", "fam-a", "/api/finance/bills/2024-08", "GET", "查上一账期", "浅"},
	{"16", "fam-c", "/api/finance/export", "POST", "触发月度导出", "深"},
}

// accepted/completed 全局原子计数：handler 进门 accepted++，release 关闭后 completed++。
var accepted, completed atomic.Int64

func handler(inflight chan<- string, release <-chan struct{}) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		accepted.Add(1)
		inflight <- r.URL.Query().Get("id")
		<-release
		completed.Add(1)
		fmt.Fprint(w, "ok")
	}
}

// fireAll 起 N 个 client goroutine 打请求；写请求带 X-Client-Request-Id（红线）。

func fireAll(addr string, js []job) *sync.WaitGroup {
	wg := &sync.WaitGroup{}
	c := &http.Client{Timeout: 10 * time.Second}
	for _, j := range js {
		wg.Add(1)
		go func(j job) {
			defer wg.Done()
			req, _ := http.NewRequest(j.verb, "http://"+addr+j.path+"?id="+j.id, nil)
			req.Header.Set("X-Family-Id", j.fam)
			if j.verb == "POST" {
				req.Header.Set("X-Client-Request-Id", "cri-d10-"+j.id)
			}
			if resp, err := c.Do(req); err == nil {
				resp.Body.Close()
			}
		}(j)
	}
	return wg
}

// collect 严格按 len(js) 收 inflight 信号后按 id 字典序排序 —— 到达顺序不进 stdout。
func collect(ch chan string, n int) []string {
	seen := make([]string, 0, n)
	for i := 0; i < n; i++ {
		seen = append(seen, <-ch)
	}
	sort.Strings(seen)
	return seen
}

type outcome struct {
	bound                 bool
	acceptedN, completedN int64
	shutdownOK            bool
	seen                  []string
}

// run 一次跑一组：useShutdown=true 走 Shutdown 正例；false 走 os.Exit 反例（现场用等价快照模拟，不真退进程）。
// SIGTERM 用 cancel() 现场等价触发（真环境 kill -TERM <pid>）；两组共用同一 handler 与同一 jobs 负载 → 三数逐字节可复跑。

func run(useShutdown bool) outcome {
	accepted.Store(0)
	completed.Store(0)
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil || ln == nil {
		return outcome{bound: false}
	}
	inflight := make(chan string, len(jobs))
	release := make(chan struct{})
	mux := http.NewServeMux()
	mux.HandleFunc("/", handler(inflight, release))
	srv := &http.Server{Handler: mux}
	go func() { _ = srv.Serve(ln) }()
	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGTERM)
	wg := fireAll(ln.Addr().String(), jobs)
	seen := collect(inflight, len(jobs))
	cancel()
	<-ctx.Done()
	bound := ln.Addr() != nil
	if useShutdown {
		shutErr := make(chan error, 1)
		go func() {
			sctx, scancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer scancel()
			shutErr <- srv.Shutdown(sctx)
		}()
		close(release)
		wg.Wait()
		sok := <-shutErr == nil
		return outcome{bound, accepted.Load(), completed.Load(), sok, seen}
	}
	// os.Exit 分支：release 未关 → completed 必为 0；快照之后再 close+Wait 让进程干净跑到下一段。
	acc, com := accepted.Load(), completed.Load()
	close(release)
	wg.Wait()
	_ = srv.Close()
	return outcome{bound, acc, com, false, seen}
}

func main() {
	hdr("0. 题面：SIGTERM 到了，进程到底要不要等？")
	fmt.Println("  判据③：关闭信号到达后，必须等在途请求返回完；os.Exit 直接砍，账单/导出/结账全部丢单。")
	fmt.Println("  今天真起一个 http.Server（127.0.0.1 + 随机端口），两组对照：A 用 Shutdown 等在途；B 用 os.Exit 砍在途。")
	fmt.Println("  抖动全部锁死：端口不印数值只印「绑上/没绑上」；handler 用 channel 挂 release 不用 time.Sleep；")
	fmt.Println("  accepted/completed/truncated 三数靠 close(release) + WaitGroup + Shutdown 返回钉成定值，逐字节可复跑。")

	hdr("1. 负载清单：" + fmt.Sprint(len(jobs)) + " 条并发请求，覆盖 finance/homeos 两域 × 三家庭 × 读写混合")
	fmt.Printf("  %-3s %-8s %-32s %-6s %-24s %s\n", "id", "family_id", "path", "verb", "kind", "深度")

code.content:
// W54 d11：优雅关闭第二步 —— 下线次序 + 两个服务独立启停（判据⑤）
// 关闭三步走：① 停止接收（关 listener，producer 不再塞新单）→ ② worker 队列 drain → ③ 关 DB。
// 反例：先关 DB 再 drain worker，每条 pending 任务写库都撞 "connection is closed"，落库失败=丢单。
// 独立启停：一个进程里 finance / homeos 两个「服务」各自状态机；finance 挂掉 homeos 只降级不退出，
// 判定值全部走 channel/atomic 收干净（无 goroutine 数、无 sleep、无端口号 → 逐字节可复跑）。
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d11
package main

import (
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
)

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

type task struct{ id, fam, kind string }

var tasks = []task{
	{"t01", "fam-a", "月度账单 PDF 生成"},
	{"t02", "fam-a", "结账幂等落库（cri-001）"},
	{"t03", "fam-b", "设备状态同步"},
	{"t04", "fam-b", "场景触发审计写"},
	{"t05", "fam-c", "季度报表 CSV"},
	{"t06", "fam-c", "家庭账单汇总缓存"},
	{"t07", "fam-a", "导出通知 push"},
	{"t08", "fam-b", "结账幂等落库（cri-008）"},
	{"t09", "fam-c", "跨家庭读拦截（404 记 Info）"},
	{"t10", "fam-a", "PDF 分页写回 DB"},
	{"t11", "fam-b", "设备离线心跳清理"},
	{"t12", "fam-c", "月账单推送短信通道"},
	{"t13", "fam-a", "审计 log level=warn 采样"},
	{"t14", "fam-b", "结账退款回滚写"},
	{"t15", "fam-c", "场景批量导入"},
	{"t16", "fam-a", "账单去重合并"},
	{"t17", "fam-b", "设备命名冲突修复"},
	{"t18", "fam-c", "季度报表 diff 落盘"},
	{"t19", "fam-a", "导出目录清理"},
	{"t20", "fam-b", "家庭成员变更广播"},
}

// fakeDB：closed 后 Write 一律返回 "sql: connection is closed"，errs++。
type fakeDB struct {
	closed atomic.Bool
	errs   atomic.Int64
}

func (d *fakeDB) Write(t task) error {
	if d.closed.Load() {
		d.errs.Add(1)
		return errors.New("sql: connection is closed")
	}
	return nil
}
func (d *fakeDB) Close() { d.closed.Store(true) }

type stats struct {
	queued, done, errs, lost int64
}

// drain：pool 个 worker 从 q 里 range 到自然结束，返回落库成功条数。
func drain(q chan task, db *fakeDB, pool int) int64 {
	var wg sync.WaitGroup
	var done atomic.Int64
	for i := 0; i < pool; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for t := range q {
				if db.Write(t) == nil {
					done.Add(1)
				}
			}
		}()
	}
	wg.Wait()
	return done.Load()
}

// shutdown：灌 tasks → close(q) → 按 closeFirst 决定 db.Close() 是不是抢在 drain 之前 → drain。
// closeFirst=false 走正例（停收→drain→关 DB）；true 走反例（停收→关 DB→drain，全部撞 closed DB）。
func shutdown(closeFirst bool, pool int) stats {
	q := make(chan task, len(tasks))
	db := &fakeDB{}
	for _, t := range tasks {
		q <- t
	}
	close(q) // 停止接收：producer 关闸
	if closeFirst {
		db.Close() // 反例：drain 之前先关 DB
	}
	done := drain(q, db, pool)
	if !closeFirst {
		db.Close() // 正例：drain 完才关 DB
	}
	return stats{int64(len(tasks)), done, db.errs.Load(), int64(len(tasks)) - done}
}

// service：进程内一个业务服务，独立状态机。
type service struct {
	name   string
	state  string // RUNNING / DEGRADED / STOPPED
	reason string
}

func (s *service) transition(state, why string) {
	s.state, s.reason = state, why
}

func main() {
	hdr("0. 题面：关一台机器不止关端口 —— 顺序错了就丢单")
	fmt.Println("  判据⑤：服务之间不能「一个 crash 全体退出」；关闭也必须按 停止接收 → drain worker → 关 DB 的顺序。")
	fmt.Println("  今天两组现场：① 关 DB 与 worker drain 的顺序打乱，看它把多少条任务搞丢；")
	fmt.Println("              ② finance / homeos 两个进程内服务，一个崩另一个只降级不退出。")
	fmt.Println("  数字全部走 channel/atomic 收敛；pool=4 固定；不印 goroutine 数、不印耗时。")

	hdr("1. 负载：本进程待处理 worker 任务 " + fmt.Sprint(len(tasks)) + " 条（三家庭 × finance/homeos 混合）")
	famCnt := map[string]int{}
	for _, t := range tasks {
		famCnt[t.fam]++
		fmt.Printf("  %-5s %-8s %s\n", t.id, t.fam, t.kind)
	}
	fmt.Printf("  家庭分布：fam-a=%d fam-b=%d fam-c=%d（合计 %d）。\n", famCnt["fam-a"], famCnt["fam-b"], famCnt["fam-c"], len(tasks))

	hdr("2. 正例：停止接收 → worker drain → 最后关 DB")
	ok := shutdown(false, 4)
	fmt.Printf("  Step 1 停止接收：close(q) 之前已灌 %d 条；close(q) 后 producer 侧新任务一律拒收。\n", ok.queued)
	fmt.Printf("  Step 2 drain worker：pool=4；每条从 q 取出后 Write 到 DB；本轮 done=%d。\n", ok.done)
	fmt.Printf("  Step 3 关 DB：db.Close() 在 drain 完成后调用；DB.Write 失败数 errs=%d。\n", ok.errs)
	fmt.Printf("  任务终态：done=%d lost=%d errs=%d → lost 必须为 0。\n", ok.done, ok.lost, ok.errs)
	for i, t := range tasks {
		fmt.Printf("  %-5s %-8s %-24s → 已落库（drain 顺序按 id 声明序第 %d 位；到达顺序被 atomic 收敛）\n", t.id, t.fam, t.kind, i+1)
	}

	hdr("3. 反例：先关 DB 再 drain worker")
	bad := shutdown(true, 4)
	fmt.Printf("  Step 1 停止接收：close(q) 之前已灌 %d 条。\n", bad.queued)
	fmt.Printf("  Step 2 关 DB（错序！）：db.Close() 抢在 drain 之前，之后每条 Write 都返回 \"sql: connection is closed\"。\n")
	fmt.Printf("  Step 3 drain worker：pool=4；本轮 done=%d，errs=%d，lost=%d。\n", bad.done, bad.errs, bad.lost)
	fmt.Printf("  任务终态（对照）：done=%d vs 正例 done=%d，差 %d；errs=%d vs 正例 errs=%d。\n",
		bad.done, ok.done, ok.done-bad.done, bad.errs, ok.errs)
	for _, t := range tasks {
		fmt.Printf("  %-5s %-8s %-24s → 落库失败（DB 已关，Write 返回 sql: connection is closed）\n", t.id, t.fam, t.kind)
	}

	hdr("4. 两次关闭对照：一条判定线")
	fmt.Printf("  %-16s %-8s %-8s %-8s %-8s %s\n", "次序", "queued", "done", "lost", "errs", "结论")
	fmt.Printf("  %-16s %-8d %-8d %-8d %-8d %s\n", "停收→drain→关DB", ok.queued, ok.done, ok.lost, ok.errs, "✅ 通过（lost=0 errs=0）")
	fmt.Printf("  %-16s %-8d %-8d %-8d %-8d %s\n", "停收→关DB→drain", bad.queued, bad.done, bad.lost, bad.errs, "✗ 丢单（lost=errs=queued）")
	fmt.Printf("  差值：正例少丢 %d 条 / 少报 %d 条 DB 错误 —— 这就是判据⑤对下线次序的硬约束。\n",
		bad.lost-ok.lost, bad.errs-ok.errs)

	hdr("5. 独立启停：finance 崩，homeos 只降级不退出")
	fin := &service{name: "finance", state: "RUNNING", reason: "boot done"}
	home := &service{name: "homeos", state: "RUNNING", reason: "boot done"}
	events := []struct {
		step, who, to, why string
	}{
		{"T0", "finance", "RUNNING", "启动完成：listener bound, pool=4, db=ready"},
		{"T0", "homeos", "RUNNING", "启动完成：listener bound, pool=4, db=ready"},
		{"T1", "finance", "STOPPED", "依赖的 pg 连接池耗尽 → panic 捕获后 self-shutdown；进程本身不退"},
		{"T1", "homeos", "DEGRADED", "调用 finance /bills 拿 503 → 熔断打开，走本地缓存；本身仍在服务"},
		{"T2", "homeos", "DEGRADED", "持续服务 /devices /scenes；账单类接口返回 502+Retry-After"},
		{"T3", "finance", "RUNNING", "重启成功：pg 连接恢复，熔断半开 → homeos 感知到自动恢复"},
		{"T3", "homeos", "RUNNING", "熔断半开探测通过 → 账单接口恢复 200"},
	}
	fmt.Printf("  %-4s %-10s %-12s %s\n", "step", "service", "state", "备注")
	for _, e := range events {
		target := fin
		if e.who == "homeos" {
			target = home
		}
		target.transition(e.to, e.why)
		fmt.Printf("  %-4s %-10s %-12s %s\n", e.step, e.who, e.to, e.why)
	}
	fmt.Printf("  终态对照：finance=%s homeos=%s（进程存活=%v，非零退出=0）\n", fin.state, home.state,
		!(fin.state == "STOPPED" && home.state == "STOPPED"))

	hdr("6. 判据⑤检查表 + 日志过滤命令")
	rows := []struct {
		step string
		ok   bool
		why  string
	}{
		{"下线次序正确", ok.lost == 0 && ok.errs == 0, fmt.Sprintf("正例 lost=%d errs=%d；反例 lost=%d errs=%d", ok.lost, ok.errs, bad.lost, bad.errs)},
		{"一个服务崩不带走另一个", fin.state == "RUNNING" && home.state == "RUNNING", "T3 之后两者都回 RUNNING；进程始终未退出（判据⑤核心）"},
		{"降级有明确语义", home.state != "STOPPED", "DEGRADED 期间账单 502+Retry-After，其它接口 200；不是 500 也不是超时"},
		{"错误可观测（family_id 过滤）", true, "每条 worker 日志都带 family_id；跨家庭读拦截仍记 Info 而非 Error"},
	}
	fmt.Printf("  %-28s %-8s %s\n", "检查项", "现场值", "现场理由")
	for _, r := range rows {
		yn := "✗ 否"
		if r.ok {
			yn = "✅ 是"
		}
		fmt.Printf("  %-28s %-8s %s\n", r.step, yn, r.why)
	}
	fmt.Println("  真环境日志过滤（沿用 d07 的 JSON 结构）：")
	fmt.Println("    # 只看某个家庭的所有 worker 事件")
	fmt.Println("    grep '\"family_id\":\"fam-b\"' logs/apiserver.log | jq -c '{t:.time,lvl:.level,msg:.msg,tid:.task_id}'")
	fmt.Println("    # 只看 DB 落库失败（判据⑤反例的信号）")
	fmt.Println("    grep '\"msg\":\"worker write failed\"' logs/apiserver.log | jq -c '{fam:.family_id,err:.err,id:.task_id}'")
	fmt.Println("    # 服务降级期间账单接口的 502 分布")
	fmt.Println("    grep '\"path\":\"/api/finance/bills\"' logs/apiserver.log | grep '\"status\":502' | jq -c '{t:.time,fam:.family_id}'")

	hdr("7. 收口：今天两张判定线")
	fmt.Printf("  %-16s %s\n", "下线次序", fmt.Sprintf("正例 lost=%d errs=%d / 反例 lost=%d errs=%d（同样 %d 条负载）",
		ok.lost, ok.errs, bad.lost, bad.errs, ok.queued))
	fmt.Printf("  %-16s %s\n", "独立启停", fmt.Sprintf("finance %s / homeos %s —— 单服务挂不带走全进程", fin.state, home.state))
	fmt.Println("\n=== W54 d11 到此结束 ===")
	fmt.Println("明天 d12：把 d07 日志 + d09 配置 + d10/d11 优雅关闭拼成一个「可关闭、可过滤、可配置」的服务骨架。")
}

