// W54 d11：优雅关闭第二步 —— 下线次序 + 两个服务独立启停（判据⑤）
// 关闭三步走：① 停止接收（关 listener，producer 不再塞新单）→ ② worker 队列 drain → ③ 关 DB。
// 反例：先关 DB 再 drain worker，每条 pending 任务写库都撞 "connection is closed"，落库失败=丢单。
// 独立启停：一个进程里 finance / homeos 两个「服务」各自状态机；finance 挂掉 homeos 只降级不退出，
// 判定值全部走 channel/atomic 收干净（无 goroutine 数、无 sleep、无端口号 → 逐字节可复跑）。
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d11
package main

import (
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
)

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

type task struct{ id, fam, kind string }

var tasks = []task{
	{"t01", "fam-a", "月度账单 PDF 生成"},
	{"t02", "fam-a", "结账幂等落库（cri-001）"},
	{"t03", "fam-b", "设备状态同步"},
	{"t04", "fam-b", "场景触发审计写"},
	{"t05", "fam-c", "季度报表 CSV"},
	{"t06", "fam-c", "家庭账单汇总缓存"},
	{"t07", "fam-a", "导出通知 push"},
	{"t08", "fam-b", "结账幂等落库（cri-008）"},
	{"t09", "fam-c", "跨家庭读拦截（404 记 Info）"},
	{"t10", "fam-a", "PDF 分页写回 DB"},
	{"t11", "fam-b", "设备离线心跳清理"},
	{"t12", "fam-c", "月账单推送短信通道"},
	{"t13", "fam-a", "审计 log level=warn 采样"},
	{"t14", "fam-b", "结账退款回滚写"},
	{"t15", "fam-c", "场景批量导入"},
	{"t16", "fam-a", "账单去重合并"},
	{"t17", "fam-b", "设备命名冲突修复"},
	{"t18", "fam-c", "季度报表 diff 落盘"},
	{"t19", "fam-a", "导出目录清理"},
	{"t20", "fam-b", "家庭成员变更广播"},
}

// fakeDB：closed 后 Write 一律返回 "sql: connection is closed"，errs++。
type fakeDB struct {
	closed atomic.Bool
	errs   atomic.Int64
}

func (d *fakeDB) Write(t task) error {
	if d.closed.Load() {
		d.errs.Add(1)
		return errors.New("sql: connection is closed")
	}
	return nil
}

func (d *fakeDB) Close() { d.closed.Store(true) }

type stats struct {
	queued, done, errs, lost int64
}

// drain：pool 个 worker 从 q 里 range 到自然结束，返回落库成功条数。
func drain(q chan task, db *fakeDB, pool int) int64 {
	var wg sync.WaitGroup
	var done atomic.Int64
	for i := 0; i < pool; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for t := range q {
				if db.Write(t) == nil {
					done.Add(1)
				}
			}
		}()
	}
	wg.Wait()
	return done.Load()
}

// shutdown：灌 tasks → close(q) → 按 closeFirst 决定 db.Close() 是不是抢在 drain 之前 → drain。
// closeFirst=false 走正例（停收→drain→关 DB）；true 走反例（停收→关 DB→drain，全部撞 closed DB）。
func shutdown(closeFirst bool, pool int) stats {
	q := make(chan task, len(tasks))
	db := &fakeDB{}
	for _, t := range tasks {
		q <- t
	}
	close(q) // 停止接收：producer 关闸
	if closeFirst {
		db.Close() // 反例：drain 之前先关 DB
	}
	done := drain(q, db, pool)
	if !closeFirst {
		db.Close() // 正例：drain 完才关 DB
	}
	return stats{int64(len(tasks)), done, db.errs.Load(), int64(len(tasks)) - done}
}

// service：进程内一个业务服务，独立状态机。
type service struct {
	name   string
	state  string // RUNNING / DEGRADED / STOPPED
	reason string
}

func (s *service) transition(state, why string) {
	s.state, s.reason = state, why
}

func main() {
	hdr("0. 题面：关一台机器不止关端口 —— 顺序错了就丢单")
	fmt.Println("  判据⑤：服务之间不能「一个 crash 全体退出」；关闭也必须按 停止接收 → drain worker → 关 DB 的顺序。")
	fmt.Println("  今天两组现场：① 关 DB 与 worker drain 的顺序打乱，看它把多少条任务搞丢；")
	fmt.Println("              ② finance / homeos 两个进程内服务，一个崩另一个只降级不退出。")
	fmt.Println("  数字全部走 channel/atomic 收敛；pool=4 固定；不印 goroutine 数、不印耗时。")

	hdr("1. 负载：本进程待处理 worker 任务 " + fmt.Sprint(len(tasks)) + " 条（三家庭 × finance/homeos 混合）")
	famCnt := map[string]int{}
	for _, t := range tasks {
		famCnt[t.fam]++
		fmt.Printf("  %-5s %-8s %s\n", t.id, t.fam, t.kind)
	}
	fmt.Printf("  家庭分布：fam-a=%d fam-b=%d fam-c=%d（合计 %d）。\n", famCnt["fam-a"], famCnt["fam-b"], famCnt["fam-c"], len(tasks))

	hdr("2. 正例：停止接收 → worker drain → 最后关 DB")
	ok := shutdown(false, 4)
	fmt.Printf("  Step 1 停止接收：close(q) 之前已灌 %d 条；close(q) 后 producer 侧新任务一律拒收。\n", ok.queued)
	fmt.Printf("  Step 2 drain worker：pool=4；每条从 q 取出后 Write 到 DB；本轮 done=%d。\n", ok.done)
	fmt.Printf("  Step 3 关 DB：db.Close() 在 drain 完成后调用；DB.Write 失败数 errs=%d。\n", ok.errs)
	fmt.Printf("  任务终态：done=%d lost=%d errs=%d → lost 必须为 0。\n", ok.done, ok.lost, ok.errs)
	for i, t := range tasks {
		fmt.Printf("  %-5s %-8s %-24s → 已落库（drain 顺序按 id 声明序第 %d 位；到达顺序被 atomic 收敛）\n", t.id, t.fam, t.kind, i+1)
	}

	hdr("3. 反例：先关 DB 再 drain worker")
	bad := shutdown(true, 4)
	fmt.Printf("  Step 1 停止接收：close(q) 之前已灌 %d 条。\n", bad.queued)
	fmt.Printf("  Step 2 关 DB（错序！）：db.Close() 抢在 drain 之前，之后每条 Write 都返回 \"sql: connection is closed\"。\n")
	fmt.Printf("  Step 3 drain worker：pool=4；本轮 done=%d，errs=%d，lost=%d。\n", bad.done, bad.errs, bad.lost)
	fmt.Printf("  任务终态（对照）：done=%d vs 正例 done=%d，差 %d；errs=%d vs 正例 errs=%d。\n",
		bad.done, ok.done, ok.done-bad.done, bad.errs, ok.errs)
	for _, t := range tasks {
		fmt.Printf("  %-5s %-8s %-24s → 落库失败（DB 已关，Write 返回 sql: connection is closed）\n", t.id, t.fam, t.kind)
	}

	hdr("4. 两次关闭对照：一条判定线")
	fmt.Printf("  %-16s %-8s %-8s %-8s %-8s %s\n", "次序", "queued", "done", "lost", "errs", "结论")
	fmt.Printf("  %-16s %-8d %-8d %-8d %-8d %s\n", "停收→drain→关DB", ok.queued, ok.done, ok.lost, ok.errs, "✅ 通过（lost=0 errs=0）")
	fmt.Printf("  %-16s %-8d %-8d %-8d %-8d %s\n", "停收→关DB→drain", bad.queued, bad.done, bad.lost, bad.errs, "✗ 丢单（lost=errs=queued）")
	fmt.Printf("  差值：正例少丢 %d 条 / 少报 %d 条 DB 错误 —— 这就是判据⑤对下线次序的硬约束。\n",
		bad.lost-ok.lost, bad.errs-ok.errs)

	hdr("5. 独立启停：finance 崩，homeos 只降级不退出")
	fin := &service{name: "finance", state: "RUNNING", reason: "boot done"}
	home := &service{name: "homeos", state: "RUNNING", reason: "boot done"}
	events := []struct {
		step, who, to, why string
	}{
		{"T0", "finance", "RUNNING", "启动完成：listener bound, pool=4, db=ready"},

