	fmt.Println("              ② context.WithTimeout 端到端串联 handler→service→repo→DB，超时后 goroutine 必须自己收；")
	fmt.Println("              ③ 错误语义：上游超时=504、依赖崩=503、业务错=4xx；跨家庭读永远 404，禁止 403/500 混用。")

	hdr("6. 收口：W54 五张判定线（d07-d12 全部串起来）")
	fmt.Printf("  %-16s %s\n", "① 结构化", fmt.Sprintf("JSON 日志 %d 条全部带 family_id/request_id/amount_cents；程序真解 JSON 得到 a=%d b=%d c=%d",
		len(logEvents), famCnt["fam-a"], famCnt["fam-b"], famCnt["fam-c"]))
	fmt.Printf("  %-16s %s\n", "② 级别", fmt.Sprintf("INFO=%d WARN=%d ERROR=%d；404 记 Warn 不记 Error", lvlCnt["INFO"], lvlCnt["WARN"], lvlCnt["ERROR"]))
	fmt.Printf("  %-16s %s\n", "③ 优雅关闭", fmt.Sprintf("accepted=%d completed=%d truncated=%d（Shutdown 返回 nil=%v）", acc, com, tr, sok))
	fmt.Printf("  %-16s %s\n", "④ 配置加载", fmt.Sprintf("%d 个 key env>file>default 逐条现场；关键项 fail fast", len(cfgEntries)))
