// W54 d12：W54 收口 —— 一个可关闭、可过滤、可配置的服务骨架
// 把 d07 结构化日志 + d09 配置加载 + d10/d11 优雅关闭拼成一个最小可跑的服务骨架（单文件演示；homecube/server/internal/platform/{logger,cfg,httpapi} 包形态）。
// platform/logger：slog JSON，去时间/去 source；每条都带 family_id/request_id/amount_cents（PII 全走 *_cents 整数红线）。
// platform/cfg：env > file > default 三级优先级 + 关键项 fail fast + atomic.Pointer 整份替换。
// platform/httpapi：真 http.Server（127.0.0.1 随机端口，端口号不进 stdout），SIGTERM → Shutdown 等在途；三数由 close(release)+WaitGroup 钉死。
// 判据③④⑤逐条打 ✅ 并给真环境复跑命令（kill -TERM / grep family_id / go test -race）；结束交接 W55（并发聚合 + context 超时）。
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d12
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os/signal"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

const NA = "—"

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---------- internal/platform/logger 形状 ----------

func dropAttr(_ []string, a slog.Attr) slog.Attr {
	if a.Key == slog.TimeKey || a.Key == slog.SourceKey {
		return slog.Attr{}
	}
	return a
}
func newLogger(w *bytes.Buffer) *slog.Logger {
	return slog.New(slog.NewJSONHandler(w, &slog.HandlerOptions{AddSource: false, ReplaceAttr: dropAttr}))
}
func levelOf(s string) slog.Level {
	if s == "ERROR" {
		return slog.LevelError
	}
	if s == "WARN" {
		return slog.LevelWarn
	}
	return slog.LevelInfo
}

// logEv 全部字段字符串化，slog.Level/amount_cents 现场由 levelOf+ParseInt 转回；这样切片可以一行一个事件。
type logEv struct{ lvl, msg, fam, rid, cents string }

func handler(inflight chan<- string, release <-chan struct{}) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		accepted.Add(1)
		inflight <- r.URL.Query().Get("id")
		<-release
		completed.Add(1)
		fmt.Fprint(w, "ok")
	}
}

// bootAndShutdown：真 http.Server + 灌负载 + cancel() 现场等价 SIGTERM + Shutdown 等在途；三数由 close(release)+wg 钉成定值。
func bootAndShutdown() (int64, int64, int64, bool) {
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	if ln == nil {
		return 0, 0, 0, false
	}
	inflight := make(chan string, len(srvReqs))
	release := make(chan struct{})
	srv := &http.Server{Handler: http.HandlerFunc(handler(inflight, release))}
	go srv.Serve(ln)
	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGTERM)
	defer cancel()
	var wg sync.WaitGroup
	c := &http.Client{Timeout: 10 * time.Second}
	for _, r := range srvReqs {
		wg.Add(1)
		go func(r srvReq) {
			defer wg.Done()
			req, _ := http.NewRequest(r.verb, "http://"+ln.Addr().String()+r.path+"?id="+r.id, nil)
			req.Header.Set("X-Family-Id", r.fam)
			req.Header.Set("X-Client-Request-Id", "cri-d12-"+r.id)
			if resp, err := c.Do(req); err == nil {
				resp.Body.Close()
			}
		}(r)
	}
	for range srvReqs {
		<-inflight
	}
	cancel()
	<-ctx.Done()
	shutErr := make(chan error, 1)
	go func() {
		sctx, scancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer scancel()
		shutErr <- srv.Shutdown(sctx)
	}()
	close(release)
	wg.Wait()
	return accepted.Load(), completed.Load(), accepted.Load() - completed.Load(), <-shutErr == nil
}

func main() {
	hdr("0. 题面：d07+d09+d10+d11 拼成一个能跑的最小服务骨架")
	fmt.Println("  W54 四件事一次串起来：结构化日志（family_id 打得穿）+ 三级配置（env>file>default+fail fast）+ 优雅关闭（Shutdown 等在途）。")
	fmt.Println("  下面三段各演示一个 platform 包的形状，最后按判据③④⑤逐条打 ✅ 并给真环境复跑命令；结束交给 W55。")
	fmt.Println("  抖动锁死：端口不印数值只印「绑上/没绑上」；JSON 日志去 time/source；Shutdown 三数用 close(release)+WaitGroup 钉死。")

	hdr("1. internal/platform/logger：现场生成 " + fmt.Sprint(len(logEvents)) + " 条 JSON 日志（去时间/去 source）")

var lbuf bytes.Buffer
lg := newLogger(&lbuf)
ctx0 := context.Background()
for _, e := range logEvents {
	n, _ := strconv.ParseInt(e.cents, 10, 64)
	lg.LogAttrs(ctx0, levelOf(e.lvl), e.msg,
		slog.String("family_id", e.fam),
		slog.String("request_id", e.rid),
		slog.Int64("amount_cents", n))
}
lines := strings.Split(strings.TrimRight(lbuf.String(), "\n"), "\n")
for _, ln := range lines {
	fmt.Println("  " + ln)
}
famCnt, lvlCnt := map[string]int{}, map[string]int{}
for _, ln := range lines {
	var m map[string]any
	if err := json.Unmarshal([]byte(ln), &m); err != nil {
		continue
	}
	if f, ok := m["family_id"].(string); ok {
		famCnt[f]++
	}
	if l, ok := m["level"].(string); ok {
		lvlCnt[l]++
	}
}
fmt.Printf("  家庭过滤（程序真解 JSON）：fam-a=%d fam-b=%d fam-c=%d，合计 %d（应 =%d）。\n",
	famCnt["fam-a"], famCnt["fam-b"], famCnt["fam-c"], famCnt["fam-a"]+famCnt["fam-b"]+famCnt["fam-c"], len(lines))
fmt.Printf("  级别分布：INFO=%d WARN=%d ERROR=%d —— 404 记 Warn 不记 Error，别把告警池淹掉。\n",
	lvlCnt["INFO"], lvlCnt["WARN"], lvlCnt["ERROR"])
fmt.Println("  学员侧真环境过滤（同 family_id 单引号 JSON 字段）：")
fmt.Println("      grep '\"family_id\":\"fam-b\"' logs/apiserver.log | jq -c '{lvl:.level,msg:.msg,rid:.request_id,cents:.amount_cents}'")

hdr("2. internal/platform/cfg：" + fmt.Sprint(len(cfgEntries)) + " 个 key 三级优先级 + fail fast + atomic.Pointer")
fmt.Printf("  %-22s %-24s %-24s %-24s %-24s %s\n", "key", "DEFAULT", "FILE", "ENV", "终值", "胜出")
winE, winF, winD := 0, 0, 0
for _, e := range cfgEntries {
	v, src := pick(e.def, e.file, e.env)
