// =====================================================================
// W55 d13：串行聚合慢在哪 —— 多账户 × 多分类的 N+1
//
// 这一天在解决什么问题：首页/报表要「每账户、每分类各花多少」。最省事的写法是先查账户列表（1 次），
// 再对每账户、每分类各发一条 SUM —— 这就是 N+1：全串行排队，慢在「次数 × 每次固定往返成本」线性叠加
// （墙钟 = 调用数 × 单价）。修法是按账户开 goroutine 并行：账户内部仍逐分类串行、账户之间并发，于是
// 墙钟 ≈ 最慢的那一路，而不是所有调用之和。耗时不真计时、不随机：按固定单价（每调用 callUnitMs 毫秒）
// × 调用数算出，两次跑逐字节一致。金额一律 *_cents 整数；family_id 恒进每一条查询。并行后调用数不减、
// 只减墙钟；正确性另在 d14 逐桶对拍。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d13
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"sync"
)

const (
	famID      = "aaaaaaaa-0000-4000-8000-000000000001"
	callUnitMs = 4 // 模拟单价：一次「账户×分类」SUM 查询的固定往返成本（毫秒），不真计时
)

var cats = []string{"cat-food", "cat-travel", "cat-shop", "cat-house", "cat-learn", "cat-salary"}

type account struct {
	code  string
	name  string
	byCat map[string]int64 // 分类 → expense_cents（整数分）；只存真实出现过的分类格
}

var accounts = []account{
	mk("ACC-01", "现金钱包", "cat-food", 230000, "cat-shop", 120000),
	mk("ACC-02", "储蓄卡", "cat-food", 88000, "cat-travel", 318400, "cat-shop", 245000),
	mk("ACC-03", "信用卡", "cat-food", 50000, "cat-learn", 260000, "cat-travel", 120000),
	mk("ACC-04", "房贷账户", "cat-house", 800000),
	mk("ACC-05", "证券", "cat-travel", 45000, "cat-shop", 15000),
	mk("ACC-06", "公积金", "cat-house", 240000, "cat-learn", 90000),
	mk("ACC-07", "外币", "cat-travel", 210000, "cat-food", 9000, "cat-shop", 1500, "cat-house", 30000, "cat-learn", 22000, "cat-salary", 90000),
	mk("ACC-08", "家长代管", "cat-learn", 40000, "cat-shop", 5000),
	mk("ACC-09", "备用金", "cat-food", 60000, "cat-travel", 7000),
	mk("ACC-10", "生意往来", "cat-shop", 500000, "cat-house", 33000, "cat-food", 12000),
	mk("ACC-11", "礼金", "cat-salary", 100000),
	mk("ACC-12", "投资专户", "cat-travel", 26000, "cat-learn", 18000, "cat-shop", 4200, "cat-house", 9000, "cat-salary", 30000),
}

// mk：变参 (cat, cents, cat, cents ...) 造账户，金额全是整数分（不调 rand，两次跑一致）。
func mk(code, name string, kv ...any) account {
	a := account{code: code, name: name, byCat: map[string]int64{}}
	for i := 0; i < len(kv); i += 2 {
		cents, _ := kv[i+1].(int)              // 变参里的整型字面量装进 any 即为 int
		a.byCat[kv[i].(string)] = int64(cents) // 分类支出 *_cents
	}
	return a
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string {
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}
func codes() []string { // 稳定排序键：账户 code 字典序
	out := make([]string, len(accounts))
	for i, a := range accounts {
		out[i] = a.code
	}
	sort.Strings(out)
	return out
}
func catsOf(a account) []string { // 按分类字典序，保证串行/并行同一遍历序
	var out []string
	for _, c := range cats {
		if _, ok := a.byCat[c]; ok {
			out = append(out, c)
		}
	}
	return out
}
func findAcct(code string) account { // 一条「账户×分类」查询的取数入口（内存表模拟 finance_transaction）
	for _, a := range accounts {
		if a.code == code {
			return a
		}
	}
	return account{}
}

// ---- 串行版：先取账户列表（1 次），再逐账户逐分类各发一条 SUM ----
func serialAgg() map[string]int64 {
	totals := map[string]int64{}
	for _, code := range codes() {
		a := findAcct(code)
		var s int64
		for _, c := range catsOf(a) {
			s += a.byCat[c] // 1 条 SUM 查询的等价取数
		}
		totals[code] = s
	}
	return totals
}

// ---- 并行版：按账户开 goroutine；账户内部仍逐分类串行，账户之间并发；结果收集后按 code 排序 ----
func parallelAgg() map[string]int64 {
	type res struct {
		code string
		sum  int64
	}
	ch := make(chan res, len(accounts))
	var wg sync.WaitGroup
	for _, code := range codes() {
		wg.Add(1)
		go func(code string) { // code 作参数传入：闭包捕获循环变量会与后续迭代竞争
			defer wg.Done()
			a := findAcct(code)
			var s int64
			for _, c := range catsOf(a) {
				s += a.byCat[c] // 与串行同一份查询口径，只是并发跑
			}
			ch <- res{code, s}
		}(code)
	}
	wg.Wait()
	close(ch)
	totals := map[string]int64{}
	for r := range ch {
		totals[r.code] = r.sum // 收集完再按稳定键读，打印顺序与调度无关
	}
	return totals
}

// 调用数 = 1（列表）+ Σ 各账户分类格数；最慢一路 = 单账户最多格数（并行墙钟由它决定）。
func callStats() (calls, maxPath int, slowest string) {
	calls = 1
	for _, code := range codes() {
		k := len(catsOf(findAcct(code)))
		calls += k
		if k > maxPath {
			maxPath, slowest = k, code
		}
	}
	return
}

func main() {
	nAcct, nCat := len(accounts), len(cats)
	serialTotals := serialAgg()
	parTotals := parallelAgg()
	serialCalls, maxPath, slowest := callStats()
	parCalls := serialCalls // 并行与串行调用数完全相同：并行不减往返次数

	hdr(fmt.Sprintf("1. 场景：%d 账户 × %d 分类 = %d 格（family_id=%s），金额全 *_cents 整数", nAcct, nCat, nAcct*nCat, famID))
	fmt.Printf("  单次「账户×分类」SUM 的模拟单价 = %d ms（固定量，不真计时、不随机）；每账户只查它真实出现过的分类格。\n", callUnitMs)
	fmt.Println("  （ACC-04 房贷只有物业一格，ACC-07 外币六格全开 —— 分类数天然不同，才有「最慢一路」）")
	fmt.Printf("  %-8s %-12s %s\n", "code", "账户", "真实出现过的分类格数")
	for _, code := range codes() {
		fmt.Printf("  %-8s %-12s %d\n", code, findAcct(code).name, len(catsOf(findAcct(code))))
	}

	hdr("2. ❌ 串行版：N+1 —— 1 次列表 + Σ 分类查询，全排队")
	fmt.Printf("  循环体：for 账户 { for 该账户分类 { SUM(finance_transaction WHERE family_id 且 account 且 category) } }\n")
	fmt.Printf("  串行调用数 = %d（列表 1 + 分类 %d）；串行墙钟 = %d × %d = %d ms\n", serialCalls, serialCalls-1, serialCalls, callUnitMs, serialCalls*callUnitMs)
	fmt.Println("  把这一次串行走的查询逐条摊开（第 2 条起才是 N+1 的「N 条子查询」）：")
	fmt.Printf("  %-4s %-8s %-11s %-52s %s\n", "序", "账户", "分类", "SQL 形状（等价，非本条真跑库）", "累计排队(ms)")
	qi := 1
	fmt.Printf("  %-4d %-8s %-11s %-52s %d\n", 1, "（全部）", "—", "SELECT code FROM finance_account WHERE family_id=$1", callUnitMs)
	for _, code := range codes() {
		for _, c := range catsOf(findAcct(code)) {
			qi++
			fmt.Printf("  %-4d %-8s %-11s %-52s %d\n", qi, code, c,
				fmt.Sprintf("SELECT SUM(expense_cents) WHERE family_id=$1 AND account=%s AND category=%s", code, c), qi*callUnitMs)
		}
	}

	hdr("3. ✅ 并行版：账户之间并发，账户内部仍逐分类串行")
	fmt.Printf("  %d 个 goroutine 各领一个账户，跑完把自己那格结果发进 channel；主线程收集后按 code 排序（两次跑字节一致）。\n", nAcct)
	fmt.Printf("  并行调用数 = %d（与串行一模一样，并行不减往返次数）。\n", parCalls)
	fmt.Println("  每账户并行合计 + 它自己那几路串行占用的「并发窗口」（相对并行起点 0）：")
	fmt.Printf("  %-8s %-14s %-10s %s\n", "code", "并行合计(元)", "本路(ms)", "并发窗口")
	for _, code := range codes() {
		k := len(catsOf(findAcct(code)))
		fmt.Printf("  %-8s %-14s %-10d [0, %d) ms 与其它 %d 路同时跑\n", code, money(parTotals[code]), k*callUnitMs, k*callUnitMs, nAcct-1)
	}

	hdr("4. 两条路径逐账户对拍：合计 diff 全 0（并行没算重/漏算）")
	bad := 0
	fmt.Printf("  %-8s %-14s %-14s %-10s %s\n", "code", "串行合计(元)", "并行合计(元)", "diff(分)", "判定")
	for _, code := range codes() {
		d := parTotals[code] - serialTotals[code]
		mark := "✅"
		if d != 0 {
			mark, bad = "❌", bad+1
		}
		fmt.Printf("  %-8s %-14s %-14s %-10d %s\n", code, money(serialTotals[code]), money(parTotals[code]), d, mark)
	}
	fmt.Printf("  非 0 账户 %d/%d —— 并行与串行吃同一份查询口径，结果逐账户等；差只差在「墙钟」。\n", bad, nAcct)

	hdr(fmt.Sprintf("5. 耗时证明：并行墙钟 ≈ 最慢的一路，不是 %d 次调用之和", serialCalls))
	serialMs := serialCalls * callUnitMs
	parMs := (1 + maxPath) * callUnitMs // 列表 1 次（串行前置）+ 最慢账户那一趟；其余在这段里同时跑完
	ratio := float64(serialMs) / float64(parMs)
	fmt.Printf("  串行墙钟 %d ms（%d 次 × %d ms 全排队）\n", serialMs, serialCalls, callUnitMs)
	fmt.Printf("  最慢一路 = %s（%s）：%d 格分类 → %d ms；并行墙钟 = (列表1 + 最慢%d) × %d = %d ms\n",
		slowest, findAcct(slowest).name, maxPath, maxPath*callUnitMs, maxPath, callUnitMs, parMs)
	fmt.Printf("  其余 %d 个账户都在这 %d ms 里并发跑完（各自 ≤ 最慢一路）→ 墙钟由最慢一路决定。\n", nAcct-1, parMs)
	fmt.Printf("  比值 串行/并行 = %d/%d ≈ %.2f×（≈ 参与并行的账户数 %d）——「并行后总耗时 ≈ 最慢的一路」成立。\n", serialMs, parMs, ratio, nAcct)
	fmt.Printf("  但调用数仍是 %d（= 串行）：并行只把「排队」变「同时」，没把 %d 次分类往返合并成 1 条 GROUP BY。\n", parCalls, parCalls-1)

	hdr("6. 收口")
	fmt.Println("  · N+1 的「慢」是「次数 × 固定往返成本」的线性叠加；并行把线性叠加变最大值，是止血不是根治。")
	fmt.Printf("  · 根治是把「%d 条分类 SUM」合成 1 条 GROUP BY account, category（见报表桶口径）；今天先证明并行的墙钟收益与它「不减调用」的局限。\n", serialCalls-1)
	fmt.Printf("  · 金额全程 *_cents（分→元只在 money() 展示层发生）；family_id=%s 恒进每一条查询与日志。\n", famID)
	fmt.Println("\n=== W55 d13 到此结束 ===")
	fmt.Println("明天 d14：并行结果的正确性——并发写同一 map 会 fatal，得分片归并；并行与串行逐桶对拍 diff 必须全 0。")
}

