// =====================================================================
// W55 d13：串行聚合慢在哪 —— 多账户 × 多分类的 N+1
//
// 这一天在解决什么问题：首页/报表要「每账户、每分类各花多少」。最省事的写法是先查账户列表（1 次），
// 再对每账户、每分类各发一条 SUM —— 这就是 N+1：全串行排队，慢在「次数 × 每次固定往返成本」线性叠加
// （墙钟 = 调用数 × 单价）。修法是按账户开 goroutine 并行：账户内部仍逐分类串行、账户之间并发，于是
// 墙钟 ≈ 最慢的那一路，而不是所有调用之和。耗时不真计时、不随机：按固定单价（每调用 callUnitMs 毫秒）
// × 调用数算出，两次跑逐字节一致。金额一律 *_cents 整数；family_id 恒进每一条查询。并行后调用数不减、
// 只减墙钟；正确性另在 d14 逐桶对拍。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d13
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"sync"
)

const (
	famID      = "aaaaaaaa-0000-4000-8000-000000000001"
	callUnitMs = 4 // 模拟单价：一次「账户×分类」SUM 查询的固定往返成本（毫秒），不真计时
)

var cats = []string{"cat-food", "cat-travel", "cat-shop", "cat-house", "cat-learn", "cat-salary"}

type account struct {
	code  string
	name  string
	byCat map[string]int64 // 分类 → expense_cents（整数分）；只存真实出现过的分类格
}

var accounts = []account{
	mk("ACC-01", "现金钱包", "cat-food", 230000, "cat-shop", 120000),
	mk("ACC-02", "储蓄卡", "cat-food", 88000, "cat-travel", 318400, "cat-shop", 245000),
	mk("ACC-03", "信用卡", "cat-food", 50000, "cat-learn", 260000, "cat-travel", 120000),
	mk("ACC-04", "房贷账户", "cat-house", 800000),
	mk("ACC-05", "证券", "cat-travel", 45000, "cat-shop", 15000),
	mk("ACC-06", "公积金", "cat-house", 240000, "cat-learn", 90000),
	mk("ACC-07", "外币", "cat-travel", 210000, "cat-food", 9000, "cat-shop", 1500, "cat-house", 30000, "cat-learn", 22000, "cat-salary", 90000),
	mk("ACC-08", "家长代管", "cat-learn", 40000, "cat-shop", 5000),
	mk("ACC-09", "备用金", "cat-food", 60000, "cat-travel", 7000),
	mk("ACC-10", "生意往来", "cat-shop", 500000, "cat-house", 33000, "cat-food", 12000),
	mk("ACC-11", "礼金", "cat-salary", 100000),
	mk("ACC-12", "投资专户", "cat-travel", 26000, "cat-learn", 18000, "cat-shop", 4200, "cat-house", 9000, "cat-salary", 30000),
}

// mk：变参 (cat, cents, cat, cents ...) 造账户，金额全是整数分（不调 rand，两次跑一致）。
func mk(code, name string, kv ...any) account {
	a := account{code: code, name: name, byCat: map[string]int64{}}
	for i := 0; i < len(kv); i += 2 {
		cents, _ := kv[i+1].(int)              // 变参里的整型字面量装进 any 即为 int
		a.byCat[kv[i].(string)] = int64(cents) // 分类支出 *_cents
	}
	return a
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string {
	neg := ""
	if c < 0 {
		neg, c = "-", -c
	}
	return fmt.Sprintf("%s%d.%02d", neg, c/100, c%100)
}
func codes() []string { // 稳定排序键：账户 code 字典序
	out := make([]string, len(accounts))
	for i, a := range accounts {
		out[i] = a.code
	}
	sort.Strings(out)
	return out
}
func catsOf(a account) []string { // 按分类字典序，保证串行/并行同一遍历序
	var out []string
	for _, c := range cats {
		if _, ok := a.byCat[c]; ok {
			out = append(out, c)
		}
	}
	return out
}
func findAcct(code string) account { // 一条「账户×分类」查询的取数入口（内存表模拟 finance_transaction）
	for _, a := range accounts {
		if a.code == code {
			return a
		}
	}
	return account{}
}

// ---- 串行版：先取账户列表（1 次），再逐账户逐分类各发一条 SUM ----
func serialAgg() map[string]int64 {
	totals := map[string]int64{}
	for _, code := range codes() {
		a := findAcct(code)
		var s int64
		for _, c := range catsOf(a) {
			s += a.byCat[c] // 1 条 SUM 查询的等价取数
		}
		totals[code] = s
	}
	return totals
}

// ---- 并行版：按账户开 goroutine；账户内部仍逐分类串行，账户之间并发；结果收集后按 code 排序 ----
func parallelAgg() map[string]int64 {

	type res struct {
		code string
		sum  int64
	}
	ch := make(chan res, len(accounts))
	var wg sync.WaitGroup
	for _, code := range codes() {
		wg.Add(1)
		go func(code string) { // code 作参数传入：闭包捕获循环变量会与后续迭代竞争
			defer wg.Done()
			a := findAcct(code)
			var s int64
			for _, c := range catsOf(a) {
				s += a.byCat[c] // 与串行同一份查询口径，只是并发跑
			}
			ch <- res{code, s}
		}(code)
	}
	wg.Wait()
	close(ch)
	totals := map[string]int64{}
	for r := range ch {
		totals[r.code] = r.sum // 收集完再按稳定键读，打印顺序与调度无关
	}
	return totals
}

// 调用数 = 1（列表）+ Σ 各账户分类格数；最慢一路 = 单账户最多格数（并行墙钟由它决定）。
func callStats() (calls, maxPath int, slowest string) {
	calls = 1
	for _, code := range codes() {
		k := len(catsOf(findAcct(code)))
		calls += k
		if k > maxPath {
			maxPath, slowest = k, code
		}
	}
	return
}

