// =====================================================================
// W55 d14：并行聚合的正确性 —— 两条路径逐桶 diff 必须为 0
//
// 这一天在解决什么问题：d13 把聚合并行化只减了墙钟，没验「并行算的还是不是同一个数」。把每一路结果
// 直接累加进「同一张共享 map」会当场 fatal error: concurrent map writes —— 它不是 panic，recover
// 接不住，runtime 自己的 hashWriting 才是哨兵。正确路子是分片归并：每个 goroutine 只写自己私有那份
// 桶 map，算完再单线程按固定序合并。今天先用 d14fatal_test.go 真跑出那个 fatal，再上分片修复，最后把
// 并行结果与串行结果逐桶对拍：income/expense/net/count 四类整数分口径 diff 全 0 才算过。
//
// 桶契约逐字沿用 S11 W46：bucketStart/bucketEnd/bucketKey/parseKey/shiftKey + 唯一 trend 出桶现场；
// month 档、家庭时区 Asia/Shanghai、金额全 *_cents 整数；family_id 恒进每一条聚合与每一条日志。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d14
// 真崩复跑：   go test -count=1 -run TestConcurrentMapWrites ./lab/s13/d14
// =====================================================================
package main

import (
	"fmt"
	"strings"
	"sync"
	"time"
)

const famID = "aaaaaaaa-0000-4000-8000-000000000001"

// 家庭时区（PRD 3.4.8）：它决定桶边界，只从家庭设置取、不是入参；取不到即崩、不回落 UTC。
var famLoc = time.FixedZone("Asia/Shanghai", 8*3600)

func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }

// ---- W46 桶契约（month 档）：全项目唯一一处边界推导，空期照样占一格 ----
func bucketStart(t time.Time) time.Time { l := t.In(famLoc); return day0(l.Year(), int(l.Month()), 1) }
func bucketEnd(t time.Time) time.Time   { return bucketStart(t).AddDate(0, 1, 0) } // 排他右端 = 下一桶 start
func bucketKey(t time.Time) string      { return t.In(famLoc).Format("2006-01") }

// parseKey：canonical 往返 —— 反解出来再格式化必须逐字等于入参，否则拒（不猜窗、不回落默认档）。
func parseKey(s string) (time.Time, error) {
	t, e := time.ParseInLocation("2006-01", s, famLoc)
	if e != nil || bucketKey(t) != s {
		return time.Time{}, fmt.Errorf("period=%q 不是规范 month 桶键（形如 2026-07）", s)
	}
	return t, nil
}

// shiftKey：环比的唯一位移来源，back=true 上一桶 / false 下一桶。
func shiftKey(s string, back bool) (string, error) {
	st, e := parseKey(s)
	if e != nil {
		return "", e
	}
	if back {
		return bucketKey(st.Add(-time.Nanosecond)), nil
	}
	return bucketKey(bucketEnd(st)), nil
}

func enumKeys(from, to time.Time) []string {
	var out []string
	for cur := bucketStart(from); cur.Before(to); cur = bucketEnd(cur) {
		out = append(out, bucketKey(cur))
	}
	return out
}

// 内存表 finance_transaction：金额只有 *_cents 整数（income/expense 两列，等价 SQL FILTER）。
type txn struct {
	id, fam, kind string
	cents         int64
	at            time.Time
	soft          bool // true = deleted_at 非空：软删既不进桶也不进对拍
}
type bkt struct{ income, expense, net, count int64 }

var ledger = []txn{
	{"t-01", famID, "income", 860000, day0(2026, 5, 5).Add(9 * time.Hour), false},
	{"t-02", famID, "expense", 230000, day0(2026, 5, 11).Add(8 * time.Hour), false},
	{"t-03", famID, "expense", 128000, day0(2026, 5, 20), false},
	{"t-04", famID, "expense", 45000, day0(2026, 6, 3), false},
	{"t-05", famID, "income", 1200000, day0(2026, 6, 5).Add(9 * time.Hour), false},
	{"t-06", famID, "expense", 318400, day0(2026, 6, 10), true}, // 软删：不进任何桶
	{"t-07", famID, "expense", 500000, day0(2026, 7, 25).Add(3 * time.Hour), false},
	{"t-08", famID, "income", 90000, day0(2026, 7, 30).Add(59 * time.Minute), false},
	{"t-09", "fam-B", "expense", 999000, day0(2026, 7, 15), false}, // 跨家庭：被 family_id 挡掉
	{"t-10", famID, "expense", 120000, day0(2026, 8, 8), false},
	{"t-11", famID, "income", 460000, day0(2026, 8, 12), false},
	{"t-12", famID, "expense", 33000, day0(2026, 9, 1), false},
	{"t-13", famID, "expense", 260000, day0(2026, 9, 28), false},
	{"t-14", famID, "income", 300000, day0(2026, 10, 2), false},
	{"t-15", famID, "expense", 70000, day0(2026, 11, 8), false},
	{"t-16", famID, "income", 500000, day0(2026, 11, 5).Add(9 * time.Hour), false},
	{"t-17", famID, "expense", 15000, day0(2026, 12, 1), false},
	{"t-18", famID, "expense", 40000, day0(2026, 12, 20), false},
}

// 稠密枚举整年 → 12 个 month 桶（窗右端排他）；1~4 月一行为空，照样各占一格。
var winFrom, winTo = day0(2026, 1, 1), day0(2027, 1, 1)
var keys = enumKeys(winFrom, winTo)

func hdr(s string)         { fmt.Printf("\n===== %s =====\n", s) }
func okStr(ok bool) string { return map[bool]string{true: "✅", false: "❌"}[ok] }

// reason：去向由行上的两个标记现场决定（跨家庭优先于软删），文案不是写死在打印循环里的。

func reason(r txn) string {
	if r.fam != famID {
		return "❌ 跨家庭 → 404（family_id 不匹配，不是 403）"
	}
	if r.soft {
		return "❌ 软删 deleted_at 非空 → 不进桶、不进对拍"
	}
	return "✅ 进口径"
}

// signed：expense 记负、income 记正，全程整数分，不出现浮点。
func signed(r txn) int64 { return map[bool]int64{true: r.cents, false: -r.cents}[r.kind == "income"] }

// pick：等价 WHERE family_id = $1 AND deleted_at IS NULL AND occurred_at >= $2 AND occurred_at < $3
func pick() []txn {
	var out []txn
	for _, r := range ledger {
		if r.fam == famID && !r.soft && !r.at.Before(winFrom) && r.at.Before(winTo) {
			out = append(out, r)
		}
	}
	return out
}

// trend：全项目唯一的出桶 + 累加现场；写进调用方传进来的那张 map（传私有分片，所以能并行）。
func trend(rows []txn, into map[string]*bkt) {
	for _, r := range rows {
		b := into[bucketKey(r.at)]
		if r.kind == "income" {
			b.income += r.cents
		} else {
			b.expense += r.cents
		}
		b.net, b.count = b.income-b.expense, b.count+1
	}
}

// dense：先按稠密枚举把每格占好 → trend 与归并都没有 nil 判断，空期也带着自己的桶键出现。
func dense() map[string]*bkt {
	m := map[string]*bkt{}
	for _, k := range keys {
		m[k] = &bkt{}
	}
	return m
}
func serialAgg() map[string]*bkt { m := dense(); trend(pick(), m); return m }

// parallelAgg：4 个 goroutine 各写私有分片 map（零共享写）→ 算完单线程按分片序归并。
func parallelAgg() (map[string]*bkt, []map[string]*bkt) {
	rows := pick()
	const shards = 4
	parts := make([]map[string]*bkt, shards)

	var wg sync.WaitGroup
	for s := 0; s < shards; s++ {
		parts[s] = dense()
		wg.Add(1)
		go func(s int) { // s 作参数传入；各片只碰 parts[s]，彼此无交集 → 共享 map 的 fatal 无从发生
			defer wg.Done()
			var mine []txn
			for i, r := range rows {
				if i%shards == s {
					mine = append(mine, r)
				}
			}
			trend(mine, parts[s]) // 写私有分片而不是共享 map → 不 fatal
		}(s)
	}
	wg.Wait()
	merged := dense()
	for _, p := range parts { // 归并单线程、顺序固定（分片 0..3）→ 两次跑字节一致
		for k, b := range p {
			m := merged[k]
			m.income, m.expense, m.count = m.income+b.income, m.expense+b.expense, m.count+b.count
			m.net = m.income - m.expense
		}
	}
	return merged, parts
}

// 内嵌：go test 真崩抓到的 fatal 原文节选。归一化只动无信息量字节：0x… 地址→0xADDR、goroutine 编号→G#、
// 本地绝对路径→模块相对路径 lab/s13/d14/...、标准库绝对路径→$GOROOT/src/...；行结构、文件:行号、函数名、
// +0x… 偏移逐字未改（Go 的 fatal/panic 栈本来就是绝对 file:line，这里只换前缀，没动行号本身）。
const fatalReport = `fatal error: concurrent map writes

goroutine G# [running]:
homecube/server/lab/s13/d14.TestConcurrentMapWrites.func1(0xADDR)
	lab/s13/d14/d14fatal_test.go:20 +0x8a
created by homecube/server/lab/s13/d14.TestConcurrentMapWrites in goroutine G#
	lab/s13/d14/d14fatal_test.go:17 +0x8c

goroutine G# [semacquire]:
sync.runtime_Semacquire(0xADDR?)
	$GOROOT/src/runtime/sema.go:62 +0x25
sync.(*WaitGroup).Wait(0xADDR?)
	$GOROOT/src/sync/waitgroup.go:116 +0x48
homecube/server/lab/s13/d14.TestConcurrentMapWrites(0xADDR?)
	lab/s13/d14/d14fatal_test.go:24 +0x173`

func main() {
	serial := serialAgg()
	par, parts := parallelAgg()
	rows := pick()

	hdr(fmt.Sprintf("1. 场景：%d 行流水进口径（剔跨家庭、剔软删），month 桶稠密 %d 个（family_id=%s）", len(rows), len(keys), famID))
	fmt.Println("  桶契约（S11 W46 原样）：bucketStart=月初 / bucketEnd=排他右端(下一月初) / bucketKey=2006-01 / 家庭时区 Asia/Shanghai")
	fmt.Println("  金额全 *_cents 整数：income_cents 与 expense_cents 两列各自累加，net_cents = income - expense，一个浮点都不出现。")
	fmt.Printf("  全表 %d 行，逐行按 family_id、deleted_at IS NULL、窗 [%s, %s)（右端排他）三条件决定去留：\n", len(ledger), bucketKey(winFrom), bucketKey(winTo))
	fmt.Printf("  %-6s %-9s %-8s %-9s %-11s %s\n", "id", "family", "kind", "桶键", "净增量(分)", "过滤去向")
	for _, r := range ledger {
		fmt.Printf("  %-6s %-9s %-8s %-9s %-11d %s\n", r.id, r.fam, r.kind, bucketKey(r.at), signed(r), reason(r))
	}

	hdr("2. ❌ 先崩：把每路结果直接累加进「同一张共享 map」→ fatal error，不是 DATA RACE")
	fmt.Println("  崩法：8 个 goroutine 各跑 buckets[key] += 1（无锁写同一 map）。下面是 go test 真崩抓到的原文节选：")
	for _, l := range strings.Split(fatalReport, "\n") {
		fmt.Printf("    %s\n", l)
	}
	fmt.Println("  归一化只动这四类无信息量字节：0x… 地址→0xADDR、goroutine 编号→G#、本地绝对路径→lab/s13/d14/...、标准库绝对路径→$GOROOT/src/...；")
	fmt.Println("  行结构、文件:行号（:20 与 :17 与 :24）、函数名（TestConcurrentMapWrites.func1 / sync.(*WaitGroup).Wait / created by ...）、+0x… 偏移逐字未改。")
	fmt.Println("  · fatal 不是 panic（recover 拦不住、退出码 2）；-race 只是旁观者，runtime 的 hashWriting 才是哨兵。")
	fmt.Println("  · 想亲眼看它死：go test -count=1 -run TestConcurrentMapWrites ./lab/s13/d14（本程序 stdout 不含这行崩溃，是确定的）。")

	hdr("3. ✅ 修复：私有分片 map + 单线程归并（trend 是唯一出桶现场）")
	fmt.Printf("  并行版把 %d 行进 %d 个分片（行号 %% %d 轮转），每片一张私有 map，goroutine 只写自己那份 → 零共享写；归并按分片索引 0..%d 固定序合并，两次跑字节一致。\n", len(rows), len(parts), len(parts), len(parts)-1)
	fmt.Println("  各分片的「私有半成品」—— 归并前每片只数得出自己命中的桶，别的桶在这张 map 里还是空格子（= 分片的边界）：")
	fmt.Printf("  %-8s %-30s %-10s %s\n", "分片", "该片命中的桶键", "该片笔数", "该片Σnet(分)")
	for s := range parts {
		hit := []string{}
		cnt, net := int64(0), int64(0)
		for _, k := range keys { // 按稠密桶键序遍历，count>0 才算命中 → 输出确定
			if b := parts[s][k]; b.count > 0 {
				hit = append(hit, k)
				cnt += b.count
				net += b.net
			}
		}
		fmt.Printf("  %-8s %-30s %-10d %d\n", fmt.Sprintf("shard%d", s), strings.Join(hit, " "), cnt, net)
	}

	hdr("4. 逐桶对拍：并行归并 vs 串行，income/expense/net/count 四类整数分 diff 必须全 0")
	fmt.Printf("  %-8s %-9s %-9s %-10s %-5s %-9s %-9s %-10s %-5s %-19s %s\n", "桶键", "并in", "并exp", "并net", "并笔", "串in", "串exp", "串net", "串笔", "diff(in/exp/net/cnt)", "判定")
	var tIn, tExp, tNet, tCnt int64
	bad := 0
	for _, k := range keys {
		s, p := serial[k], par[k]
		d := [4]int64{p.income - s.income, p.expense - s.expense, p.net - s.net, p.count - s.count}
		netChk := p.income - p.expense - p.net // 每桶 net 恒 = income-expense → 整数口径没漂
		if d != [4]int64{} || netChk != 0 {
			bad++
		}
		tIn, tExp, tNet, tCnt = tIn+p.income, tExp+p.expense, tNet+p.net, tCnt+p.count
		fmt.Printf("  %-8s %-9d %-9d %-10d %-5d %-9d %-9d %-10d %-5d %-19s %s\n", k, p.income, p.expense, p.net, p.count,
			s.income, s.expense, s.net, s.count, fmt.Sprintf("%d/%d/%d/%d", d[0], d[1], d[2], d[3]), okStr(d == [4]int64{} && netChk == 0))
	}

	hdr("5. 三处求和自证：Σ并行桶 == Σ逐笔独立 == Σ分片直加（结论由程序现算，没写死）")

	var shIn, shExp, shNet, shCnt int64 // 分片侧直加，不经过 merged
	for _, p := range parts {
		for _, b := range p {
			shIn, shExp, shNet, shCnt = shIn+b.income, shExp+b.expense, shNet+b.net, shCnt+b.count
		}
	}
	var dIn, dExp, dCnt int64 // 独立算路：不切桶、逐笔相加
	for _, r := range rows {
		dCnt++
		if r.kind == "income" {
			dIn += r.cents
		} else {
			dExp += r.cents
		}
	}
	dNet := dIn - dExp
	sameRow := tIn == dIn && tExp == dExp && tNet == dNet && tCnt == dCnt
	fmt.Printf("  Σ并行桶    ：income %d · expense %d · net %d · 笔数 %d\n", tIn, tExp, tNet, tCnt)
	fmt.Printf("  Σ逐笔独立  ：income %d · expense %d · net %d · 笔数 %d\n", dIn, dExp, dNet, dCnt)
	fmt.Printf("  Σ分片直加  ：income %d · expense %d · net %d · 笔数 %d（与 Σ并行桶 一致 = %s）\n", shIn, shExp, shNet, shCnt, okStr(shIn == tIn && shExp == tExp && shNet == tNet && shCnt == tCnt))
	fmt.Printf("  逐桶四类 diff 非 0 的桶 %d/%d %s；桶和==逐笔和 %s —— 三条独立算路同点，才敢判并行没算重/漏算\n",
		bad, len(keys), okStr(bad == 0), map[bool]string{true: "成立", false: "不成立"}[sameRow])

	hdr("6. 桶契约回归：parseKey canonical 往返 + shiftKey 相邻（W46 沿用，环比全靠它）")
	fmt.Printf("  %-8s %-10s %-10s %-22s %s\n", "period", "prev", "next", "prev→next / next→prev", "判定")
	adj := 0
	for _, k := range keys {
		pv, _ := shiftKey(k, true)
		nx, _ := shiftKey(k, false)
		pn, _ := shiftKey(pv, false)
		np, _ := shiftKey(nx, true)
		ok := pn == k && np == k
		if ok {
			adj++
		}
		fmt.Printf("  %-8s %-10s %-10s %-22s %s\n", k, pv, nx, pn+"/"+np, okStr(ok))
	}
	badKeys := []string{"2026-9", "202609", "2026-13", "2026-01-31", "", "2026-07-01", "2026-00", "2026/07"}
	rej := 0
	for _, b := range badKeys {
		if _, e := parseKey(b); e != nil {
			rej++
		}
	}
	fmt.Printf("  shiftKey 相邻自反 %d/%d 全过；非法桶键 %d/%d 全被 parseKey 拒（无一条回落默认档或当前期）。\n", adj, len(keys), rej, len(badKeys))

	hdr("7. 收口")
	fmt.Printf("  · 并行聚合的正确性 = 「分片零共享写 + 固定序归并 + 逐桶四类 diff 全 0」三件一起成立，缺一都是假绿（本轮非 0 桶 %d/%d）。\n", bad, len(keys))
	fmt.Println("  · 结论全部现算：非 0 桶数、Σ桶 vs Σ逐笔 vs Σ分片、shiftKey 相邻数 —— 换一批 ledger 结论跟着变，没有一条写死。")
	fmt.Printf("  · 金额全程 *_cents；family_id=%s 恒进每一条聚合与日志；跨家庭那行按 404 语义挡在门外（不是 403）。\n", famID)
	fmt.Println("  · 今天全程内存模拟、无真库无网络：ledger 是 finance_transaction 的模拟行，桶/diff/求和是聚合口径推导；")
	fmt.Println("    真实 SQL 形态见 d13 的逐查询轨迹与 S11 d33 的 DryRun 语句，此处不重复落库。")
	fmt.Println("\n=== W55 d14 到此结束 ===")
	fmt.Println("明天 d15：并行是跑起来了，但还得能在超时/取消时停下来 —— context 的取消信号怎么传到下游，以及「取消后副作用已发生」的反例。")
}

code.content:
// =====================================================================
// W55 d15：context 超时与取消怎么传下去
//
// 这一天在解决什么问题：d13/d14 把聚合并行化了，但并行起来的那几路「什么时候该停」没人管——
// 上游超时、用户取消、请求被丢弃时，取消信号要顺着 context 树传到每一个下游 goroutine。
// 三种时序各跑一遍：① 父 ctx 超时（下游收到 Done()，Err()=DeadlineExceeded）；② 主动 cancel()
// （父与两个派生子一并收到 Canceled）；③ 子 ctx 派生（cancel 只沿树单向往下传、不回流）。
// 两个反例当场数出来：④ 下游不查 ctx.Err() —— ctx 已取消、聚合调用计数照涨（白算）；
// ⑤ 超时后结果被丢弃，但「先写内存表再查 ctx」的那版副作用已经落了行（丢结果丢不掉副作用）。
// 确定性：延迟全是钉死的毫秒常数（模型表值，不是测出来的），结论只依赖「表值 vs 预算」的大小
// 关系，真实计时器只用来兑现这个关系，stdout 不打印任何测出来的耗时；计数一律在 wg.Wait 后收口
// 再读 → 两次跑逐字节一致。金额 *_cents 整数；family_id 恒进每条聚合口径（沿用 d13/d14）。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d15
// =====================================================================
package main

import (
	"context"
	"fmt"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

const famID = "aaaaaaaa-0000-4000-8000-000000000001"

var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---- 模拟下游聚合：一路「账户×分类」的合计。两版行为：
//
//	runAgg    —— 完全不查 ctx：只要被调度就自增 aggCalls 并跑完（第 4 节「白算」反例的主角）。
//	runAggCtx —— 每格分类先查 ctx.Err()：取消后剩余格子不再执行、不再计数。
var (
	aggCalls int64 // 聚合调用计数（atomic：wg.Wait 之后读，终值确定）
	sideRows int64 // 内存表 bucket_cache 被「写副作用」增的行数
)

// 一路账户的固定分格数据（整数分）：3 个分类格 → runAggCtx 跑满时这一路计 3 次。
var acctCells = map[string]int64{"cat-food": 230000, "cat-shop": 120000, "cat-travel": 318400}

func sortedKeys(m map[string]int64) []string {
	var out []string
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func runAgg(lat time.Duration) int64 {
	time.Sleep(lat) // 固定模拟延迟（表值，不是测量值）
	return atomic.AddInt64(&aggCalls, 1)
}

func runAggCtx(ctx context.Context, accounts map[string]int64, perCell time.Duration) (map[string]int64, error) {
	out := map[string]int64{}
	for _, c := range sortedKeys(accounts) { // 分类字典序：遍历与调度无关
		if err := ctx.Err(); err != nil {
			return nil, err // 已取消：这一格与之后的格子都不跑、不计数
		}
		time.Sleep(perCell)
		atomic.AddInt64(&aggCalls, 1)
		out[c] = accounts[c] // WHERE family_id = $1 AND account/category 命中格（*_cents）
	}
	return out, nil
}

// runAggBadSide：反例版——每格「先写内存表一行、再查 ctx」。取消只拦得住返回值，拦不住已落的行。
func runAggBadSide(ctx context.Context, accounts map[string]int64, perCell time.Duration) (map[string]int64, error) {
	out := map[string]int64{}
	for _, c := range sortedKeys(accounts) {
		time.Sleep(perCell)
		atomic.AddInt64(&aggCalls, 1)
		atomic.AddInt64(&sideRows, 1) // 副作用先发生
		if err := ctx.Err(); err != nil {
			return nil, err // 后查 ctx：这一格结果被丢弃，但那一行已经留在表里
		}
		out[c] = accounts[c]
	}
	return out, nil
}

// runAggGoodSide：修复版——每格「先查 ctx、再写」。取消那格一行都不写。
func runAggGoodSide(ctx context.Context, accounts map[string]int64, perCell time.Duration) (map[string]int64, error) {
	out := map[string]int64{}
	for _, c := range sortedKeys(accounts) {
		time.Sleep(perCell)
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		atomic.AddInt64(&sideRows, 1)
		out[c] = accounts[c]
	}
	return out, nil
}

type stopRec struct {
	name string
	err  error
}

func main() {
	hdr(fmt.Sprintf("1. 场景：并行聚合的几路下游（family_id=%s），今天只管「超时/取消怎么传下去、什么时候停」", famID))
	fmt.Println("  · d13 解决「慢」、d14 解决「对」；今天解决「该停就停」：取消信号从哪来、怎么顺着 ctx 树传到底。")
	fmt.Println("  · 三种时序（父超时 / 主动 cancel / 子 ctx 派生）+ 两个反例（不查 ctx 白算 / 超时后副作用已发生）+ errgroup 联动。")
	fmt.Println("  · 延迟全是钉死的毫秒常数，结论只依赖「表值 vs 预算」的大小关系；程序不打印任何测量耗时 → 两次跑字节一致。")

	// ---- 2. 父 ctx 超时 ----
	hdr("2. 时序①：父 ctx 超时 —— 下游被 Done() 唤醒，Err() = DeadlineExceeded")
	downLat := 500 * time.Millisecond // 下游自己的「本会耗时」（钉死表值）：它排在预算后面，永远等不到自己跑完
	pctx, pcancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer pcancel()
	var dErr error
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		select {
		case <-time.After(downLat):
			dErr = nil // 上游不给预算时它 500ms 后才回
		case <-pctx.Done():
			dErr = pctx.Err() // 父 50ms 到期先亮 → 下游当场被唤醒
		}
	}()
	wg.Wait()
	fmt.Printf("  上游预算 50ms < 下游本会耗时 %v → 走的是 Done 分支：err = %v（== DeadlineExceeded %s）\n",
		downLat, dErr, mark[dErr == context.DeadlineExceeded])
	fmt.Println("  传法：超时不是「到点 kill」，是 close(ctx.Done()) 广播 + Err() 给出原因；持有同一 ctx 的下游同时被唤醒。")

	// ---- 3. 主动取消 + 子 ctx 派生 ----
	hdr("3. 时序②③：主动 cancel() 与子 ctx 派生 —— cancel 沿树单向往下传，不回流")
	parent, pcancel2 := context.WithCancel(context.Background())
	defer pcancel2()
	c1, cc1 := context.WithTimeout(parent, 20*time.Millisecond) // 子预算 20ms
	defer cc1()
	c2, cc2 := context.WithTimeout(parent, 500*time.Millisecond) // 子预算比谁都长
	defer cc2()
	children := make([]stopRec, 2)
	var cwg sync.WaitGroup
	cwg.Add(2)
	go func() { defer cwg.Done(); <-c1.Done(); children[0] = stopRec{"子 ctx(20ms)", c1.Err()} }()
	go func() { defer cwg.Done(); <-c2.Done(); children[1] = stopRec{"子 ctx(500ms)", c2.Err()} }()
	pcancel2() // 主线程立刻取消父：两个子都应被唤醒，收到的原因都是 Canceled
	cwg.Wait()
	fmt.Println("  父 ctx 被主动 cancel()；两个子都从 parent 派生（子预算各 20ms / 500ms，都比「父此刻被取消」晚不到）：")
	fmt.Printf("  %-14s %-24s %s\n", "子 ctx", "收到的 Err()", "判定")
	for _, ch := range children {
		fmt.Printf("  %-14s %-24s %s\n", ch.name, ch.err, mark[ch.err == context.Canceled])
	}
	fmt.Println("  · 父被取消 → 所有派生子一并取消（树形传播、单向往下）；反过来子超时不影响父 —— 预算花在哪层就派生在哪层。")
	fmt.Println("  · 派生规则：WithTimeout(parent, x) 的实际到期 = min(父剩余, x)。上面两路都收到 Canceled，正因为父先动了。")

	// ---- 4. 反例：下游不查 ctx.Err() 就白算 ----
	hdr("4. 反例①：下游不查 ctx.Err() —— 「已取消（超时）但仍执行了 4 次聚合」的调用计数当场算给你看")
	before := atomic.LoadInt64(&aggCalls)
	cctx, ccancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer ccancel()
	var awg sync.WaitGroup
	postExpired := make([]bool, 4) // 每路跑完时「回头一看」：此刻 ctx 是否早已过期（只观测，不控制）
	for i := 0; i < 4; i++ {
		i := i
		awg.Add(1)
		go func() {
			defer awg.Done()
			if i == 3 {
				time.Sleep(25 * time.Millisecond) // 第 4 路在预算过期（20ms）之后才起跑
			}
			runAgg(5 * time.Millisecond) // 不查 ctx 的下游：照样跑完、照样计数
			postExpired[i] = cctx.Err() != nil
		}()
	}
	awg.Wait()
	naive := atomic.LoadInt64(&aggCalls) - before
	lateRuns := 0
	for _, e := range postExpired {
		if e {
			lateRuns++
		}
	}
	// 守规矩版：每格先查 ctx.Err()。预算 7ms、每格 5ms → 第 3 格起跑前（t≈10ms>7ms）被拦。
	cctx2, ccancel2 := context.WithTimeout(context.Background(), 7*time.Millisecond)
	defer ccancel2()
	before2 := atomic.LoadInt64(&aggCalls)
	res, err := runAggCtx(cctx2, acctCells, 5*time.Millisecond)
	checks := atomic.LoadInt64(&aggCalls) - before2
	fmt.Printf("  ❌ 不查 ctx 版：ctx 已在 20ms 超时，4 路下游全部执行 → 调用计数 = %d/4 %s；其中第 4 路是超时之后起跑、白算（回头观测：跑完时 ctx 已过期的路数 = %d）\n",
		naive, mark[naive == 4], lateRuns)
	fmt.Printf("  ✅ 每格查 ctx.Err() 版：预算 7ms、每格 5ms → 只执行了 %d 格就停，err = %v，结果 = %v（丢弃并早退 %s）\n",
		checks, err, res, mark[err == context.DeadlineExceeded && checks == 2])
	fmt.Println("  · 两个计数都由这段代码 wg.Wait 后现场算出：「不查」与「每格查」的差 = 白算掉的成本。")
	fmt.Println("  · 取消是协作式的：runtime 不强杀 goroutine，查了才算停 —— 所以每步循环、每次下游调用前都要查 ctx.Err()。")

	// ---- 5. 反例：超时后结果被丢弃，但副作用已发生 ----
	hdr("5. 反例②：超时后结果被丢弃 —— 但「先写内存表」的副作用已经落了行")
	rowsBefore := atomic.LoadInt64(&sideRows)
	sctx, scancel := context.WithTimeout(context.Background(), 7*time.Millisecond)
	defer scancel()
	sres, serr := runAggBadSide(sctx, acctCells, 5*time.Millisecond) // 第 1 格 t≈5ms 写完 ctx 还活着；第 2 格 t≈10ms 先写后查，被丢弃
	deltaRows := atomic.LoadInt64(&sideRows) - rowsBefore
	fmt.Printf("  反例下游每格「先写 bucket_cache 一行、再查 ctx」：预算 7ms、每格 5ms → 第 2 格写完才看见超时：\n")
	fmt.Printf("  返回值：err = %v、结果 map = %v（被丢弃 %s）；可内存表副作用当场涨了 %d 行\n",
		serr, sres, mark[serr != nil && sres == nil], deltaRows)
	fmt.Println("  · 被丢弃的只是返回值，不是副作用 —— 行还留在表里。「查询已提交但响应作废」只能靠幂等键事后对账（d20 见）。")
	fixBefore := atomic.LoadInt64(&sideRows)
	fctx, fcancel := context.WithTimeout(context.Background(), 7*time.Millisecond)
	defer fcancel()
	fres, ferr := runAggGoodSide(fctx, acctCells, 5*time.Millisecond) // 同预算：第 2 格跑完后先查——查到就停，这格一行不写
	deltaFix := atomic.LoadInt64(&sideRows) - fixBefore
	fmt.Printf("  ✅ 修复版「先查后写」：同一预算 7ms → err = %v、结果丢弃（%s）、副作用增量 = %d（预算内真跑完的第 1 格落 1 行，被取消那格 0 行）\n",
		ferr, mark[ferr != nil && fres == nil], deltaFix)
	fmt.Println("  · 口径：ctx 到期时正在跑的那一步要么已提交、要么没提交，没有中间态 —— 所以写操作要能按幂等键重放对账。")

	// ---- 6. errgroup 里取消怎么传：一个失败，其余被派生 ctx 取消 ----
	hdr("6. 组合场景：errgroup.WithContext 的形状 —— 一路超预算返回 error，其余路被派生 ctx 掐停")
	paths := []struct {
		name    string
		perCell time.Duration
	}{
		{"ACC-01 现金钱包", 5 * time.Millisecond},
		{"ACC-02 储蓄卡", 5 * time.Millisecond},
		{"ACC-03 信用卡", 40 * time.Millisecond}, // 单格就超预算的一路
		{"ACC-04 房贷账户", 5 * time.Millisecond},
	}
	// 4 路共享同一个 30ms 预算（等价于 errgroup 组内派生的 gctx 到期）；每格先查 ctx 的守规矩版。
	gbudget := 30 * time.Millisecond
	tctx, tcancel := context.WithTimeout(context.Background(), gbudget)
	defer tcancel()
	var gwg sync.WaitGroup
	stopped := make([]bool, len(paths))
	for i, p := range paths {
		i, p := i, p
		gwg.Add(1)
		go func() {
			defer gwg.Done()
			_, e := runAggCtx(tctx, acctCells, p.perCell)
			stopped[i] = e != nil // 被预算掐停的路（返回了 ctx 错误）
		}()
	}
	gwg.Wait()
	nStop := 0
	for _, s := range stopped {
		if s {
			nStop++
		}
	}
	fmt.Printf("  预算 %v：3 路每格 5ms（3 格 15ms 内跑完）→ 完整返回；ACC-03 每格 40ms，单格就超预算 → 在下一格起跑前被掐停。\n", gbudget)
	fmt.Printf("  现场掐停的路数 = %d/%d（判定 = 该路从 runAggCtx 拿到了 ctx 错误）；其余 %d 路完整返回。\n",
		nStop, len(paths), len(paths)-nStop)
	fmt.Println("  · errgroup.WithContext 的语义就一句：任一路先返回 error → 组内派生 ctx 立即 cancel() → 其余路从 Done 收到信号早退。")
	fmt.Println("  · 传下去的还是同一机制（Done 广播 + Err 定因），差别只在「取消的触发者」从超时时钟换成了同伴的失败。")

	// ---- 7. 行为表 ----
	hdr("7. 行为表：三种时序 × 下游收到什么（中间列全是现场跑出来的变量，不是手抄字符串）")
	type row struct {
		when  string
		got   error
		claim error
	}
	rows := []row{
		{"父 ctx 到期（WithTimeout 到点）", dErr, context.DeadlineExceeded},
		{"主动 cancel()（父与两个派生子）", children[0].err, context.Canceled},
		{"子 ctx 预算先于返回到期（第 5 节）", serr, context.DeadlineExceeded},
	}
	fmt.Printf("  %-34s %-26s %s\n", "时序", "下游 Err()", "判定")
	for _, r := range rows {
		fmt.Printf("  %-34s %-26s %s\n", r.when, r.got, mark[r.got == r.claim])
	}

	// ---- 8. 收口 ----
	hdr("8. 收口")
	fmt.Printf("  · 传播形状一棵树：WithCancel/WithTimeout/WithValue 都从父派生；cancel 只往下传，父到期与子到期互不越层。\n")
	fmt.Printf("  · 协作式停止：查了 ctx 才停 —— 第 4 节不查版 %d/4 全白算、查版只跑 %d 格，计数都由代码当场数出。\n", naive, checks)
	fmt.Printf("  · 超时丢结果 ≠ 丢副作用：第 5 节反例当场多落 %d 行缓存，修复版增量归位（被取消那格 0 行）。\n", deltaRows)
	fmt.Printf("  · 一个失败要能只停「该停的」：第 6 节 %d 路被掐停、其余完整返回 —— 明天 d16 把「一个慢不能整页坏」做成预算表。\n", nStop)
	fmt.Println("\n=== W55 d15 到此结束 ===")
	fmt.Println("明天 d16：超时预算与部分失败 —— errgroup + 每区独立 deadline，单区超时只标 degraded，重试只给幂等读。")
}

