code.content:
// =====================================================================
// W55 d16：超时预算与部分失败 —— 一个慢不能整页坏
//
// 这一天在解决什么问题：S12 d21 把首页四区（账目摘要 / 待办提醒 / 通知未读 / 最近动态）用 errgroup
// 并行取，并定死「单区失败只标那一格 degraded、整页恒 200」。今天给这套形状补上「时间维度」：
// 每个区独立 context.WithTimeout 预算（100ms），慢区（通知未读，固定模拟延迟 300ms）到点只掐自己；
// ❌ 对照版整页共享一条预算且 error 出组 —— 一个区超时把 3 个本可完成的区拖成整页 500。
// 重试预算 maxTries=3 只给幂等读：瞬断第二次就成功、结构性慢重试三次仍超时（白等 3× 预算，数给你看）；
// 写操作不许自动重试：同一 client_request_id 重发 3 次唯一索引去重只剩 1 行，
// 每次重试重新生成 crid 则落 3 行 —— 行数差就是崩法证据，全部现算。
// 确定性：延迟是钉死毫秒常数，结论只依赖「表值 vs 预算」关系；结果按下标收口、打印前排序，两次跑字节一致。
// 金额 *_cents 整数；family_id 恒进每条查询且只从会话取；业务面不自起计时器（待办只读到期中心注册行，
// 幂等键 (source_system, source_id, kind)）。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d16
// =====================================================================
package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"golang.org/x/sync/errgroup"
)

const (
	famA, famB, uDad = "fam-A", "fam-B", "u-dad"
	month            = "2026-10"
	budgetMs         = 100 // 每区独立超时预算（钉死常数）
	maxTries         = 3   // 重试预算：只给幂等读
	handlerLatMs     = 15  // 装配耗时（模型常数）
)

var fixedNow = time.Date(2026, 10, 19, 9, 0, 0, 0, time.FixedZone("Asia/Shanghai", 8*3600))
var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string {
	a := c
	if a < 0 {
		a = -a
	}
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], a/100, a%100)
}
func dayOf(y, m, d, hh, mm int) time.Time {
	return time.Date(y, time.Month(m), d, hh, mm, 0, 0, fixedNow.Location())
}

// ---- 内存表（S12 d21 同口径的模拟行；本机无 PostgreSQL，全部在内存里数） ----
type noteRow struct {
	ID                  int64
	FamilyID, Recipient string
	Kind                string
	AmountCents         int64
	ReadAt, DeletedAt   time.Time
}

var notes = []noteRow{
	{1, famA, uDad, "budget_alert", 2518000, time.Time{}, time.Time{}},
	{2, famA, uDad, "reminder", 180000, time.Time{}, time.Time{}},
	{3, famA, uDad, "system", 0, time.Time{}, time.Time{}},
	{4, famA, uDad, "system", 0, fixedNow.Add(-12 * time.Hour), time.Time{}}, // 已读
	{5, famA, uDad, "system", 0, time.Time{}, fixedNow},                      // 软删（撤回）
	{6, famA, "u-kid", "reminder", 30000, time.Time{}, time.Time{}},          // 收件人不是自己
	{7, famB, "u-mom", "system", 0, time.Time{}, time.Time{}},                // 别家 → 不可见
}

func alive(n noteRow) bool { return n.ReadAt.IsZero() && n.DeletedAt.IsZero() }

// unread：全项目唯一的未读数口径（read_at IS NULL 且 deleted_at IS NULL 且 family_id 且收件人是自己）。
func unread(fam, user string) int {
	c := 0
	for _, n := range notes {
		if n.FamilyID == fam && n.Recipient == user && alive(n) {
			c++
		}
	}
	return c
}

type txnRow struct {
	ID, FamilyID, Kind    string
	AmountCents           int64
	OccurredAt, DeletedAt time.Time
}

var txns = []txnRow{
	{"t-01", famA, "expense", 128000, dayOf(2026, 10, 3, 20, 15), time.Time{}},
	{"t-02", famA, "expense", 86600, dayOf(2026, 10, 9, 12, 30), time.Time{}},
	{"t-03", famA, "income", 30000, dayOf(2026, 10, 11, 9, 0), time.Time{}},
	{"t-04", famA, "expense", 15000, dayOf(2026, 10, 15, 18, 40), time.Time{}},
	{"t-05", famA, "expense", 420000, dayOf(2026, 9, 30, 20, 15), time.Time{}}, // 上月：不进本月窗
	{"t-06", famA, "expense", 9900, dayOf(2026, 10, 17, 8, 5), fixedNow},       // 软删不进
	{"t-07", famB, "expense", 77000, dayOf(2026, 10, 12, 10, 0), time.Time{}},  // 别家
}

// monthNetCents：本月净额（整数分）与笔数 —— 与 S12 d21 同一条筛选。
func monthNetCents(fam string) (int64, int) {
	var net int64
	var n int
	for _, t := range txns {
		if t.FamilyID != fam || !t.DeletedAt.IsZero() ||
			t.OccurredAt.Before(dayOf(2026, 10, 1, 0, 0)) || !t.OccurredAt.Before(dayOf(2026, 11, 1, 0, 0)) {
			continue
		}
		n++
		if t.Kind == "expense" {
			net -= t.AmountCents
		} else {
			net += t.AmountCents
		}
	}
	return net, n
}

type actRow struct {
	ID, FamilyID, Text string
	AmountCents        int64
	CreatedAt          time.Time
}

var acts = []actRow{
	{"AF-01", famA, "小豆 交兴趣班", 210000, dayOf(2026, 10, 18, 16, 20)},
	{"AF-02", famA, "爸爸 记了一笔", 128000, dayOf(2026, 10, 19, 8, 55)},
}

// 到期中心注册行：幂等键 (source_system, source_id, kind)；业务面不自起计时器。
type dueRow struct {
	SourceSystem, SourceID, Kind, FamilyID string
	DueAt                                  time.Time
}

var dues = []dueRow{{"recurring_rule", "monthly-2026-10", "reminder", famA, dayOf(2026, 10, 26, 9, 0)}}

// ---- 四区：区名 + 来源 + 固定模拟延迟（ms，表值常数，不是测量值） ----
type regionDef struct {
	name, src string
	latMs     int
}

var regions = []regionDef{
	{"账目摘要", "finance_transaction 月窗聚合（family_id 恒在）", 25},
	{"待办提醒", "calendar_due 注册行（只读到期中心）", 45},
	{"通知未读", "homeos_notification count（唯一来源 unread）", 300}, // 今天那个「慢区」
	{"最近动态", "homeos_activity 游标分页首屏", 35},
}

// fetchValue：每区当场算出的展示值（口径与 S12 d21 逐字同形）。
func fetchValue(name string) (string, error) {
	switch name {
	case "账目摘要":
		net, n := monthNetCents(famA)
		return fmt.Sprintf("%s 元 · %d 笔", money(net), n), nil
	case "待办提醒":
		c := 0
		for _, d := range dues {
			if d.FamilyID == famA {
				c++
			}
		}
		return fmt.Sprintf("%d 条待办（到期中心注册）", c), nil
	case "通知未读":
		return fmt.Sprintf("%d 条未读", unread(famA, uDad)), nil
	case "最近动态":
		if len(acts) == 0 {
			return "暂无动态", nil
		}
		a := acts[len(acts)-1]
		return fmt.Sprintf("%s %s 元", a.Text, money(a.AmountCents)), nil
	}
	return "", errors.New("未知区: " + name)
}

// downstream：模拟该区下游 —— latMs 后带值返回；在此之前 ctx 先到期就带 ctx.Err() 返回。
// 结果由「latMs vs 预算」的钉死关系决定（25/45/35 < 100 < 300），select 两条分支不会打平 → 确定。
func downstream(ctx context.Context, latMs int, name string) (string, error) {
	select {
	case <-ctx.Done():
		return "", ctx.Err()
	case <-time.After(time.Duration(latMs) * time.Millisecond):
		return fetchValue(name)
	}
}

type secResult struct {
	name string
	val  string
	err  error
}

func (s secResult) ok() bool { return s.err == nil }

func namesOf(secs []secResult, wantOK bool) []string {
	var x []string
	for _, s := range secs {
		if s.ok() == wantOK {
			x = append(x, s.name)
		}
	}
	sort.Strings(x)
	return x
}

// homeSummaryBudgeted：✅ 正解 —— errgroup + 每区独立预算；单区错误只写进那一格，恒不返回组错误。
func homeSummaryBudgeted() []secResult {
	out := make([]secResult, len(regions))
	var g errgroup.Group
	for i, r := range regions {
		i, r := i, r
		g.Go(func() error {
			ctx, cancel := context.WithTimeout(context.Background(), budgetMs*time.Millisecond)
			defer cancel()
			v, err := downstream(ctx, r.latMs, r.name)
			out[i] = secResult{r.name, v, err} // 错误进格子，不进组 → 其余区不被牵连
			return nil
		})
	}
	_ = g.Wait()
	return out
}

// homeSummaryShared：❌ 对照 —— 整页共享一条预算，且区错误直接出组（errgroup 会 cancel gctx）。
func homeSummaryShared() ([]secResult, error) {
	ctx, cancel := context.WithTimeout(context.Background(), budgetMs*time.Millisecond)
	defer cancel()
	g, gctx := errgroup.WithContext(ctx)
	out := make([]secResult, len(regions))
	for i, r := range regions {
		i, r := i, r
		g.Go(func() error {
			v, err := downstream(gctx, r.latMs, r.name)
			out[i] = secResult{r.name, v, err}
			return err // error 出组：一个区超时 = 整页失败
		})
	}
	return out, g.Wait()
}

// retryRead：幂等读的重试循环。transientFirst=true 模拟「第一次瞬断（立即报错），之后恢复」。
type attemptLog struct {
	try     int
	outcome string
}

func retryRead(r regionDef, transientFirst bool) (string, []attemptLog, bool) {
	var logs []attemptLog
	for t := 1; t <= maxTries; t++ {
		ctx, cancel := context.WithTimeout(context.Background(), budgetMs*time.Millisecond)
		var v string
		var err error
		if transientFirst && t == 1 {
			err = errors.New("connection reset by peer（模拟瞬断，立即返回不占预算）")
		} else {
			v, err = downstream(ctx, r.latMs, r.name)
		}
		cancel()
		if err == nil {
			logs = append(logs, attemptLog{t, "成功"})
			return v, logs, true
		}
		logs = append(logs, attemptLog{t, err.Error()})
	}
	return "", logs, false
}

// ---- 写侧崩法：client_request_id 决定唯一索引去重与否 ----
func cridOf(fam, sourceID, kind string) string {
	h := sha256.Sum256([]byte(fam + "|" + sourceID + "|" + kind))
	return hex.EncodeToString(h[:])[:16] // 展示用截 16 hex；真实为完整摘要/UUID
}

var delivered []string // notification_delivery 表（只存 crid；存在即拒绝重复写入 = 唯一索引）

func tryDeliver(id string) bool {
	for _, c := range delivered {
		if c == id {
			return false
		}
	}
	delivered = append(delivered, id)
	return true
}

func main() {
	hdr(fmt.Sprintf("1. 现场：会话 fam=%s user=%s，首屏四区 + 每区独立预算 %dms（family_id 只从会话取）", famA, uDad, budgetMs))
	fmt.Printf("  路由 1 个：GET /api/home/summary?family_id=%s&month=%s；四区是视图分法，取数并行在一个请求里（S12 d21 形状）。\n", famA, month)
	fmt.Printf("  %-8s %-44s %-10s %-8s %s\n", "区", "来源", "模拟延迟", "预算", "超预算?（lat > 预算，表值现算）")
	slowOnes := []string{}
	for _, r := range regions {
		over := r.latMs > budgetMs
		if over {
			slowOnes = append(slowOnes, r.name)
		}
		fmt.Printf("  %-8s %-44s %-10d %-8d %s\n", r.name, r.src, r.latMs, budgetMs, map[bool]string{true: "❌ 是", false: "✅ 否"}[over])
	}
	fmt.Printf("  钉死的延迟表意味着：慢区恒为 %v —— 结论只依赖表值关系，不依赖真测耗时。\n", slowOnes)

	hdr("2. ✅ 正解：每区独立预算，单区超时只标那一格 degraded，整页恒 200")
	secs := homeSummaryBudgeted()
	fmt.Printf("  %-8s %-6s %-30s %-10s %-10s %s\n", "区", "ok", "值 / degraded 原因", "延迟(ms)", "预算(ms)", "格子状态")
	for _, s := range secs {
		cell := map[bool]string{true: "出数", false: "degraded（值置空，兜底文案由客户端按区名渲染）"}[s.ok()]
		val := s.val
		if !s.ok() {
			val = s.err.Error()
		}
		lat := 0
		for _, r := range regions {
			if r.name == s.name {
				lat = r.latMs
			}
		}
		shown := lat
		if !s.ok() {
			shown = budgetMs // 超时格子实际占用 = 预算本身（掐停在到点一刻）
		}
		fmt.Printf("  %-8s %-6v %-30s %-10d %-8d %s\n", s.name, s.ok(), val, shown, budgetMs, cell)
	}
	deg, kept := namesOf(secs, false), namesOf(secs, true)
	e2e := handlerLatMs
	for _, r := range regions { // 并行端到端模型 = max(min(lat,预算)) + 装配，全部表值现算
		m := r.latMs
		if m > budgetMs {
			m = budgetMs
		}
		if m > e2e-handlerLatMs {
			e2e = m + handlerLatMs
		}
	}
	serialSum := 0
	for _, r := range regions {
		serialSum += min(r.latMs, budgetMs)
	}
	fmt.Printf("  degraded=%v · 照出的区 %d/%d（%v）→ HTTP 200 %s\n", deg, len(kept), len(secs), kept, mark[len(deg) == 1 && len(kept) == len(secs)-1])
	fmt.Printf("  端到端模型值：并行 max(min(lat,预算)) + 装配 = %d + %d = %d ms；若串行排队 = %d ms —— 预算把慢区砍在 %dms 而不是 %dms。\n",
		budgetMs, handlerLatMs, e2e, serialSum+handlerLatMs, budgetMs, regions[2].latMs)

	hdr("3. ❌ 对照：整页共享一条预算、error 出组 —— 一个慢拖整页 500")
	secs2, pageErr := homeSummaryShared()
	withVal := len(namesOf(secs2, true))
	fmt.Printf("  单条 %dms 总预算 + errgroup.WithContext：慢区到点返回 error → g.Wait() = %v\n", budgetMs, pageErr)
	fmt.Printf("  此刻其实有 %d/%d 个区已拿到值 —— 但整页按失败处理（HTTP 500），%d 个完成区陪葬 %s\n",
		withVal, len(secs2), withVal, mark[pageErr != nil && withVal == len(secs2)-1])
	fmt.Println("  · 区别只在两处：① 预算挂在整页还是挂在每区；② 区的 error 进格子还是出组。两个各改对，才有第 2 节的形状。")

	hdr("4. 与 S12 d21 四区聚合对拍：区名、口径、degraded 语义逐条现算")
	s12Names := []string{"账目摘要", "待办提醒", "通知未读", "最近动态"} // S12 d21 的区表（口径常量，对拍用）
	todayNames := []string{}
	for _, r := range regions {
		todayNames = append(todayNames, r.name)
	}
	fmt.Printf("  %-26s %-22s %-22s %s\n", "对拍项", "S12 d21 口径", "今天现算", "判定")
	c1 := fmt.Sprint(s12Names) == fmt.Sprint(todayNames)
	fmt.Printf("  %-26s %-22s %-22s %s\n", "四区区名与顺序", strings.Join(s12Names, "/"), strings.Join(todayNames, "/"), mark[c1])
	c2 := secs[2].name == "通知未读" && !secs[2].ok() && secs[2].val == ""
	fmt.Printf("  %-26s %-22s %-22s %s\n", "单区失败只标那一格", "degraded 写区名、整页 200", fmt.Sprintf("degraded=%v、整页 200", deg), mark[c2])
	u := unread(famA, uDad)
	fmt.Printf("  %-26s %-22s %-22s %s\n", "未读数唯一来源", "unread(fam,user) 一处定义", fmt.Sprintf("今天 unread=%d", u), mark[u == 3])
	fmt.Println("  （注：这是同一份区表/口径的跨天对拍 —— S12 d21 的 stdout 不在本进程里跑，比的是规则不是进程。）")

	hdr("5. 重试预算 maxTries=3：只给幂等读 —— 瞬断能救，结构性慢只是把同一堵墙再撞三次")
	dueRegion := regions[1]  // 待办提醒：幂等读，模拟第一次瞬断
	slowRegion := regions[2] // 通知未读：结构性慢（300ms > 100ms 预算）
	v1, l1, ok1 := retryRead(dueRegion, true)
	fmt.Printf("  ✅ %s（幂等读·瞬断模型）：尝试轨迹 %v → 终值 %q 成功=%s\n", dueRegion.name, l1, v1, mark[ok1])
	dueRowsBefore := len(dues)
	v2, l2, ok2 := retryRead(slowRegion, false)
	fmt.Printf("  ❌ %s（结构性慢）：3 次尝试全部到点（%v）→ 成功=%s，白耗 ≈ %dms（重试对「必然超时」零收益）\n",
		slowRegion.name, l2, mark[ok2], maxTries*budgetMs)
	fmt.Printf("  读不改行数：%s 重试前后 %d/%d 行（幂等 GET：重试安全的前提是「读不写」）；%q 未取到也不补写。\n",
		"calendar_due", dueRowsBefore, len(dues), v2)
	fmt.Println("  · 规则一句话：只有「幂等的读」能挂重试；写重试不靠运气，靠 client_request_id（下一节对账）。")

	hdr("6. 写操作自动重试的崩法：同 crid vs 不同 crid，行数对账当场数出来")
	logical := 2 // 本轮逻辑写：事件 notif-7、notif-8 各应落 1 行
	cridA := cridOf(famA, "notif-7", "deliver")
	accA := []bool{}
	for t := 1; t <= maxTries; t++ { // 同一事件重试：客户端复用同一 crid → 唯一索引去重
		accA = append(accA, tryDeliver(cridA))
	}
	rowsA := 0
	for _, a := range accA {
		if a {
			rowsA++
		}
	}
	fmt.Printf("  ✅ 同一 client_request_id（%s）重发 3 次：受理轨迹 %v → 表里 %d 行（去重生效）\n", cridA, accA, rowsA)
	cridB1, cridB2, cridB3 := cridOf(famA, "notif-8#retry1", "deliver"), cridOf(famA, "notif-8#retry2", "deliver"), cridOf(famA, "notif-8#retry3", "deliver")
	accB := []bool{tryDeliver(cridB1), tryDeliver(cridB2), tryDeliver(cridB3)} // 每次重试重新生成 crid → 索引拦不住
	rowsB := 0
	for _, a := range accB {
		if a {
			rowsB++
		}
	}
	fmt.Printf("  ❌ 每次重试换 crid（notif-8 三次三个 %s…）：受理轨迹 %v → 表里 %d 行（三次都当新写收进）\n", cridB1[:8], accB, rowsB)
	total := len(delivered)
	fmt.Printf("  对账：逻辑写 %d 笔 → 应落 %d 行；实际 %d 行，多落 %d 行 = 「写自动重试+换 crid」把同一事件投递了 3 遍 %s\n",
		logical, logical, total, total-logical, mark[total-logical == rowsB-1])
	fmt.Println("  · 写要重试，重试的必须是「同一个 crid + 服务端唯一索引」；客户端每重试换 crid，等于把去重键抹掉 —— 用户收到三遍同样的到账通知就是这么来的。")

	hdr("7. 收口")
	fmt.Printf("  · 预算的正确挂法：每区一条 WithTimeout（第 2 节 degraded=%v、整页 200）；整页一条 + error 出组 = 第 3 节 500、%d 个完成区陪葬。\n", deg, withVal)
	fmt.Printf("  · 重试只救「会自己好的」：幂等读 %v 次尝试成功；结构性慢 3 次全超时、白耗 %dms；写靠 crid 不靠重试（多落 %d 行是证据）。\n",
		len(l1), maxTries*budgetMs, total-logical)
	fmt.Printf("  · 金额全程 *_cents；family_id 恒进每条查询、只从会话取；到期/撤回走注册中心（幂等键三元组），业务面不自起计时器。\n")
	fmt.Println("\n=== W55 d16 到此结束 ===")
	fmt.Println("明天 d17：并发上限与公平性 —— 无上限一把梭 vs semaphore/固定 worker 池，驻留字节算出来，-race 复跑证明池无竞争。")
}

build.add:
// =====================================================================
// W55 d16：超时预算与部分失败 —— 一个慢不能整页坏
//
// 这一天在解决什么问题：S12 d21 把首页四区（账目摘要 / 待办提醒 / 通知未读 / 最近动态）用 errgroup
// 并行取，并定死「单区失败只标那一格 degraded、整页恒 200」。今天给这套形状补上「时间维度」：
// 每个区独立 context.WithTimeout 预算（100ms），慢区（通知未读，固定模拟延迟 300ms）到点只掐自己；
// ❌ 对照版整页共享一条预算且 error 出组 —— 一个区超时把 3 个本可完成的区拖成整页 500。
// 重试预算 maxTries=3 只给幂等读：瞬断第二次就成功、结构性慢重试三次仍超时（白等 3× 预算，数给你看）；
// 写操作不许自动重试：同一 client_request_id 重发 3 次唯一索引去重只剩 1 行，
// 每次重试重新生成 crid 则落 3 行 —— 行数差就是崩法证据，全部现算。
// 确定性：延迟是钉死毫秒常数，结论只依赖「表值 vs 预算」关系；结果按下标收口、打印前排序，两次跑字节一致。
// 金额 *_cents 整数；family_id 恒进每条查询且只从会话取；业务面不自起计时器（待办只读到期中心注册行，
// 幂等键 (source_system, source_id, kind)）。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d16
// =====================================================================
package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"golang.org/x/sync/errgroup"
)

const (
	famA, famB, uDad = "fam-A", "fam-B", "u-dad"
	month            = "2026-10"
	budgetMs         = 100 // 每区独立超时预算（钉死常数）
	maxTries         = 3   // 重试预算：只给幂等读
	handlerLatMs     = 15  // 装配耗时（模型常数）
)

var fixedNow = time.Date(2026, 10, 19, 9, 0, 0, 0, time.FixedZone("Asia/Shanghai", 8*3600))
var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string {
	a := c
	if a < 0 {
		a = -a
	}
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], a/100, a%100)
}
func dayOf(y, m, d, hh, mm int) time.Time {
	return time.Date(y, time.Month(m), d, hh, mm, 0, 0, fixedNow.Location())
}

// ---- 内存表（S12 d21 同口径的模拟行；本机无 PostgreSQL，全部在内存里数） ----

type noteRow struct {
	ID                  int64
	FamilyID, Recipient string
	Kind                string
	AmountCents         int64
	ReadAt, DeletedAt   time.Time
}

var notes = []noteRow{
	{1, famA, uDad, "budget_alert", 2518000, time.Time{}, time.Time{}},
	{2, famA, uDad, "reminder", 180000, time.Time{}, time.Time{}},
	{3, famA, uDad, "system", 0, time.Time{}, time.Time{}},
	{4, famA, uDad, "system", 0, fixedNow.Add(-12 * time.Hour), time.Time{}}, // 已读
	{5, famA, uDad, "system", 0, time.Time{}, fixedNow},                      // 软删（撤回）
	{6, famA, "u-kid", "reminder", 30000, time.Time{}, time.Time{}},          // 收件人不是自己
	{7, famB, "u-mom", "system", 0, time.Time{}, time.Time{}},                // 别家 → 不可见
}

func alive(n noteRow) bool { return n.ReadAt.IsZero() && n.DeletedAt.IsZero() }

// unread：全项目唯一的未读数口径（read_at IS NULL 且 deleted_at IS NULL 且 family_id 且收件人是自己）。
func unread(fam, user string) int {
	c := 0
	for _, n := range notes {
		if n.FamilyID == fam && n.Recipient == user && alive(n) {
			c++
		}
	}
	return c
}

type txnRow struct {
	ID, FamilyID, Kind    string
	AmountCents           int64
	OccurredAt, DeletedAt time.Time
}

var txns = []txnRow{
	{"t-01", famA, "expense", 128000, dayOf(2026, 10, 3, 20, 15), time.Time{}},
	{"t-02", famA, "expense", 86600, dayOf(2026, 10, 9, 12, 30), time.Time{}},
	{"t-03", famA, "income", 30000, dayOf(2026, 10, 11, 9, 0), time.Time{}},
	{"t-04", famA, "expense", 15000, dayOf(2026, 10, 15, 18, 40), time.Time{}},
	{"t-05", famA, "expense", 420000, dayOf(2026, 9, 30, 20, 15), time.Time{}}, // 上月：不进本月窗
	{"t-06", famA, "expense", 9900, dayOf(2026, 10, 17, 8, 5), fixedNow},       // 软删不进
	{"t-07", famB, "expense", 77000, dayOf(2026, 10, 12, 10, 0), time.Time{}},  // 别家
}

// monthNetCents：本月净额（整数分）与笔数 —— 与 S12 d21 同一条筛选。
func monthNetCents(fam string) (int64, int) {
	var net int64
	var n int
	for _, t := range txns {
		if t.FamilyID != fam || !t.DeletedAt.IsZero() ||
			t.OccurredAt.Before(dayOf(2026, 10, 1, 0, 0)) || !t.OccurredAt.Before(dayOf(2026, 11, 1, 0, 0)) {
			continue
		}
		n++
		if t.Kind == "expense" {
			net -= t.AmountCents
		} else {
			net += t.AmountCents
		}
	}
	return net, n
}

type actRow struct {
	ID, FamilyID, Text string
	AmountCents        int64
	CreatedAt          time.Time
}

var acts = []actRow{
	{"AF-01", famA, "小豆 交兴趣班", 210000, dayOf(2026, 10, 18, 16, 20)},
	{"AF-02", famA, "爸爸 记了一笔", 128000, dayOf(2026, 10, 19, 8, 55)},
}

// 到期中心注册行：幂等键 (source_system, source_id, kind)；业务面不自起计时器。
type dueRow struct {
	SourceSystem, SourceID, Kind, FamilyID string
	DueAt                                  time.Time
}

var dues = []dueRow{{"recurring_rule", "monthly-2026-10", "reminder", famA, dayOf(2026, 10, 26, 9, 0)}}

// ---- 四区：区名 + 来源 + 固定模拟延迟（ms，表值常数，不是测量值） ----
type regionDef struct {
	name, src string
	latMs     int
}

var regions = []regionDef{
	{"账目摘要", "finance_transaction 月窗聚合（family_id 恒在）", 25},
	{"待办提醒", "calendar_due 注册行（只读到期中心）", 45},
	{"通知未读", "homeos_notification count（唯一来源 unread）", 300}, // 今天那个「慢区」
	{"最近动态", "homeos_activity 游标分页首屏", 35},
}

// fetchValue：每区当场算出的展示值（口径与 S12 d21 逐字同形）。
func fetchValue(name string) (string, error) {
	switch name {
	case "账目摘要":
		net, n := monthNetCents(famA)
		return fmt.Sprintf("%s 元 · %d 笔", money(net), n), nil
	case "待办提醒":
		c := 0
		for _, d := range dues {
			if d.FamilyID == famA {
				c++
			}
		}
		return fmt.Sprintf("%d 条待办（到期中心注册）", c), nil
	case "通知未读":
		return fmt.Sprintf("%d 条未读", unread(famA, uDad)), nil
	case "最近动态":
		if len(acts) == 0 {
			return "暂无动态", nil
		}
		a := acts[len(acts)-1]
		return fmt.Sprintf("%s %s 元", a.Text, money(a.AmountCents)), nil
	}
	return "", errors.New("未知区: " + name)
}

// downstream：模拟该区下游 —— latMs 后带值返回；在此之前 ctx 先到期就带 ctx.Err() 返回。
// 结果由「latMs vs 预算」的钉死关系决定（25/45/35 < 100 < 300），select 两条分支不会打平 → 确定。

func downstream(ctx context.Context, latMs int, name string) (string, error) {
	select {
	case <-ctx.Done():
		return "", ctx.Err()
	case <-time.After(time.Duration(latMs) * time.Millisecond):
		return fetchValue(name)
	}
}

type secResult struct {
	name string
	val  string
	err  error
}

func (s secResult) ok() bool { return s.err == nil }

func namesOf(secs []secResult, wantOK bool) []string {
	var x []string
	for _, s := range secs {
		if s.ok() == wantOK {
			x = append(x, s.name)
		}
	}
	sort.Strings(x)
	return x
}

// homeSummaryBudgeted：✅ 正解 —— errgroup + 每区独立预算；单区错误只写进那一格，恒不返回组错误。
func homeSummaryBudgeted() []secResult {
	out := make([]secResult, len(regions))
	var g errgroup.Group
	for i, r := range regions {
		i, r := i, r
		g.Go(func() error {
			ctx, cancel := context.WithTimeout(context.Background(), budgetMs*time.Millisecond)
			defer cancel()
			v, err := downstream(ctx, r.latMs, r.name)
			out[i] = secResult{r.name, v, err} // 错误进格子，不进组 → 其余区不被牵连
			return nil
		})
	}
	_ = g.Wait()
	return out
}

// homeSummaryShared：❌ 对照 —— 整页共享一条预算，且区错误直接出组（errgroup 会 cancel gctx）。
func homeSummaryShared() ([]secResult, error) {
	ctx, cancel := context.WithTimeout(context.Background(), budgetMs*time.Millisecond)
	defer cancel()
	g, gctx := errgroup.WithContext(ctx)
	out := make([]secResult, len(regions))
	for i, r := range regions {
		i, r := i, r
		g.Go(func() error {
			v, err := downstream(gctx, r.latMs, r.name)
			out[i] = secResult{r.name, v, err}
			return err // error 出组：一个区超时 = 整页失败
		})
	}
	return out, g.Wait()
}

// retryRead：幂等读的重试循环。transientFirst=true 模拟「第一次瞬断（立即报错），之后恢复」。

type attemptLog struct {
	try     int
	outcome string
}

func retryRead(r regionDef, transientFirst bool) (string, []attemptLog, bool) {
	var logs []attemptLog
	for t := 1; t <= maxTries; t++ {
		ctx, cancel := context.WithTimeout(context.Background(), budgetMs*time.Millisecond)
		var v string
		var err error
		if transientFirst && t == 1 {
			err = errors.New("connection reset by peer（模拟瞬断，立即返回不占预算）")
		} else {
			v, err = downstream(ctx, r.latMs, r.name)
		}
		cancel()
		if err == nil {
			logs = append(logs, attemptLog{t, "成功"})
			return v, logs, true
		}
		logs = append(logs, attemptLog{t, err.Error()})
	}
	return "", logs, false
}

// ---- 写侧崩法：client_request_id 决定唯一索引去重与否 ----
func cridOf(fam, sourceID, kind string) string {
	h := sha256.Sum256([]byte(fam + "|" + sourceID + "|" + kind))
	return hex.EncodeToString(h[:])[:16] // 展示用截 16 hex；真实为完整摘要/UUID
}

var delivered []string // notification_delivery 表（只存 crid；存在即拒绝重复写入 = 唯一索引）

func tryDeliver(id string) bool {
	for _, c := range delivered {
		if c == id {
			return false
		}
	}
	delivered = append(delivered, id)
	return true
}

func main() {
