// =====================================================================
// W55 d17：并发上限与公平性 —— semaphore 与 worker 池
//
// 这一天在解决什么问题：d13~d16 解决「怎么并行、什么时候停」，今天解决「最多同时跑多少、谁先跑」。
// ① 无上限（每片一个 goroutine 一把梭）的驻留字节要算出来：go1.22 起新 goroutine 栈 2KiB
//
//	（runtime._StackMin=2048），每任务私有聚合缓冲按钉死的 32KiB 模型值计 —— 字节由函数算出，不是抄的。
//
// ② 固定 8 worker 池（channel 所有权转移）与信号量（带缓冲 chan 当令牌）两种限流并排，合计四路对拍。
// ③ 公平性：按家庭字典序一次性投递 → 队头 8 槽被重一家 fam-A 独占（构成由投递序直接算出）；
//
//	改成每轮每家 ≤ q=⌈池/家数⌉ 片的轮转 → 任意连续 8 槽窗口内单家峰值由前缀扫描现算、片数守恒核对。
//
// ④ -race 实跑：同目录 pool_race_test.go，CGO_ENABLED=1 go test -race 真跑 —— 反例版抓到
//
//	WARNING: DATA RACE + --- FAIL + 退出码非 0（本机 go1.22.5 不打印 Found N data race(s)），
//	池版回归 PASS 且终值精确；第 3 节贴的是那次真跑归一化后的原文。
//
// 金额 *_cents 整数；family_id 恒进每条查询与日志；本机无 PG：全部内存表。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d17
// -race 实跑：CGO_ENABLED=1 go test -race -count=1 -v ./lab/s13/d17
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
)

const (
	gorStackKiB = 2  // go1.22 起新 goroutine 初始栈：runtime._StackMin = 2048B
	taskBufKiB  = 32 // 每在跑任务私有聚合缓冲（钉死模型值，KiB）
	poolSize    = 8  // 固定 worker 数 / 信号量令牌数
)

var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---- 任务与家庭的定义：片数与金额全是钉死的表值 ----
type task struct {
	id    string
	fam   string
	cents int64 // 该片的合计 *_cents（整数分）
}

var famSlices = []struct {
	fam   string
	count int
}{{"fam-A", 26}, {"fam-B", 5}, {"fam-C", 3}, {"fam-D", 2}, {"fam-E", 2}} // 合计 38 片

var tasks []task

func init() {
	for _, fs := range famSlices { // 投递序 = 家庭字典序 + 片序（钉死，与调度无关）
		for i := 0; i < fs.count; i++ {
			tasks = append(tasks, task{fmt.Sprintf("%s#%02d", fs.fam, i+1), fs.fam, int64(5000 + i*1000)})
		}
	}
}

func famTotal(f string) int {
	c := 0
	for _, t := range tasks {
		if t.fam == f {
			c++
		}
	}
	return c
}

func allFams() []string {
	out := make([]string, len(famSlices))
	for i, fs := range famSlices {
		out[i] = fs.fam
	}
	sort.Strings(out)
	return out
}

func sumTasks(ts []task) (s int64) {
	for _, t := range ts {
		s += t.cents
	}
	return
}

func sumInt64(vs []int64) (s int64) {
	for _, v := range vs {
		s += v
	}
	return
}

// ---- 无上限一把梭：每个任务一个 goroutine（结果按下标收口 → 输出确定） ----
func runUnbounded() int64 {
	res := make([]int64, len(tasks))
	var wg sync.WaitGroup
	for i, t := range tasks {
		i, t := i, t
		wg.Add(1)
		go func() {
			defer wg.Done()
			res[i] = t.cents // 每任务只写自己的下标 → 无共享写
		}()
	}
	wg.Wait()
	return sumInt64(res)
}

// ---- 固定 8 worker 池：jobs channel → workers → results channel（所有权随 channel 转移） ----
func runWorkerPool() int64 {
	jobs := make(chan task)
	done := make(chan int64, poolSize)
	var wg sync.WaitGroup
	for w := 0; w < poolSize; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			var s int64
			for t := range jobs { // 领取即独占：同一任务只会被一个 worker 拿到
				s += t.cents
			}
			done <- s // worker 私有累加器随 goroutine 结束一次性交回
		}()
	}
	for _, t := range tasks {
		jobs <- t
	}
	close(jobs)
	wg.Wait()
	close(done)
	var s int64
	for v := range done {
		s += v
	}
	return s
}

// ---- 信号量版：每任务一个 goroutine，但同时最多 poolSize 张令牌在跑 ----
func runSemaphore() int64 {
	tok := make(chan struct{}, poolSize)
	res := make([]int64, len(tasks))
	var wg sync.WaitGroup
	for i, t := range tasks {
		i, t := i, t
		wg.Add(1)
		go func() {
			defer wg.Done()
			tok <- struct{}{} // 拿令牌（满 8 张时这里排队阻塞）
			defer func() { <-tok }()
			res[i] = t.cents
		}()
	}
	wg.Wait()
	return sumInt64(res)
}

// fairnessNaive：❌ 家庭字典序一次性投递。结构性事实：池刚开闸时的前 poolSize 个在跑槽位
// 全被队头那批占着 —— 队头批的家庭构成由投递序直接切出来，与调度无关。
func fairnessNaive() (headBatch string, headFam string) {
	cnt := map[string]int{}
	for i := 0; i < poolSize && i < len(tasks); i++ {
		cnt[tasks[i].fam]++
	}
	var names []string
	for f := range cnt {
		names = append(names, f)
	}
	sort.Strings(names)
	if len(cnt) == 1 {
		headFam = names[0]
	}
	parts := make([]string, 0, len(names))
	for _, f := range names {
		parts = append(parts, fmt.Sprintf("%s×%d", f, cnt[f]))
	}
	return strings.Join(parts, " "), headFam
}

// fairnessQuota：✅ 跨家庭轮转投递 —— 每轮每家最多递 q 片。返回投递序与
// 「任意连续 poolSize 片的窗口里单家峰值」（前缀扫描现算）。
func fairnessQuota(q int) (order []string, maxWin int) {
	remaining := map[string]int{}
	for _, f := range allFams() {
		remaining[f] = famTotal(f)
	}
	for {
		progress := false
		for _, f := range allFams() { // 家庭字典序轮转：稳定、与调度无关
			for k := 0; k < q && remaining[f] > 0; k++ {
				order = append(order, f)
				remaining[f]--
				progress = true
			}
		}
		if !progress {
			break
		}
	}
	for i := 0; i+poolSize <= len(order); i++ {
		cnt := map[string]int{}
		for _, f := range order[i : i+poolSize] {
			cnt[f]++
		}
		for _, c := range cnt {
			if c > maxWin {
				maxWin = c
			}
		}
	}
	return
}

func main() {
	nFam, nTask := len(allFams()), len(tasks)
	us, ps, ss := runUnbounded(), runWorkerPool(), runSemaphore()
	ideal := sumTasks(tasks)

	hdr(fmt.Sprintf("1. 场景：%d 个家庭共 %d 个聚合片（投递序 = 家庭字典序+片序，钉死），金额 *_cents 整数", nFam, nTask))
	fmt.Printf("  %-8s %-6s %s\n", "家庭", "片数", "片金额分布（分）")
	for _, fs := range famSlices {
		fmt.Printf("  %-8s %-6d 第 1..%d 片 = 5000..%d\n", fs.fam, fs.count, fs.count, 5000+(fs.count-1)*1000)
	}
	fmt.Printf("  fam-A 一家 %d/%d 片占多半 —— 「上限」和「公平」是两个问题，都要有答案。\n", famTotal("fam-A"), nTask)

	hdr("2. 无上限一把梭 vs 固定 8 worker：驻留字节是算出来的")
	nv := nTask * (gorStackKiB + taskBufKiB)
	pv := poolSize * (gorStackKiB + taskBufKiB)
	fmt.Printf("  模型：每在跑任务驻留 = goroutine 栈 %dKiB + 私有聚合缓冲 %dKiB = %dKiB（go1.22 新 goroutine 栈 2KiB；缓冲是钉死模型值）\n",
		gorStackKiB, taskBufKiB, gorStackKiB+taskBufKiB)
	fmt.Printf("  ❌ 无上限（每片一个 goroutine，%d 个同跑）：%d × %dKiB = %d KiB = %.2f MiB\n", nTask, nTask, gorStackKiB+taskBufKiB, nv, float64(nv)/1024)
	fmt.Printf("  ✅ 固定 %d worker 池：%d × %dKiB = %d KiB —— 驻留上限与片数解耦（片数翻倍，驻留不动）\n", poolSize, poolSize, gorStackKiB+taskBufKiB, pv)
	fmt.Printf("  比值 %d/%d = %d×；家庭从 %d 家涨到 %d 家它也不涨 —— 这就是「上限」二字的价值。\n", nv, pv, nv/pv, nFam, nFam*10)

	hdr("3. 三种实现合计四路对拍 + -race 实跑结果")
	fmt.Printf("  无上限=%d · %d worker 池=%d · 信号量(令牌 %d 张)=%d · 逐片直加=%d → 四路同点 %s\n",
		us, poolSize, ps, poolSize, ss, ideal, mark[us == ps && ps == ss && ss == ideal])
	fmt.Println("  channel vs 信号量分工：池 = 所有权转移（任务发进 chan，谁领走归谁，worker 私有累加器最后交回）；")
	fmt.Println("  信号量 = 计数许可（数据仍留在各自 goroutine 闭包里，只限制「同时进入的个数」）。")
	fmt.Println("  拿信号量当队列使：N 份闭包照旧分配，省的是 CPU 不是内存 —— 要省驻留就得上池（第 2 节的字节差）。")
	fmt.Println("  同目录 pool_race_test.go 实跑（CGO_ENABLED=1 go test -race -count=1 -v ./lab/s13/d17；判据 = WARNING + --- FAIL + 退出码非 0）：")
	fmt.Println("    TestRacyNoLimitFanout   → WARNING: DATA RACE（下面原文节选），--- FAIL，退出码非 0；")
	fmt.Printf("    TestPoolRaceFree        → PASS：池版无报告，且终值 == Σ钉死片金额 = %d。\n", ideal)
	fmt.Println("  反例真跑报告节选 —— 归一化只动了三类无信息量的字节：0x… 地址 → 0xADDR、goroutine 编号 → G#、绝对路径 → 模块相对路径；")
	fmt.Println("  行结构、行号、函数名、+0x… 偏移逐字未改：")
	report := []string{
		"WARNING: DATA RACE",
		"Read at 0xADDR by goroutine G#:",
		"  homecube/server/lab/s13/d17.(*adder).add()",
		"      lab/s13/d17/pool_race_test.go:24 +0xc4",
		"  homecube/server/lab/s13/d17.TestRacyNoLimitFanout.func1()",
		"      lab/s13/d17/pool_race_test.go:81 +0x99",
		"",
		"Previous write at 0xADDR by goroutine G#:",
		"  homecube/server/lab/s13/d17.(*adder).add()",
		"      lab/s13/d17/pool_race_test.go:24 +0xdb",
		"  homecube/server/lab/s13/d17.TestRacyNoLimitFanout.func1()",
		"      lab/s13/d17/pool_race_test.go:81 +0x99",
		"",
		"Goroutine G# (running) created at:",
		"  homecube/server/lab/s13/d17.TestRacyNoLimitFanout()",
		"      lab/s13/d17/pool_race_test.go:78 +0x194",
	}
	for _, ln := range report {
		fmt.Printf("    %s\n", ln)
	}
	fmt.Println("  怎么读：一帧在 :24（a.acc += v）读到 0xADDR，另一帧同一行刚在它上面写完同一地址 —— 同址、两 goroutine、无同步 → 判 DATA RACE；")
	fmt.Println("  :81 是 fanout 调用点、:78 是 go 语句（两个 goroutine 的创建点）；那次真跑共吐了 2 条 WARNING（读写一条、写写一条），上面节选第一条；")
	fmt.Println("  不加 -race 时这个测试照样 PASS（终值常恰好相等）—— 「看起来是对的」正是判据①要先复现再修的那一半。")

	hdr("4. 公平性 ❌：按家庭字典序一次性投递 —— 队头 8 槽被重一家独占（构成由投递序切出来）")
	headBatch, headFam := fairnessNaive()
	fmt.Printf("  池刚开闸、队头还没消化时，在跑的 8 个槽位的家庭构成 = [%s]（前 %d 片按投递序切，确定性事实）\n", headBatch, poolSize)
	fmt.Printf("  独占方 = %s %s，它后面还排着 %d 片：fam-B/C/D/E 的任务在队列里干等它跑完。\n",
		headFam, mark[headFam != ""], famTotal("fam-A")-poolSize)
	fmt.Println("  上限有了（并发 ≤ 8），公平没有：一家能把池的吞吐整个吃掉 —— 别的家庭首屏等它排完。")

	hdr("5. 公平性 ✅：跨家庭轮转投递，每轮每家 ≤ q 片")
	q := (poolSize + nFam - 1) / nFam // q = ⌈池 / 家数⌉ = ⌈8/5⌉ = 2
	order, maxWin := fairnessQuota(q)
	fmt.Printf("  q = ⌈%d/%d⌉ = %d：每轮每家最多递 %d 片再轮下一家；投递序前 %d 片 = %v\n", poolSize, nFam, q, q, 2*q, order[:2*q])
	fmt.Printf("  %-8s %-8s %s\n", "家庭", "应有片数", "轮转后实拿（Σ守恒核对）")
	got := map[string]int{}
	for _, f := range order {
		got[f]++
	}
	tot := 0
	for _, f := range allFams() {
		tot += got[f]
		fmt.Printf("  %-8s %-8d %d\n", f, famTotal(f), got[f])
	}
	fmt.Printf("  守恒核对：Σ实拿 %d == 总片数 %d %s —— 轮转没丢片也没算重。\n", tot, nTask, mark[tot == nTask])
	fmt.Printf("  窗口扫描（前缀连续 %d 片）：任意 8 槽窗口内单家峰值 = %d 片（≤ q=%d %s）—— fam-A 从「独占队头 8 槽」压到 ≤ %d。\n",
		poolSize, maxWin, q, mark[maxWin <= q], q)
	fmt.Println("  · 家庭多到 q=1 还挤时，再套「每家庭同时在跑 ≤ q」的信号量 —— 上限管总量、轮转管次序、配额管单家，三件事分开设。")

	hdr("6. 收口")
	fmt.Printf("  · 驻留字节：无上限 %.2f MiB vs %d worker %d KiB —— 由 (栈+缓冲)×并发数 的函数算出，不是抄来的。\n", float64(nv)/1024, poolSize, pv)
	fmt.Printf("  · 四路合计同点 = %d（无上限/池/信号量/直加）；-race 实跑：反例 WARNING+FAIL、池版 PASS。\n", ideal)
	fmt.Printf("  · 公平性：无配额 = 队头 8 槽一家独占；轮转后窗口峰值 %d ≤ q=%d，Σ片数守恒 %d/%d。\n", maxWin, q, tot, nTask)
	fmt.Println("  · 金额全程 *_cents；family_id 恒进每条查询与日志；真环境复跑：CGO_ENABLED=1 go test -race -count=1 ./lab/s13/d17")
	fmt.Println("\n=== W55 d17 到此结束 ===")
	fmt.Println("明天 d18：W55 收口 —— 逐桶 0 + 耗时对照 + ctx 超时行为表，并发两条判据打 ✅，交 W56。")
}

