// =====================================================================
// W55 d17：并发上限与公平性 —— semaphore 与 worker 池
//
// 这一天在解决什么问题：d13~d16 解决「怎么并行、什么时候停」，今天解决「最多同时跑多少、谁先跑」。
// ① 无上限（每片一个 goroutine 一把梭）的驻留字节要算出来：go1.22 起新 goroutine 栈 2KiB
//
//	（runtime._StackMin=2048），每任务私有聚合缓冲按钉死的 32KiB 模型值计 —— 字节由函数算出，不是抄的。
//
// ② 固定 8 worker 池（channel 所有权转移）与信号量（带缓冲 chan 当令牌）两种限流并排，合计四路对拍。
// ③ 公平性：按家庭字典序一次性投递 → 队头 8 槽被重一家 fam-A 独占（构成由投递序直接算出）；
//
//	改成每轮每家 ≤ q=⌈池/家数⌉ 片的轮转 → 任意连续 8 槽窗口内单家峰值由前缀扫描现算、片数守恒核对。
//
// ④ -race 实跑：同目录 pool_race_test.go，CGO_ENABLED=1 go test -race 真跑 —— 反例版抓到
//
//	WARNING: DATA RACE + --- FAIL + 退出码非 0（本机 go1.22.5 不打印 Found N data race(s)），
//	池版回归 PASS 且终值精确；第 3 节贴的是那次真跑归一化后的原文。
//
// 金额 *_cents 整数；family_id 恒进每条查询与日志；本机无 PG：全部内存表。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d17
// -race 实跑：CGO_ENABLED=1 go test -race -count=1 -v ./lab/s13/d17
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
)

const (
	gorStackKiB = 2  // go1.22 起新 goroutine 初始栈：runtime._StackMin = 2048B
	taskBufKiB  = 32 // 每在跑任务私有聚合缓冲（钉死模型值，KiB）
	poolSize    = 8  // 固定 worker 数 / 信号量令牌数
)

var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---- 任务与家庭的定义：片数与金额全是钉死的表值 ----
type task struct {
	id    string
	fam   string
	cents int64 // 该片的合计 *_cents（整数分）
}

var famSlices = []struct {
	fam   string
	count int
}{{"fam-A", 26}, {"fam-B", 5}, {"fam-C", 3}, {"fam-D", 2}, {"fam-E", 2}} // 合计 38 片

var tasks []task

func init() {
	for _, fs := range famSlices { // 投递序 = 家庭字典序 + 片序（钉死，与调度无关）
		for i := 0; i < fs.count; i++ {
			tasks = append(tasks, task{fmt.Sprintf("%s#%02d", fs.fam, i+1), fs.fam, int64(5000 + i*1000)})
		}
	}
}

func famTotal(f string) int {
	c := 0
	for _, t := range tasks {
		if t.fam == f {
			c++
		}
	}
	return c
}

func allFams() []string {
	out := make([]string, len(famSlices))
	for i, fs := range famSlices {
		out[i] = fs.fam
	}
	sort.Strings(out)
	return out
}

func sumTasks(ts []task) (s int64) {
	for _, t := range ts {
		s += t.cents
	}
	return
}

func sumInt64(vs []int64) (s int64) {
	for _, v := range vs {
		s += v
	}
	return
}

// ---- 无上限一把梭：每个任务一个 goroutine（结果按下标收口 → 输出确定） ----
func runUnbounded() int64 {
	res := make([]int64, len(tasks))

	var wg sync.WaitGroup
	for i, t := range tasks {
		i, t := i, t
		wg.Add(1)
		go func() {
			defer wg.Done()
			res[i] = t.cents // 每任务只写自己的下标 → 无共享写
		}()
	}
	wg.Wait()
	return sumInt64(res)
}

// ---- 固定 8 worker 池：jobs channel → workers → results channel（所有权随 channel 转移） ----
func runWorkerPool() int64 {
	jobs := make(chan task)
	done := make(chan int64, poolSize)
	var wg sync.WaitGroup
	for w := 0; w < poolSize; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			var s int64
			for t := range jobs { // 领取即独占：同一任务只会被一个 worker 拿到
				s += t.cents
			}
			done <- s // worker 私有累加器随 goroutine 结束一次性交回
		}()
	}
	for _, t := range tasks {
		jobs <- t
	}
	close(jobs)
	wg.Wait()
	close(done)
	var s int64
	for v := range done {
		s += v
	}
	return s
}

// ---- 信号量版：每任务一个 goroutine，但同时最多 poolSize 张令牌在跑 ----
func runSemaphore() int64 {
	tok := make(chan struct{}, poolSize)
	res := make([]int64, len(tasks))

	var wg sync.WaitGroup
	for i, t := range tasks {
		i, t := i, t
		wg.Add(1)
		go func() {
			defer wg.Done()
			tok <- struct{}{} // 拿令牌（满 8 张时这里排队阻塞）
			defer func() { <-tok }()
			res[i] = t.cents
		}()
	}
	wg.Wait()
	return sumInt64(res)
}

// fairnessNaive：❌ 家庭字典序一次性投递。结构性事实：池刚开闸时的前 poolSize 个在跑槽位
// 全被队头那批占着 —— 队头批的家庭构成由投递序直接切出来，与调度无关。
func fairnessNaive() (headBatch string, headFam string) {
	cnt := map[string]int{}
	for i := 0; i < poolSize && i < len(tasks); i++ {
		cnt[tasks[i].fam]++
	}
	var names []string
	for f := range cnt {
		names = append(names, f)
	}
	sort.Strings(names)
	if len(cnt) == 1 {
		headFam = names[0]
	}
	parts := make([]string, 0, len(names))
	for _, f := range names {
		parts = append(parts, fmt.Sprintf("%s×%d", f, cnt[f]))
	}
	return strings.Join(parts, " "), headFam
}

// fairnessQuota：✅ 跨家庭轮转投递 —— 每轮每家最多递 q 片。返回投递序与
// 「任意连续 poolSize 片的窗口里单家峰值」（前缀扫描现算）。
func fairnessQuota(q int) (order []string, maxWin int) {
	remaining := map[string]int{}
	for _, f := range allFams() {
		remaining[f] = famTotal(f)
	}
	for {
		progress := false
		for _, f := range allFams() { // 家庭字典序轮转：稳定、与调度无关
			for k := 0; k < q && remaining[f] > 0; k++ {
				order = append(order, f)
				remaining[f]--
				progress = true
			}
		}
		if !progress {
			break
		}
	}
	for i := 0; i+poolSize <= len(order); i++ {
		cnt := map[string]int{}
		for _, f := range order[i : i+poolSize] {
			cnt[f]++
		}
		for _, c := range cnt {
			if c > maxWin {
				maxWin = c
			}
		}
	}
	return
}

