// =====================================================================
// W55 d18：W55 收口 —— 正确性与性能双证据
//
// 这一天才做三件「把 W55 钉死」的事，全部当场算：
// ① 正确性：同一批 ledger，串行一条路 vs 并行分片归并一条路，逐桶对 income/expense/net/count
//
//	四类 *_cents 整数口径 diff —— 非 0 桶必须为 0 才放行（沿用 d14 的桶契约与分片归并）。
//
// ② 性能：调用数 × 固定单价的耗时对照表（d13 模型）：串行墙钟 vs 并行≈最慢一路，比值现算。
// ③ ctx 超时行为表：正常 / 父超时 / 主动取消(父、子派生随停) / 子预算先到期 四种时序各跑一次真
//
//	ctx，收现场 Err()、执行格数、副作用行数（d15 机制收拢成一张表）。
//
// 判据自测（五条判据里并发相关的两条）：① -race 抓到真实竞争并修好 —— 本程序现场重放「修复版」
// 形态（atomic 与 Mutex 两路 fanout 终值精确），复跑报告命令在 d06/d17；② channel vs Mutex 分工 ——
// 本程序并行路就是「所有权转移用 channel」（分片整个交进 channel、归并无共享写），共享标量才上 Mutex。
// 金额一律 *_cents 整数；family_id 恒进每一条聚合与每一条日志；本机无 PG，全部内存表。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d18
// =====================================================================
package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

const (
	famID      = "aaaaaaaa-0000-4000-8000-000000000001"
	callUnitMs = 4 // d13 同款单价：一次「账户×分类」SUM 的固定往返成本（毫秒），不真计时
)

var famLoc = time.FixedZone("Asia/Shanghai", 8*3600)

var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func day0(y, m, d int) time.Time {
	return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc)
}

// ---- 桶契约（S11 W46 / d14 原样）：month 档、家庭时区、稠密枚举、空桶照出行 ----
func bucketStart(t time.Time) time.Time { l := t.In(famLoc); return day0(l.Year(), int(l.Month()), 1) }
func bucketEnd(t time.Time) time.Time   { return bucketStart(t).AddDate(0, 1, 0) }
func bucketKey(t time.Time) string      { return t.In(famLoc).Format("2006-01") }

func parseKey(s string) (time.Time, error) {
	t, e := time.ParseInLocation("2006-01", s, famLoc)
	if e != nil || bucketKey(t) != s {
		return time.Time{}, fmt.Errorf("period=%q 不是规范 month 桶键（形如 2026-07）", s)
	}
	return t, nil
}

func enumKeys(from, to time.Time) []string {
	var out []string
	for cur := bucketStart(from); cur.Before(to); cur = bucketEnd(cur) {
		out = append(out, bucketKey(cur))
	}
	return out
}

// ---- 内存表 finance_transaction：14 行，其中 1 行跨家庭、1 行软删（进口径由 pick 现场过滤） ----
type txn struct {
	id, fam, kind string
	cents         int64
	at            time.Time
	soft          bool
}

var ledger = []txn{
	{"t-01", famID, "income", 860000, day0(2026, 5, 5), false},
	{"t-02", famID, "expense", 230000, day0(2026, 5, 11), false},
	{"t-03", famID, "expense", 128000, day0(2026, 6, 3), false},
	{"t-04", famID, "income", 1200000, day0(2026, 6, 5), false},
	{"t-05", famID, "expense", 500000, day0(2026, 7, 25), false},
	{"t-06", famID, "expense", 318400, day0(2026, 7, 30), true},    // 软删：不进桶
	{"t-07", "fam-B", "expense", 999000, day0(2026, 7, 15), false}, // 跨家庭：404 语义挡在门外
	{"t-08", famID, "expense", 120000, day0(2026, 8, 8), false},
	{"t-09", famID, "income", 460000, day0(2026, 8, 12), false},
	{"t-10", famID, "expense", 33000, day0(2026, 9, 1), false},
	{"t-11", famID, "income", 300000, day0(2026, 9, 28), false},
	{"t-12", famID, "expense", 70000, day0(2026, 10, 2), false},
	{"t-13", famID, "income", 500000, day0(2026, 10, 5), false},
	{"t-14", famID, "expense", 15000, day0(2026, 10, 20), false},
}

type bkt struct{ income, expense, net, count int64 }

var winFrom, winTo = day0(2026, 5, 1), day0(2026, 11, 1)
var keys = enumKeys(winFrom, winTo)

func pick() []txn {
	var out []txn
	for _, r := range ledger {
		if r.fam == famID && !r.soft && !r.at.Before(winFrom) && r.at.Before(winTo) {
			out = append(out, r)
		}
	}
	return out
}

// trend：唯一出桶现场；写进调用方传进来的那张 map（传私有分片所以能并行 —— 共享 map 会 fatal，d14 已证）。
func trend(rows []txn, into map[string]*bkt) {
	for _, r := range rows {
		b := into[bucketKey(r.at)]
		if r.kind == "income" {
			b.income += r.cents
		} else {
			b.expense += r.cents
		}
		b.net, b.count = b.income-b.expense, b.count+1
	}
}

func dense() map[string]*bkt {
	m := map[string]*bkt{}
	for _, k := range keys {
		m[k] = &bkt{}
	}
	return m
}

func serialAgg() map[string]*bkt { m := dense(); trend(pick(), m); return m }

// parallelAgg：3 个 goroutine 私有分片 → 分片整个交进 channel（所有权转移）→ 单线程固定序归并。
func parallelAgg() map[string]*bkt {
	rows := pick()
	const shards = 3
	ch := make(chan map[string]*bkt, shards)
	var wg sync.WaitGroup
	for s := 0; s < shards; s++ {
		wg.Add(1)
		go func(s int) {
			defer wg.Done()
			part := dense()
			var mine []txn
			for i, r := range rows {
				if i%shards == s {
					mine = append(mine, r)
				}
			}
			trend(mine, part)
			ch <- part // 归并阶段没有任何共享写：分片已经交出来了
		}(s)
	}
	wg.Wait()
	close(ch)
	merged := dense()
	for part := range ch {
		for k, b := range part {
			m := merged[k]
			m.income, m.expense, m.count = m.income+b.income, m.expense+b.expense, m.count+b.count
			m.net = m.income - m.expense
		}
	}
	return merged
}

// ---- 耗时模型（d13）：8 账户各带自己的分类格数；调用数 = 1 + Σ格数 ----
var acctCells = []int{2, 3, 3, 1, 2, 2, 6, 2} // 钉死表值：每账户真实出现过的分类格数

func callStats() (calls, maxPath, sumCells int) {
	sumCells = 0
	for _, k := range acctCells {
		sumCells += k
		if k > maxPath {
			maxPath = k
		}
	}
	return 1 + sumCells, maxPath, sumCells
}

// ---- 判据① 现场重放「修复版」形态：atomic 与 Mutex 两路 fanout，终值必须精确 ----
func fanoutAtomic(n int) int64 {
	var c int64
	var wg sync.WaitGroup
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			atomic.AddInt64(&c, 1)
		}()
	}
	close(start)
	wg.Wait()
	return c
}

type lockedCounter struct {
	mu sync.Mutex
	n  int
}

func fanoutMutex(n int) int {
	lc := &lockedCounter{}
	var wg sync.WaitGroup
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			lc.mu.Lock()
			lc.n++ // 共享标量的读改写：临界区整体串行化（d03/d06 口径）
			lc.mu.Unlock()
		}()
	}
	close(start)
	wg.Wait()
	return lc.n
}

// ---- ctx 行为表现场：四种时序各真跑一次，收 Err() 与格数 ----
var (
	aggN   int64
	sideN  int64
	cellsN = 3 // 一路聚合的格数
)

func runCellAware(ctx context.Context, per time.Duration) error {
	for i := 0; i < cellsN; i++ {
		if err := ctx.Err(); err != nil { // 每格起跑前先查：已到期就停，剩余格 0 成本
			return err
		}
		time.Sleep(per)
		atomic.AddInt64(&aggN, 1)
	}
	return nil
}

type ctxCase struct {
	when  string
	err   error
	calls int64 // 该 case 内实际执行的格数（atomic 前后差值，现算）
	note  string
}

func main() {
	serial := serialAgg()
	par := parallelAgg()
	rows := pick()

	hdr(fmt.Sprintf("1. 同一批数据：%d 行进口径（剔跨家庭 1 行、剔软删 1 行），month 桶稠密 %d 个（family_id=%s）", len(rows), len(keys), famID))
	fmt.Println("  窗 [2026-05, 2026-11)（右端排他）；金额 *_cents 整数，桶契约 = bucketStart/End/Key/parseKey（d14 原样）。")
	rej := 0
	for _, b := range []string{"2026-9", "202613", "", "2026-07-01"} {
		if _, e := parseKey(b); e != nil {
			rej++
		}
	}
	fmt.Printf("  parseKey 反例核对：%d/%d 个非法桶键全被拒（不猜窗、不回落默认档）。\n", rej, 4)

	hdr("2. 正确性证据：串行 vs 并行分片归并，逐桶四类整数分 diff 必须全 0")
	fmt.Printf("  %-8s %-9s %-9s %-10s %-5s %-19s %s\n", "桶键", "in", "exp", "net", "笔", "diff(in/exp/net/cnt)", "判定")
	bad := 0
	var tIn, tExp, tNet, tCnt int64
	for _, k := range keys { // 稠密桶键序：与调度无关，空桶照出行
		s, p := serial[k], par[k]
		d := [4]int64{p.income - s.income, p.expense - s.expense, p.net - s.net, p.count - s.count}
		if d != [4]int64{} {
			bad++
		}
		tIn, tExp, tNet, tCnt = tIn+p.income, tExp+p.expense, tNet+p.net, tCnt+p.count
		fmt.Printf("  %-8s %-9d %-9d %-10d %-5d %-19s %s\n", k, p.income, p.expense, p.net, p.count,
			fmt.Sprintf("%d/%d/%d/%d", d[0], d[1], d[2], d[3]), mark[d == [4]int64{}])
	}
	var dIn, dExp, dCnt int64 // 第三条独立算路：不切桶、逐笔直加
	for _, r := range rows {
		dCnt++
		if r.kind == "income" {
			dIn += r.cents
		} else {
			dExp += r.cents
		}
	}
	fmt.Printf("  非 0 桶 %d/%d %s；Σ桶 net=%d == Σ逐笔(in-exp)=%d 且笔数 %d==%d %s —— 并行没算重/漏算。\n",
		bad, len(keys), mark[bad == 0], tNet, dIn-dExp, tCnt, dCnt, mark[tNet == dIn-dExp && tCnt == dCnt])

	hdr("3. 性能证据：调用数 × 单价的耗时对照（d13 模型，钉死常数、不真计时）")
	calls, maxPath, sumCells := callStats()
	serialMs, parMs := calls*callUnitMs, (1+maxPath)*callUnitMs
	fmt.Printf("  %-12s %-10s %-10s %-10s %s\n", "路径", "调用数", "墙钟(ms)", "单价(ms)", "公式")
	fmt.Printf("  %-12s %-10d %-10d %-10d %d × %d 全排队（列表 1 + 分类 %d）\n", "串行 N+1", calls, serialMs, callUnitMs, calls, callUnitMs, sumCells)
	fmt.Printf("  %-12s %-10d %-10d %-10d (列表1 + 最慢%d格) × %d\n", "并行按账户", calls, parMs, callUnitMs, maxPath, callUnitMs)
	fmt.Printf("  比值 %d/%d = %.2f×；调用数两路同为 %d（= 1+Σ格数 %d %s）——并行只搬「排队」，不合并往返。\n",
		serialMs, parMs, float64(serialMs)/float64(parMs), calls, sumCells+1, mark[calls == sumCells+1])

	hdr("4. ctx 超时行为表：四种时序各真跑一次（中间列全是现场值，不打印任何测量耗时）")
	var cases []ctxCase
	{ // ① 正常：预算远大于工作量
		b0 := atomic.LoadInt64(&aggN)
		ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
		e := runCellAware(ctx, 5*time.Millisecond)
		cases = append(cases, ctxCase{"① 预算100ms vs 3×5ms", e, atomic.LoadInt64(&aggN) - b0, "全部执行，返回 nil"})
		cancel()
	}
	{ // ② 父超时：每格起跑前查 ctx
		b0 := atomic.LoadInt64(&aggN)
		ctx, cancel := context.WithTimeout(context.Background(), 7*time.Millisecond)
		e := runCellAware(ctx, 5*time.Millisecond)
		cases = append(cases, ctxCase{"② 父超时7ms（格5ms）", e, atomic.LoadInt64(&aggN) - b0, "前两格在预算内存活期起跑，第 3 格起跑前被拦"})
		cancel()
	}
	{ // ③ 主动 cancel 父：子派生随停（树形单向传播）
		parent, pcancel := context.WithCancel(context.Background())
		child, cccancel := context.WithTimeout(parent, time.Second)
		b0 := atomic.LoadInt64(&aggN)
		var got error
		var wg sync.WaitGroup
		wg.Add(1)
		go func() { defer wg.Done(); got = runCellAware(child, 5*time.Millisecond) }()
		time.Sleep(3 * time.Millisecond) // 第一格起跑后、第二格返回前取消
		pcancel()
		wg.Wait()
		cases = append(cases, ctxCase{"③ 3ms 时 cancel(父)，子1s", got, atomic.LoadInt64(&aggN) - b0, "子随父停：cancel 沿树往下、不回流"})
		cccancel()
	}
	{ // ④ 子派生先到期（父很长）
		b0 := atomic.LoadInt64(&aggN)
		parent, pcancel := context.WithTimeout(context.Background(), time.Minute)
		child, cccancel := context.WithTimeout(parent, 7*time.Millisecond)
		e := runCellAware(child, 5*time.Millisecond)
		cases = append(cases, ctxCase{"④ 子派生7ms（父1min）", e, atomic.LoadInt64(&aggN) - b0, "实际到期 = min(父剩余, 子预算)"})
		cccancel()
		pcancel()
	}
	claims := []error{nil, context.DeadlineExceeded, context.Canceled, context.DeadlineExceeded}
	okRows := 0
	fmt.Printf("  %-24s %-28s %-10s %s\n", "时序", "下游收到 Err()", "执行格数", "结构性结论")
	for i, c := range cases {
		if c.err == claims[i] {
			okRows++
		}
		fmt.Printf("  %-24s %-28s %-10d %s\n", c.when, c.err, c.calls, c.note)
	}
	fmt.Printf("  Err() 与预期逐一相等 %d/4 %s；执行格数由 atomic 前后差值现算（超时/取消后剩余格 0 增量）。\n", okRows, mark[okRows == 4])
	b0 := atomic.LoadInt64(&sideN)
	{ // 副作用反例收拢一行：先写后查版
		ctx, cancel := context.WithTimeout(context.Background(), 7*time.Millisecond)
		for i := 0; i < cellsN; i++ {
			time.Sleep(5 * time.Millisecond)
			atomic.AddInt64(&sideN, 1) // 先落一行
			if ctx.Err() != nil {      // 后查 ctx：拦得住返回值，拦不住已落的行
				break
			}
		}
		cancel()
	}
	fmt.Printf("  副作用对照（d15 反例的最小重放）：「先写后查」同一 7ms 预算当场落 %d 行、结果被丢 —— 修复口径 = 先查后写 + 幂等键对账（W56 d20）。\n",
		atomic.LoadInt64(&sideN)-b0)

	hdr("5. 判据自测（五条判据里并发相关的 ①②，判定全部现算）")
	aN := fanoutAtomic(200)
	mN := fanoutMutex(200)
	fmt.Printf("  ①「-race 跑出真实竞争并修好」：本程序现场重放两路修复形态 —— atomic fanout 终值 %d/200 %s、Mutex fanout 终值 %d/200 %s；\n",
		aN, mark[aN == 200], mN, mark[mN == 200])
	fmt.Printf("     竞争本体见 d06（S10 乐观锁 + S11 trendCalls）与 d17（无保护 fanout）：判据 = WARNING: DATA RACE + --- FAIL + 退出码非 0\n")
	fmt.Printf("     （本机 go1.22.5 不打印 Found N data race(s)）。复跑：CGO_ENABLED=1 go test -race -count=1 ./lab/s13/d06 与 ./lab/s13/d17\n")
	fmt.Printf("  ②「channel vs Mutex 分工」：所有权转移用 channel —— 第 2 节并行路就是分片整个交进 channel、归并零共享写（非 0 桶 %d/%d %s）；\n", bad, len(keys), mark[bad == 0])
	fmt.Printf("     共享标量读改写用 Mutex/atomic（上面 %d/200、%d/200 两路）；裸共享 map 写是 fatal 不是 race（d14 TestConcurrentMapWrites）。\n", aN, mN)

	hdr("6. 收口：交 W56")
	fmt.Println("  · W55 一条线走完：N+1 慢在哪（d13）→ 并行正确性（d14）→ 何时停（d15）→ 预算与部分失败（d16）→ 上限与公平（d17）→ 今天双证据收口。")
	fmt.Println("  · 红线口径全程没动：金额 *_cents、family_id 恒进每条查询与日志、跨家庭 404 不是 403、软删不进桶、业务面不自起计时器。")
	fmt.Println("  · W56（缓冲 + 重做，4 张）：d19 批量 flush 换吞吐的丢数据账；d20 幂等回放三个数不变；d21 失败补偿与人工修复入口；d22 阶段判据机器自测 + 费曼复盘。")
	fmt.Println("\n=== W55 d18 到此结束 ===")
	fmt.Println("明天 d19：缓冲写入 —— 攒 250 条一批落库 vs 逐条落的次数对照；进程在 flush 前崩，缓冲里那 N 条点名消失；WAL 补救版丢 0 条。")
}

