// =====================================================================
// W56 d20：重做与幂等回放 —— 同一事件重放 N 次，结果必须不变
//
// 这一天在解决什么问题：outbox 重投、cron 补跑、人工重试……同一个业务事件在真实系统里一定会被
// 投递多次。判据就一条：重放 1/3/10 次，三个下游计数 —— 通知未读数、动态流条数、due 注册行数 ——
// 必须一个都不动。幂等键是三元组 (source_system, source_id, kind)：少了 kind，同一家族的
// reminder 和 budget_alert 会互相吞；少了 source_system，两个面各自的 #42 号会撞车（S9 的教训）。
// 反例版不带键：三个数各自 ×N，当场对账。另验两件事：撤销后的重放被墓碑拦住（revoked 不被复活、
// 也不留新行），以及「动态流只由事件总线写入、聚合与未读数服务端只有一处」的红线在本模型里的形状。
// 业务面不自起计时器：due 行走注册/撤销（{code}.due.registered|revoked），不 sleep、不起 timer。
// 金额 *_cents 整数；family_id 恒进每一条写入与日志；本机无 PG，全部内存表 + 纯函数回放，两次跑字节一致。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d20
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

const (
	famA, famB = "fam-A", "fam-B"
	uDad       = "u-dad"
)

var fixedNow = time.Date(2026, 10, 19, 9, 0, 0, 0, time.FixedZone("Asia/Shanghai", 8*3600))

var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---- 事件：一个「周期记账到点」的领域事件（outbox 会重投的就是它） ----
type event struct {
	SourceSystem, SourceID, Kind string
	FamilyID, Title              string
	AmountCents                  int64 // 事件里的金额照旧 *_cents
}

func (e event) key() string { return e.SourceSystem + "|" + e.SourceID + "|" + e.Kind }

var evReminder = event{"recurring_rule", "monthly-2026-10", "reminder", famA, "周期记账到点提醒", 180000}

// ---- 三张下游表 + 幂等台账 ----
type noteRow struct {
	fam, recip, title, srcKey string
}
type actRow struct {
	fam, text string
}
type dueRow struct {
	fam, key, state string // state: registered | revoked（墓碑）
}

type store struct {
	notes    []noteRow
	acts     []actRow
	dues     []dueRow
	seen     map[string]bool // 幂等台账：key=(source_system, source_id, kind)；nil = 反例「无键」
	dupShots int             // 被去重吞掉的重投次数（现算）
}

func newStore(idempotent bool) *store {
	s := &store{}
	if idempotent {
		s.seen = map[string]bool{}
	}
	return s
}

// applyEvent：一个事件进来，三张表各写一格。幂等版按三元组去重；反例版来一次写一次。
// 动态流只由事件总线写入（这里就是这一处调用），未读数只在 unread() 一处口径。
func (s *store) applyEvent(e event) bool {
	if s.seen != nil {
		if s.seen[e.key()] {
			s.dupShots++ // 重投命中台账：不再写任何表 —— 撤销后的重放同样被这层拦住（墓碑=台账键+revoked 行）
			return false
		}
		s.seen[e.key()] = true
	}
	s.notes = append(s.notes, noteRow{e.FamilyID, uDad, e.Title, e.key()})
	s.acts = append(s.acts, actRow{e.FamilyID, "到点提醒：" + e.Title})
	s.dues = append(s.dues, dueRow{e.FamilyID, e.key(), "registered"})
	return true
}

// revoke：{code}.due.revoked —— 原地改 state 成墓碑，不物理删（软删可追溯的同一口径）。
func (s *store) revoke(e event) bool {
	for i := range s.dues {
		if s.dues[i].key == e.key() && s.dues[i].state == "registered" {
			s.dues[i].state = "revoked"
			return true
		}
	}
	return false
}

// unread：全项目唯一一处未读口径（家庭 + 收件人 + 未读；无键版的重投会把它翻倍）。
func (s *store) unread(fam, user string) int {
	c := 0
	for _, n := range s.notes {
		if n.fam == fam && n.recip == user {
			c++
		}
	}
	return c
}
func (s *store) actsCount(fam string) int {
	c := 0
	for _, a := range s.acts {
		if a.fam == fam {
			c++
		}
	}
	return c
}
func (s *store) duesCount(fam string) int {
	c := 0
	for _, d := range s.dues {
		if d.fam == fam {
			c++
		}
	}
	return c
}

// replayN：把同一事件投 n 次，返回三个数。
func replayN(n int, idempotent bool, ev event) (unread, acts, dues, dup int) {
	s := newStore(idempotent)
	for i := 0; i < n; i++ {
		s.applyEvent(ev)
	}
	return s.unread(ev.FamilyID, uDad), s.actsCount(ev.FamilyID), s.duesCount(ev.FamilyID), s.dupShots
}

func main() {
	hdr(fmt.Sprintf("1. 场景：一个「%s」事件（键三元组 %s，family_id=%s）会被 outbox 重投 N 次", evReminder.Kind, evReminder.key(), famA))
	fmt.Println("  三个下游计数：未读数（notification）· 动态流条数（activity，只由事件总线写入）· due 注册行数（到期中心，业务面不自起计时器）。")
	fmt.Printf("  事件金额 %d.%02d 元（*_cents 整数口径贯穿始终）。\n", evReminder.AmountCents/100, evReminder.AmountCents%100)

	hdr("2. ✅ 幂等版：重放 1/3/10 次，三个数并排 —— 必须全部不动")
	fmt.Printf("  %-10s %-10s %-10s %-10s %-12s %s\n", "重放次数", "未读数", "动态流条数", "due注册行", "被去重吞掉", "判定(三个数==投1次)")
	u1, a1, d1, _ := replayN(1, true, evReminder)
	allSame := true
	dupSum := 0
	for _, n := range []int{1, 3, 10} {
		u, a, d, dup := replayN(n, true, evReminder)
		dupSum += dup
		same := u == u1 && a == a1 && d == d1
		if !same {
			allSame = false
		}
		fmt.Printf("  %-10d %-10d %-10d %-10d %-12d %s\n", n, u, a, d, dup, mark[same])
	}
	fmt.Printf("  跨重放不变性：%s —— 「同一事件重放 N 次结果不变」成立；三轮共投 %d 次、被台账吞掉 %d 次、落库恒 3×1 行，全部只动了台账。\n", mark[allSame], 3*0+dupSum+3, dupSum)

	hdr("3. ❌ 反例：不带幂等键 —— 三个数各自翻倍，行数对账当场见光")
	fmt.Printf("  %-10s %-10s %-10s %-10s %s\n", "重放次数", "未读数", "动态流条数", "due注册行", "应得 vs 实得(未读)")
	badAll := false
	for _, n := range []int{1, 3, 10} {
		u, a, d, _ := replayN(n, false, evReminder)
		if u != u1 {
			badAll = true
		}
		fmt.Printf("  %-10d %-10d %-10d %-10d %d vs %d %s\n", n, u, a, d, u1, u, mark[u == n*u1])
	}
	fmt.Printf("  判读：无键版三个数严格 ×N（%s）—— 角标 3 条里只有 1 条是真事件，清不完的白角标、翻倍的动态流都是它；\n", mark[badAll])
	fmt.Println("  且 due 注册行也 ×N：同一个周期规则挂着 3 个计时器，到点重复通知（S9「多套定时器 = 多套真相」的并发版）。")

	hdr("4. 键的边界：三元组少一个维度都会出事故（判定由落库数现场比出，含一处故意的 ❌）")
	type kcase struct {
		desc  string
		evs   []event
		claim int // 应落库的事件数
	}
	cases := []kcase{
		{"同 (system,id)、kind 不同：reminder + budget_alert", []event{
			evReminder,
			{"recurring_rule", "monthly-2026-10", "budget_alert", famA, "支出超预算提醒", 2518000},
		}, 2},
		{"同 (id,kind)、system 不同：recurring_rule 与 import_job 各自的 #42", []event{
			{"recurring_rule", "42", "reminder", famA, "周期面的 42 号", 180000},
			{"import_job", "42", "reminder", famA, "导入面的 42 号", 90000},
		}, 2},
		{"三元组全同：真重投，该吞", []event{evReminder, evReminder}, 1},
		{"family 不同、三元组同：应两家各 1 行", []event{
			{"recurring_rule", "monthly-2026-10", "reminder", famA, "A 家的提醒", 180000},
			{"recurring_rule", "monthly-2026-10", "reminder", famB, "B 家的提醒", 180000},
		}, 2},
	}
	fmt.Printf("  %-52s %-10s %-10s %-14s %s\n", "场景", "投递数", "落库数", "应落库", "判定")
	for _, c := range cases {
		s := newStore(true)
		for _, e := range c.evs {
			s.applyEvent(e)
		}
		got := len(s.dues)
		fmt.Printf("  %-52s %-10d %-10d %-14d %s\n", c.desc, len(c.evs), got, c.claim, mark[got == c.claim])
	}
	fmt.Println("  第 4 行的 ❌ 是故意的：台账键只用题面三元组、不带 family_id 时，B 家的事件被 A 家的键吞掉 —— 这就是「跨家庭 404」")
	fmt.Println("  要靠 family_id 恒进每条查询的同一层防线：真实台账键 = (family_id, source_system, source_id, kind)。")
	sF := newStore(true)
	seenF := map[string]bool{}
	famGot := map[string]int{}
	for _, e := range cases[3].evs {
		k := e.FamilyID + "|" + e.key() // 四元组台账
		if seenF[k] {
			continue
		}
		seenF[k] = true
		sF.applyEvent(e)
		famGot[e.FamilyID]++
	}
	fmt.Printf("  并入 family 后：A 家 %d 行、B 家 %d 行 → 两家各 1 %s（同键三元组的真重投仍被吞：吞与不吞的差别只在键里有没有家）。\n",
		famGot[famA], famGot[famB], mark[famGot[famA] == 1 && famGot[famB] == 1])

	hdr("5. 撤销后的重放：墓碑拦住复活")
	s2 := newStore(true)
	s2.applyEvent(evReminder)
	revoked := s2.revoke(evReminder) // {code}.due.revoked：改 state，不物理删
	s2.applyEvent(evReminder)        // 撤销后 outbox 又投一次
	s2.applyEvent(evReminder)        // 再投一次
	states := []string{}
	for _, d := range s2.dues {
		states = append(states, d.state)
	}
	sort.Strings(states)
	fmt.Printf("  register → revoke(%s) → 重放 2 次：due 行数 = %d、状态序列 = [%s]\n", mark[revoked], s2.duesCount(famA), strings.Join(states, ","))
	fmt.Printf("  判定：行数仍 1 %s、状态保持 revoked %s —— 撤销不被重放复活；这条注册链的三步全是现算。\n",
		mark[s2.duesCount(famA) == 1], mark[len(s2.dues) == 1 && s2.dues[0].state == "revoked"])

	hdr("6. 收口")
	u10, a10, d10, _ := replayN(10, false, evReminder)
	fmt.Printf("  · 三个数并排的最终对账：幂等版 1/3/10 次全为 %d/%d/%d（不变 %s）；无键版 10 次涨到 %d/%d/%d（×10）。\n",
		u1, a1, d1, mark[allSame], u10, a10, d10)
	fmt.Println("  · 幂等键的正确形状：family_id + (source_system, source_id, kind)；到期/撤回走 due.registered|revoked，业务面不自起计时器。")
	fmt.Println("  · 动态流只由事件总线写入、未读数只有 unread() 一处、金额全程 *_cents —— 三条红线在重放 N 次后依然逐字成立，才叫幂等。")
	fmt.Println("  · 真环境复跑：停掉 outbox worker 十分钟再放开（制造重投），断言三张表行数与停投前一致；库里 UNIQUE (family_id, source_system, source_id, kind) 是最后防线。")
	fmt.Println("\n=== W56 d20 到此结束 ===")
	fmt.Println("明天 d21：失败补偿与人工修复入口 —— 投递失败有上限退避重试、pending 卡死清理、自动/人工判定表由状态机生成。")
}

