// 必须一个都不动。幂等键是三元组 (source_system, source_id, kind)：少了 kind，同一家族的
// reminder 和 budget_alert 会互相吞；少了 source_system，两个面各自的 #42 号会撞车（S9 的教训）。
// 反例版不带键：三个数各自 ×N，当场对账。另验两件事：撤销后的重放被墓碑拦住（revoked 不被复活、
// 也不留新行），以及「动态流只由事件总线写入、聚合与未读数服务端只有一处」的红线在本模型里的形状。
// 业务面不自起计时器：due 行走注册/撤销（{code}.due.registered|revoked），不 sleep、不起 timer。
// 金额 *_cents 整数；family_id 恒进每一条写入与日志；本机无 PG，全部内存表 + 纯函数回放，两次跑字节一致。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d20
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

const (
	famA, famB = "fam-A", "fam-B"
	uDad       = "u-dad"
)

