// =====================================================================
// W56 d21：失败补偿与人工修复入口
//
// 这一天在解决什么问题：并发与缓冲把写跑起来之后，剩下的都是「失败了怎么办」。三件事全用状态机说：
// ① 通知投递重试：指数退避（base 1s、×2、上限 maxTries=3），瞬断型第 3 次成功；持久型到顶即终态
//
//	failed —— 再跑几轮作业，failed 行的 attempts 一次都不再涨（增量为 0，现算）。
//
// ② 导出任务卡死 pending 的清理作业：扫描「pending 且 createdAt < now-30min」的行改 state，
//
//	行数对账逐态前后并排；第二轮扫描改动 0 行（清理本身幂等）。
//
// ③ 「哪些能自动重做、哪些必须人工」的判定表由程序按状态机规则表生成（rule 列表驱动，不是手抄
//
//	结论）：每行带今天场景里该 state 的实时计数。
//
// 时间全是虚拟时钟：fixedNow + 钉死 tick 偏移，程序不 sleep、不读墙上时间 → 两次跑字节一致。
// 人工修复入口的写操作同样带 client_request_id（重放不翻倍，d20）；每行恒带 family_id；
// 金额 *_cents；业务面不自起计时器 —— 到点投递走到期中心 nextAt，扫描作业也一样。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d21
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"time"
)

const (
	famA              = "aaaaaaaa-0000-4000-8000-000000000001"
	maxTries          = 3  // 投递重试上限（钉死）
	backoffBaseSec    = 1  // 指数退避基数：1s、2s、4s
	stuckThresholdMin = 30 // pending 超过这个时长视为卡死
)

var fixedNow = time.Date(2026, 10, 19, 9, 0, 0, 0, time.FixedZone("Asia/Shanghai", 8*3600))

var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---- ① 通知投递：notification_delivery ----
type delivery struct {
	id, fam, crid string
	attempts      int
	state         string // pending → retrying → delivered | failed（终态）
	nextAt        time.Time
	okAtAttempt   int // 模拟下游：第几次尝试成功；0 = 持久失败
}

var deliveries = []*delivery{
	{"nd-01", famA, "crid-nd01", 0, "pending", fixedNow, 3}, // 瞬断型：前两次失败、第三次成功
	{"nd-02", famA, "crid-nd02", 0, "pending", fixedNow, 0}, // 持久型：模板变量缺失，怎么投都失败
}

func backoffSec(try int) int { return backoffBaseSec << (try - 1) } // 1,2,4...

// runDeliveryTick：虚拟时钟的一个作业轮。到点(nextAt<=tick)且非终态的行才动 —— 终态 failed 不再重试。
func runDeliveryTick(dv *delivery, tick time.Time) bool {
	if (dv.state == "pending" || dv.state == "retrying") && !dv.nextAt.After(tick) {
		dv.attempts++
		if dv.okAtAttempt != 0 && dv.attempts == dv.okAtAttempt {
			dv.state = "delivered"
			return true
		}
		if dv.attempts >= maxTries {
			dv.state = "failed" // 到顶即终态：清理交给「人工修复入口」，不是继续自动撞
			return true
		}
		dv.state = "retrying"
		dv.nextAt = dv.nextAt.Add(time.Duration(backoffSec(dv.attempts)) * time.Second)
		return true
	}
	return false
}

