	for _, d := range deliveries {
		fmt.Printf("  %-8s %-8s %-10d %-10s ", d.id, d.state, d.attempts, d.nextAt.Format("15:04:05"))
		if d.okAtAttempt > 0 {
			fmt.Printf("前 %d 次失败（按 1s→2s 退避）→ 第 %d 次成功\n", d.okAtAttempt-1, d.okAtAttempt)
		} else {
			fmt.Printf("%d 次全失败 → 到顶 maxTries=%d，判终态 failed\n", d.attempts, maxTries)
		}
	}
