	delta := 0
	for k := 5; k <= 6; k++ {
		tick := fixedNow.Add(time.Duration(k*10) * time.Minute)
		for _, d := range deliveries {
			if runDeliveryTick(d, tick) {
				delta++
			}
		}
	}
