			n = post["expired"]
		default:
			n = st1["delivered"] + post["done"]
		}
		modeCN := map[string]string{"auto": "自动", "manual": "人工", "wait": "等待", "none": "终态"}[r.mode]
		if r.mode == "auto" {
			autoSlots++
		}
		if r.mode == "manual" {
			manualSlots++
		}
		fmt.Printf("  %-6s %-24s %-8s %-46s %d\n", r.scope, r.state, modeCN, r.action, n)
	}
	fmt.Printf("  档位汇总（遍历现数）：可自动 %d 档 · 必须人工 %d 档 · 等待/终态 %d 档（规则表共 %d 行）。\n",
