	fmt.Println("\n=== W56 d21 到此结束 ===")
	fmt.Println("明天 d22：S13 阶段判据机器自测（五条判据逐条落成可判定项）+ 费曼复盘问答清单 + 交 S14 的三件产物。")
}

func union(a, b []string) []string {
	set := map[string]bool{}
	for _, x := range a {
		set[x] = true
	}
	for _, x := range b {
		set[x] = true
	}
	var out []string
	for k := range set {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func sumMap(m map[string]int) (s int) {
	for _, v := range m {
		s += v
	}
	return
}

