	// 再跑两轮：终态行一次都不许再动（增量为 0，现算）
	delta := 0
	for k := 5; k <= 6; k++ {
		tick := fixedNow.Add(time.Duration(k*10) * time.Minute)
		for _, d := range deliveries {
			if runDeliveryTick(d, tick) {
				delta++
			}
		}
	}
	fmt.Printf("  ★ failed 是终态：追加 2 轮作业后动作行数 = %d %s（attempts 全部停在 %d/%d，自动重试到此为止，剩下的归人工口）\n",
		delta, mark[delta == 0], deliveries[0].attempts, deliveries[1].attempts)

	hdr("3. ② 导出卡死 pending 的清理作业：扫超时行改 state，行数对账")
	pre := countByStateJob()
	flipped, ids := sweepStuckPending(fixedNow)
	post := countByStateJob()
	fmt.Printf("  扫描条件：state=pending AND created_at < %s（now−%dmin，恒带 family_id）\n",
		fixedNow.Add(-time.Duration(stuckThresholdMin)*time.Minute).Format("15:04"), stuckThresholdMin)
	fmt.Printf("  本轮改动 %d 行：%v → pending→expired\n", flipped, ids)
	fmt.Printf("  %-10s %-8s %-8s %-8s\n", "state", "扫前", "扫后", "Δ")
	for _, k := range union(sortedKeysInt(pre), sortedKeysInt(post)) {
		fmt.Printf("  %-10s %-8d %-8d %-8d\n", k, pre[k], post[k], post[k]-pre[k])
	}
	flipped2, _ := sweepStuckPending(fixedNow)
	fmt.Printf("  第二轮扫描改动 %d 行 %s —— 清理作业幂等：expired 不再命中「pending」条件。\n", flipped2, mark[flipped2 == 0])
	fmt.Printf("  守恒核对：Σ扫后 %d == 总行数 %d %s（没造行也没吞行）。\n", sumMap(post), len(jobs), mark[sumMap(post) == len(jobs)])

	hdr("4. ③ 「能自动重做 / 必须人工」判定表：由状态机规则表现场生成")
	fmt.Printf("  %-6s %-24s %-8s %-46s %s\n", "面", "state", "处置档", "动作", "今天场景里的行数")
	autoSlots, manualSlots := 0, 0
	for _, r := range rules {
		n := 0
		switch {
		case r.scope == "投递" && r.state == "pending/retrying（未到上限）":
			n = st1["pending"] + st1["retrying"]
		case r.scope == "投递":
			n = st1["failed"]
		case r.scope == "导出" && r.state == "pending（未超阈值）":
			n = post["pending"]
		case r.scope == "导出" && r.state == "pending（超阈值=卡死）":
			n = flipped
		case r.scope == "导出" && r.state == "expired（已扫出）":
			n = post["expired"]
		default:
			n = st1["delivered"] + post["done"]
		}
		modeCN := map[string]string{"auto": "自动", "manual": "人工", "wait": "等待", "none": "终态"}[r.mode]
		if r.mode == "auto" {
			autoSlots++
		}
		if r.mode == "manual" {
			manualSlots++
		}
		fmt.Printf("  %-6s %-24s %-8s %-46s %d\n", r.scope, r.state, modeCN, r.action, n)
	}
	fmt.Printf("  档位汇总（遍历现数）：可自动 %d 档 · 必须人工 %d 档 · 等待/终态 %d 档（规则表共 %d 行）。\n",
		autoSlots, manualSlots, len(rules)-autoSlots-manualSlots, len(rules))
	fmt.Println("  表是 rules 列表遍历出来的：每行的「行数」列取自第 2/3 节现场状态分布 —— 换一批数据这张表跟着变。")
	fmt.Println("  人工修复入口的形状：POST /api/admin/{deliveries|exports}/{id}/redo，必须带新 client_request_id + 操作者 + 理由；")
	fmt.Println("  入口做的还是「重放事件」而不是改行（d20 的幂等键兜底）；审计日志恒带 family_id —— 修数据的手也要能被查出来。")

	hdr("5. 收口")
	fmt.Printf("  · 自动侧账：%d 个投递到顶判 failed、%d 个成功；清理扫掉 %d 行卡死 pending、第二轮 0 改动、Σ行数守恒 %d/%d。\n",
		st1["failed"], st1["delivered"], flipped, sumMap(post), len(jobs))
	fmt.Printf("  · 人工侧门：failed/expired 不进自动队列（第 2 节增量 %d 是证据），只走带 crid 的 redo 入口，留操作者与理由。\n", delta)
	fmt.Println("  · 业务面不自起计时器：到点重投与扫描都挂在到期中心的 nextAt 上；金额全程 *_cents；family_id 恒进每条查询与日志。")
	fmt.Println("  · 真环境复跑：把 nd-02 的模板变量修掉后从人工口重放一次，断言 delivered=2、attempts 不回退；发布前 kill -TERM 导出 worker，" +
		"下一轮清理作业应把孤儿 pending 扫成 expired（行数对账同第 3 节形状）。")
	fmt.Println("\n=== W56 d21 到此结束 ===")
	fmt.Println("明天 d22：S13 阶段判据机器自测（五条判据逐条落成可判定项）+ 费曼复盘问答清单 + 交 S14 的三件产物。")
}

func union(a, b []string) []string {
	set := map[string]bool{}
	for _, x := range a {
		set[x] = true
	}
	for _, x := range b {
		set[x] = true
	}
	var out []string
	for k := range set {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func sumMap(m map[string]int) (s int) {
	for _, v := range m {
		s += v
	}
	return
}

