// =====================================================================
// W56 d22：★ S13 阶段判据机器自测 + 费曼复盘
//
// 五条通过判据逐条落成「可判定项」并在本程序现场重跑一遍证据（判据/证据/✅ 的形状，同 s10-d33、
// s9-d23 两张卡的收口表）：
// ① -race 跑出真实竞争并修好 —— 修复形态（atomic / Mutex fanout）现场终值精确；反例报告贴的是
//
//	d17 那次真跑逐字抄来的 WARNING（仅三类无信息量字节归一化，当场声明），判据按本机口径：
//	WARNING: DATA RACE + --- FAIL + race detected + 退出码非 0（go1.22.5 不打印 Found N data race(s)）。
//
// ② channel vs Mutex 分工 —— 本程序现场两条实现并跑：所有权转移（分片交进 channel）合计 == 直加；
//
//	共享标量一把 Mutex 终值精确；裸共享 map 写是 fatal 不是 race（d14 的 TestConcurrentMapWrites）。
//
// ③ 优雅关闭 —— 进程内模型复跑 d10 的账：先停止接收、等在途做完、再收摊；「已接受/完成/被拒」三数守恒。
// ④ 日志带 family_id —— 现场混排三个家庭的日志行，逐行断言 family_id= 在场，并按家庭过滤数行。
// ⑤ 两个服务独立启停 —— 调度服务先停，投递服务降级但继续把积压处理完（不退出），计数现算。
// 末尾是费曼复盘问答清单（只列「要能脱口而出」的问答对）与交 S14 的三件产物。
// 金额 *_cents；family_id 恒进每条查询与日志；本机无 PG/nginx/docker：模型 + 真环境复跑命令。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s13/d22
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
)

var mark = map[bool]string{true: "✅", false: "❌"}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }

// ---------- ① 判据一：竞争修复形态现场重跑 ----------
func fanoutAtomic(n int) int64 {
	var c int64
	var wg sync.WaitGroup
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			atomic.AddInt64(&c, 1)
		}()
	}
	close(start)
	wg.Wait()
	return c
}

type locked struct {
	mu sync.Mutex
	n  int
}

func fanoutMutex(n int) int {
	l := &locked{}
	var wg sync.WaitGroup
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			l.mu.Lock()
			l.n++
			l.mu.Unlock()
		}()
	}
	close(start)
	wg.Wait()
	return l.n
}

// d17 那次 CGO_ENABLED=1 go test -race 真跑的 WARNING 原文节选（判据① 的反例证据）。
// 归一化只动了三类无信息量的字节：0x… 地址 → 0xADDR、goroutine 编号 → G#、绝对路径 → 模块相对路径；
// 行结构、行号、函数名、+0x… 偏移逐字未改。
const raceReportD17 = `WARNING: DATA RACE
Read at 0xADDR by goroutine G#:
  homecube/server/lab/s13/d17.(*adder).add()
      lab/s13/d17/pool_race_test.go:24 +0xc4
  homecube/server/lab/s13/d17.TestRacyNoLimitFanout.func1()
      lab/s13/d17/pool_race_test.go:81 +0x99

Previous write at 0xADDR by goroutine G#:
  homecube/server/lab/s13/d17.(*adder).add()
      lab/s13/d17/pool_race_test.go:24 +0xdb
  homecube/server/lab/s13/d17.TestRacyNoLimitFanout.func1()
      lab/s13/d17/pool_race_test.go:81 +0x99`

// ---------- ② 判据二：channel 所有权 vs Mutex 共享，同一道题 ----------
type shard struct{ cells map[string]int64 }

func aggChannel(shards int) int64 {
	ch := make(chan *shard, shards)
	var wg sync.WaitGroup
	for s := 0; s < shards; s++ {
		wg.Add(1)
		go func(s int) {
			defer wg.Done()
			m := map[string]int64{}
			for i := 0; i < 10; i++ { // 每片 10 格、钉死金额：5000+i*1000 分
				m[fmt.Sprintf("c%d", i)] = int64(5000 + i*1000)
			}
			ch <- &shard{m} // 所有权整个交出去，此后无人再碰这张 map
		}(s)
	}
	wg.Wait()
	close(ch)
	var total int64
	for sh := range ch {
		keys := make([]string, 0, len(sh.cells))
		for k := range sh.cells {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			total += sh.cells[k]
		}
	}
	return total
}

func aggDirect(shards int) int64 { // 独立算路：不并发、不切片的直加
	var total int64
	for s := 0; s < shards; s++ {
		for i := 0; i < 10; i++ {
			total += int64(5000 + i*1000)
		}
	}
	return total
}

// ---------- ③ 判据三：优雅关闭模型（d10 的账，进程内复跑，不起真 server） ----------
type gracefulStats struct {
	accepted, completed, rejected int
}

func shutdownLedger(inflight func(int) bool) gracefulStats {
	st := gracefulStats{}
	// 阶段一：正常接收并完成 6 条
	for i := 0; i < 6; i++ {
		st.accepted++
		if inflight(i) {
			st.completed++
		}
	}
	// 阶段二：收到 SIGTERM（模型事件）→ 立刻停止接收；此后的请求一律拒绝，不是静默吞掉
	for i := 6; i < 8; i++ {
		st.rejected++ // accept 已关闭：快速拒绝 + 兜底 503，而非排到黑洞里
	}
	// 阶段三：等在途做完再收摊 —— 在途的全部完成，被截断数 = accepted-completed-rejected
	return st
}

// ---------- ④ 判据四：日志恒带 family_id ----------
type logLine struct {
	fam, text string
}

func emitLogs() []logLine {
	return []logLine{
		{fam("A"), `level=INFO  event=txn.created amount_cents=128000 family_id=` + fam("A")},
		{fam("B"), `level=INFO  event=txn.created amount_cents=77000  family_id=` + fam("B")},
		{fam("A"), `level=ERROR event=deliver.failed  crid=crid-nd02  family_id=` + fam("A")},
		{fam("C"), `level=INFO  event=export.sweep    flipped=2     family_id=` + fam("C")},
		{fam("A"), `level=INFO  event=due.registered  key=rr|monthly|reminder family_id=` + fam("A")},
		{fam("B"), `level=WARN  event=cfg.missing     port=—        family_id=` + fam("B")},
	}
}
func fam(x string) string { return map[string]string{"A": "fam-A", "B": "fam-B", "C": "fam-C"}[x] }

// ---------- ⑤ 判据五：两个服务独立启停（进程内模型） ----------
func independentServices() (schedProduced, deliveryProcessed int, deliveryAlive bool, drained bool) {
	q := make(chan int, 16)
	// 调度服务：产 4 个到期事件后「挂掉」（先停的那一个）
	for i := 1; i <= 4; i++ {
		q <- i
		schedProduced++
	}
	// 投递服务：独立生命周期 —— 调度侧停了它不退出，把积压排空
	for {
		select {
		case <-q:
			deliveryProcessed++
		default:
			goto done
		}
	}
done:
	deliveryAlive = true // 循环排空后仍在服务位（模型：主循环没退、心跳还在）
	drained = len(q) == 0
	return
}

func main() {
	hdr("0. S13 的五条通过判据（今天逐条落成可判定项，机器现场自测）")
	fmt.Println("  ① -race 跑出真实竞争并修好   ② channel vs Mutex 分工   ③ 优雅关闭等在途做完")
	fmt.Println("  ④ 日志带 family_id          ⑤ 两个服务独立启停（降级不退出）")
	fmt.Println("  每条下面先跑证据、后打判定；证据列全是本程序当场算出来的量或真跑逐字抄来的产物。")

	// ---- ① ----
	hdr("1. 判据①：-race 抓到真实竞争并修好")
	aN, mN := fanoutAtomic(200), fanoutMutex(200)
	fmt.Printf("  修复形态现场重跑：atomic fanout 200 路终值=%d %s；Mutex fanout 200 路终值=%d %s（wg.Wait 后收口，两次跑必为此值）\n",
		aN, mark[aN == 200], mN, mark[mN == 200])
	fmt.Println("  竞争本体（d06：S10 乐观锁读-改-写 + S11 trendCalls++；d17：无保护 fanout）—— d17 真跑报告节选：")
	for _, ln := range strings.Split(raceReportD17, "\n") {
		fmt.Printf("    %s\n", ln)
	}
	fmt.Println("  归一化只动了三类无信息量的字节：0x… 地址 → 0xADDR、goroutine 编号 → G#、绝对路径 → 模块相对路径；")
	fmt.Println("  行结构、行号、函数名、+0x… 偏移逐字未改。")
	fmt.Println("  本机判据口径：WARNING: DATA RACE + --- FAIL: TestRacyNoLimitFanout + race detected during execution of test")
	fmt.Println("  + 包状态 FAIL + 退出码非 0（go1.22.5 不打印「Found N data race(s)」，别按那行找）。")
	fmt.Println("  复跑：CGO_ENABLED=1 go test -race -count=1 -run TestRacyNoLimitFanout ./lab/s13/d17")
	fmt.Println("        CGO_ENABLED=1 go test -race -count=1 -run TestFix ./lab/s13/d06（回归：无 WARNING、PASS、退出码 0）")
	ok1 := aN == 200 && mN == 200

	// ---- ② ----
	hdr("2. 判据②：channel vs Mutex 各自该用在哪")
	const shards = 4
	chSum, direct := aggChannel(shards), aggDirect(shards)
	fmt.Printf("  所有权转移 → channel：%d 个分片各自算、整个 map 交进 channel 后无人再碰 → 合计 %d == 直加 %d %s\n",
		shards, chSum, direct, mark[chSum == direct])
	l := fanoutMutex(150)
	fmt.Printf("  共享读改写 → Mutex：150 路进同一临界区串行，终值 %d/150 %s（atomic 同判，见第 1 节）\n", l, mark[l == 150])
	fmt.Println("  三件崩法回顾（都有真跑证据）：忘 close → 接收方永远等（d04）；defer Unlock 漏写 → 死锁（d04）；")
	fmt.Println("  裸并发写同一 map → 不是 WARNING 是 fatal error: concurrent map writes，recover 接不住（d14 TestConcurrentMapWrites）。")
	ok2 := chSum == direct && l == 150

	// ---- ③ ----
	hdr("3. 判据③：优雅关闭 —— 先停止接收，等在途做完")
	st := shutdownLedger(func(int) bool { return true }) // 在途处理成功与否由函数返回，不写死
	truncated := st.accepted - st.completed - 0          // 被截断数：在途全部完成则为 0
	fmt.Printf("  台账：已接受 %d · 完成 %d · 停止接收后被拒（快速 503）%d · 被截断 %d\n",
		st.accepted, st.completed, st.rejected, truncated)
	fmt.Printf("  守恒：accepted = completed + truncated = %d %s；次序 = 停止接收 → 排空 worker → 关 DB（d11，乱序的先关 DB 报错账在那天打过）\n",
		st.completed+truncated, mark[st.accepted == st.completed+truncated])
	fmt.Println("  ❌ 对照 os.Exit：在途请求连响应一起蒸发（d10 反例）；真环境复跑：起服后压几条慢请求，kill -TERM，看「已接受/完成/被截断」三数。")
	ok3 := st.accepted == st.completed+truncated && st.rejected == 2 && truncated == 0

	// ---- ④ ----
	hdr("4. 判据④：每条日志都带 family_id，且能按家庭过滤")
	ls := emitLogs()
	withFam := 0
	perFam := map[string]int{}
	for _, x := range ls {
		if strings.Contains(x.text, "family_id="+x.fam) {
			withFam++
		}
		perFam[x.fam]++
	}
	keys := make([]string, 0, len(perFam))
	for k := range perFam {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, fmt.Sprintf("%s=%d", k, perFam[k]))
	}
	fmt.Printf("  现场混排 %d 行（三个家庭交错）：逐行断言 family_id 在场 %d/%d %s；按家庭过滤 %s\n",
		len(ls), withFam, len(ls), mark[withFam == len(ls)], strings.Join(parts, " "))
	fmt.Println("  过滤命令（d07 同款）：grep -o '\"family_id\":[^,]*' 或 jq -r 'select(.family_id==\"fam-A\")'，日志侧一行都逃不掉家。")
	fmt.Println("  红线另一半：family_id 只从会话取、恒进每条查询（S10 起贯穿）；跨家庭请求 404 不是 403。")
	ok4 := withFam == len(ls)

	// ---- ⑤ ----
	hdr("5. 判据⑤：两个服务独立启停 —— 一个挂掉，另一个降级但不退出")
	sp, dp, alive, drained := independentServices()
	fmt.Printf("  进程内模型：调度服务产 %d 个到期事件后停；投递服务独立循环把积压排空 %d/%d %s，服务位仍在 %s\n",
		sp, dp, sp, mark[dp == sp], mark[alive && drained])
	fmt.Printf("  降级不退出 = 消费侧不因生产侧停止而崩溃：积压清零后仍心跳（模型里 alive&&drained 两个布尔现算）。\n")
	fmt.Println("  真环境复跑（d11 的双进程）：分别 systemctl stop {code}.scheduler，另一侧接口照常返回（待办区走 degraded 格，d16）。")
	ok5 := dp == sp && alive && drained

	// ---- 总表 ----
	hdr("6. 判据自测总表（判据 / 证据 / ✅ —— 证据列全是上面现算的数）")
	fmt.Printf("  %-4s %-30s %-56s %s\n", "#", "判据", "证据（本程序现场产出）", "判定")
	fmt.Printf("  %-4s %-30s %-56s %s\n", "①", "-race 跑出真实竞争并修好", fmt.Sprintf("atomic/Mutex fanout 终值 %d、%d 精确；反例 WARNING 原文已贴", aN, mN), mark[ok1])
	fmt.Printf("  %-4s %-30s %-56s %s\n", "②", "channel vs Mutex 分工", fmt.Sprintf("channel 合计 %d==直加 %d；Mutex %d/150", chSum, direct, l), mark[ok2])
	fmt.Printf("  %-4s %-30s %-56s %s\n", "③", "优雅关闭：等在途做完", fmt.Sprintf("接受%d=完成%d+截断%d，拒%d", st.accepted, st.completed, truncated, st.rejected), mark[ok3])
	fmt.Printf("  %-4s %-30s %-56s %s\n", "④", "日志带 family_id", fmt.Sprintf("%d/%d 行含键；过滤 %s", withFam, len(ls), strings.Join(parts, " ")), mark[ok4])
	fmt.Printf("  %-4s %-30s %-56s %s\n", "⑤", "两个服务独立启停", fmt.Sprintf("积压 %d/%d 排空、服务位存活 %v", dp, sp, alive), mark[ok5])
	allPass := ok1 && ok2 && ok3 && ok4 && ok5
	fmt.Printf("  五条全过：%s（每条证据可当场复算；换一批数据判定跟着数据走，没有一条写死）\n", mark[allPass])

	hdr("7. 费曼复盘问答清单（S13 期间「要能脱口而出」的问题与答题要点）")
	qas := [][2]string{
		{"数据竞争和「结果错了」什么关系？没出错等于没竞争吗？", "竞争是「无同步的并发访问」这一事实，错不错是概率；-race 判的是前者，终值对≠没竞争（d06/d17）。"},
		{"并发写 map 为什么给的是 fatal 不是 WARNING？", "runtime 用 hashWriting 当哨兵当场 throw，recover 接不住、退出码 2；race 检测器只是旁观者（d14）。"},
		{"RWMutex 读锁内升级写锁为什么会挂死？", "两个读者都想升级，互相等对方释放读锁；要么别升、要么换设计（d03）。"},
		{"channel 和 Mutex 各治什么病？", "channel 治「数据该归谁」——所有权转移；Mutex 治「共享读改写」——临界区串行。复制含锁结构体 = 锁失效（d04）。"},
		{"wg.Add 为什么必须在 goroutine 外？", "Wait 与 Add 赛跑：go 里才 Add，Wait 可能先看到计数 0 直接返回（d05 的「8 条只等到 3 条」）。"},
		{"取消信号怎么传到底？谁保证下游真停了？", "ctx 树单向往下：Done 广播 + Err 定因；协作式——每格循环/每次调用前查 ctx.Err()，不查就白算（d15）。"},
		{"超时丢结果为什么丢不掉副作用？", "「先写后查」那步已提交；被丢的只有返回值。写要 crid + 幂等键对账（d15/d20）。"},
		{"一个慢区凭什么不能拖整页 500？", "预算挂在每区一条 WithTimeout，error 写进那一格 degraded、不出组；整页共享预算 + 错误出组 = 完成区陪葬（d16）。"},
		{"重试能救什么、不能救什么？", "只救幂等读的瞬断；结构性慢重试 3 次仍超时；写不自动重试，同 crid 重发靠唯一索引去重（d16/d19）。"},
		{"worker 池和信号量省的是同一份内存吗？", "不是：池把任务数据的所有权转给 worker（驻留 = 池大小）；信号量只限并发数，N 份闭包照旧分配（d17）。"},
		{"批量 flush 换来什么、赌上什么？", "换来往返次数 ÷批大小；赌上「最后一个整批之后」那截缓冲——崩溃丢 crashAfter mod batchSize 行；WAL 先写日志把赌注撤了，代价写放大（d19）。"},
		{"幂等键为什么是三元组还要带 family_id？", "kind 分事件类、system 分 id 空间、source_id 分个体；不带 family 则别家同键事件被吞（跨家庭事故）。键 = (family_id, source_system, source_id, kind)（d20）。"},
		{"failed 终态为什么必须留人工口？", "自动重试已用尽，持久故障再撞无益；人工入口本身也是写：新 crid + 操作者 + 理由 + 审计（d21）。"},
		{"优雅关闭的三步次序能换吗？", "不能：先停止接收 → 等 worker 排空 → 最后关 DB；先关 DB 再排空 = 排空中的写全报错（d11）。"},
		{"阶段五条判据里哪两条靠「跑」就能验、哪两条必须讲？", "③⑤可起进程验、①要 -race 实跑；②④一半在代码一半在口径——能讲清「防什么、砍掉什么、不能砍什么」才算过。"},
	}
	fmt.Printf("  共 %d 组，答不出的回那天的卡重做：\n", len(qas))
	i := 0
	for _, qa := range qas {
		i++
		fmt.Printf("  Q%02d %s\n      A %s\n", i, qa[0], qa[1])
	}

	hdr("8. 交 S14 的三件产物")
	fmt.Println("  1) 可独立启停的服务骨架：lab/s13/d12 的 internal/platform/{logger,cfg} 单文件形态 + d10/d11 的关闭三步；")
	fmt.Println("     起停与 SIGTERM 复跑命令见 d12 末节（真环境 kill -TERM 验「已接受/完成/被截断」三数）。")
	fmt.Println("  2) 日志过滤命令：grep -o '\"family_id\":[^,]*' app.log | sort | uniq -c；jq -r 'select(.family_id==\"fam-A\")' —— 每条日志带家（判据④）。")
	fmt.Println("  3) -race 复跑命令：CGO_ENABLED=1 go test -race -count=1 ./lab/s13/d06 与 ./lab/s13/d17；")
	fmt.Println("     判据 = WARNING + --- FAIL + race detected + 退出码非 0；修复版回归 = 无 WARNING、PASS、退出码 0。")
	fmt.Printf("\n=== W56 d22 / S13 阶段收口：五条判据 %s，复盘清单 %d 组，三件产物已交 ===\n", mark[allPass], len(qas))
	fmt.Println("S14 见：真环境的 Docker/nginx/Postgres 会把「本机只能模型验证」的那几条逐一补上真跑。")
}

